/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100914-5","meetingId":"h22-cm09","date":"2010年9月14日","dateIso":"2010-09-14","committee":"総務委員会","time":"午後１時０２分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"完全に地上デジタル放送に移るということで、それに１００％対応できるようにということなんだと思いますが、今、どの程度ということの把握はどこがどのようになさっているのかなということと、デジサポ東京中央にいろいろお願いしていますが、ここはそういうものを把握するようにしているのかどうか。さもないといつまでたってもきりがないということになりかねないのではないですか。","respondent":"久保田行財政改革担当課長","answer":"それで、品川区につきましては、細かい数値というものはございませんが、私どもの方で把握しているものがケーブルテレビへの加入世帯といったもので、いわゆる地上デジタル放送への切り替えが済んでいるものということで考えておりまして、現在のところ、普及率につきましては。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"今のお話だと、ケーブルテレビの皆さんはもうほとんどがデジタルのチューナーを買うなり何なりして対策が済んだというふうにも聞きとれるんですけど、それはそうではないんですか。","respondent":"久保田行財政改革担当課長","answer":"説明が足りませんでした。その８４.５％の方につきましては、地上デジタル放送を見る環境が整っているですので、あとはご自分の方でチューナーを買うなり、地上デジタル放送対応のテレビを買っていただければ、アンテナ工事等の必要なく地上デジタル放送が見られるです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"我々品川区は、ケーブルテレビとは全く無関係ではないわけですから、その意味で、それ以外のところについての対応・対策等も、ケーブルテレビとの間の情報交換等もしていただいて、そういうところの対策はどうするんだと。最終的に言ってくるということになると、区に言ってきたりということになるかもしれないことなんだろうと思うので、ぜひ、そこら辺の把握に努めてもらいたいと思うんです。","respondent":"久保田行財政改革担当課長","answer":"それに合わせまして、南東京ケーブルテレビの方も同じように、例えば相談会等を各地区で実施をしたりしておりまして、そうした意味で、全区的に普及が図れるように関係機関と連携して取り組んでいるというところでございまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"今の質問に関連するんですけれども、全国の方は８３.８％、５月現在だと思うんですけれども、この普及率がとても低いということで、一部に、今現在のアナログ放送、来年７月２４日で停止するのを先に延ばしたほうがいいのではないかという意見もかなり出てきているんですが、そこには来年７月２４日のアナログ放送終了までに、見られなくなる方がかなり残されるのではないかという予想なんですね。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明いたしましたが、現在ケーブルテレビでは８４.５％、区民チャンネルの視聴が可能という数値が出ておりますので、こうした中で、あとは皆さんに端末機の方で対応していただきたいということで、私どもとしましては、広報紙、または巡回相談等を使って。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"提案","question":"それでどういうところが残されていくのかというのをしっかり把握しながら対策をとることが大事じゃないかと思うんです。実際に所得の少ない方々に対するチューナーの貸し出し等もあるんだけれども、思い切ってそういう対策なんかも対象を考え直すとか、実際にどういうところが残されそうかということをもっと調べて、正確に把握して必要な対策をとるということが必要だと思うんですが、どうですか。","respondent":"久保田行財政改革担当課長","answer":"民生委員協議会等にも伺って、地上デジタル放送切り替えということの説明をさせていただいて、チラシを配りまして、それぞれの民生委員の方が各高齢者のご家庭を訪問した際に聞かれたときには、答えられる範囲でご説明をしていただいて。","voiceIndex":13,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、今実際に高齢者は、余裕のある人もいるでしょうけれども、余裕のない人もいっぱいいて、チューナーそれ自体も躊躇してしまうという方々は多いと思うんですよ。そういう方々にどうするかというのを、もっと地方自治体の側から発信していただきたいと思います。これは要望として、何か考えていることとかがあったら伺いたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"四つに分かれている説明の中で、２番目のこれは、いわゆる区が持っている建物によって電波障害が生じた部分で、ケーブルテレビに入っている人が約４,６００世帯ということで、この人たちについては戸別訪問をして説明をしてきた。それから４番目は、いざというときは、ケーブルテレビに入っていると平成２７年までアナログで見られますよという説明だと。こういうふうに受けとっていいんですか。","respondent":"久保田行財政改革担当課長","answer":"今、委員の方からご指摘ございましたように、２番については、区が原因となって電波障害を起こしている方に対して、責任をもってご説明をするというものでございまして。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"そうすると、極端に言うと、４番を適用していくと、ケーブルテレビに入れば４年間延長されるというふうに考えて、ケーブルテレビに入っていれば、今見ているテレビで、地デジではなくてアナログのテレビでも延長ができますよ、だからケーブルテレビに入ったらどうですかという商売の仕方もあるのではないのかなというふうに受けとれるんだけれども、そういうこともある。その辺をちょっと聞かせてください。","respondent":"久保田行財政改革担当課長","answer":"これの周知につきましても、ケーブルテレビの方で折に触れて、今加入されている方に対して周知を図っているというものでございまして、あわせまして、２番の電波障害対策の世帯の方への周知の中でも。","voiceIndex":19,"id":"exchange-008"},{"speaker":"林委員","kind":"意見","question":"周知を図るということと、各家庭で工事を済ませて対応が済んだということと、何となく自治体でやる仕事があやふやになっているんだけど、その工事というか、地デジを買ってもらうか、ケーブルテレビに来てもらって工事をやってもらうか、自治体はアナウンスだけをしていくということでいいわけですね。","respondent":"久保田行財政改革担当課長","answer":"ただ、期限が平成２７年３月末までですので、それまでの間に地上デジタル放送対応の端末機を買わないと、平成２７年３月の時点以降は見られなくなるです。ちょっと期間が延びたというようなことでお考えいただければと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"林委員","kind":"確認","question":"地上放送だけを見る、それから品川チャンネルだけを見るというだけの、ケーブルテレビにはお金は払わない、会員になった会費というのは払わないで、継続してテレビを見ている人と、ケーブルテレビの会員になって、毎月の会費をケーブルテレビに払っていくという、二つの種類の方法があるんだけど、この約４,６００世帯というのは、両方インクルーズされているわけですか。","respondent":"久保田行財政改革担当課長","answer":"この２番の約４,６００世帯の方というのは、区の施設が原因で電波障害を起こしている方で、既にケーブルテレビの回線がそこに引かれていまして、ケーブルテレビを使ってテレビを見ているという方ですので、この約４,６００世帯の中には、例えば有料チャンネル。","voiceIndex":23,"id":"exchange-010"},{"speaker":"林委員","kind":"意見","question":"最後に、この委員会では所管していないかもわからないんだけれども、この事業によってテレビがどのぐらい廃棄されるのかというのは、区としてはつかんでおく必要があると思いますけれども、そんなことは家庭でいろいろあるんだから面倒見ていられない、計算していられないと言ってしまうのか、それこそ平成２７年までには全部テレビが変わらなければならないということになると。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"大きく２点ほど質問させていただきたいんですが、先ほどの電波障害対策のところで、アナログの時代に電波障害ということが多く発生してきたかと思うんですが、その中で、地デジ対応ということで、様々な説明を４,６００世帯の方にされるということですけれども、そもそも電波障害の考え方、これをちょっと確認しておきたいなと思うんです。","respondent":"久保田行財政改革担当課長","answer":"現に、私ども品川区としましても、南東京ケーブルテレビとも連携しまして、区内で電波障害の状況を確認しまして、区内３０カ所で調査をしたところ、電波障害というものはなかったという結果を受けております。","voiceIndex":26,"id":"exchange-012"},{"speaker":"浅野副委員長","kind":"質問","question":"２点目にデジアナ変換なんですけれども、私の記憶にあるのは、機械だけで数千万円というふうに報道されていた時代があるんですね。ものは安くなるとはいえども、かなりのコストがかかるのではないかということは、ケーブルテレビの事業にも影響する危険性もあるので、どのぐらいの初期投資がかかって、ランニングコストはどのぐらいかかるのかというのをちょっとお伺いしたいです。","respondent":"久保田行財政改革担当課長","answer":"チャンネル設定につきましても、基本的には今までどおりに見られるというふうには伺っておりますが、デジアナ変換をやった際にどうなるかということもあると思いますので、そうした場合には、総務省からの通知に従いまして。","voiceIndex":28,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"先ほど課長からお話があった、過剰サービスという中でも、それは品川区民チャンネルの促進とか、品川区の情報を見ていただくという見地から、区有施設等が原因で起きる電波障害に対して、区の予算を使って動くということならば、品川区全体が見られないということならば、それは逆に総務省が責任としてお金を出すべき話ということになると思うんですが、その辺の整合性というか。","respondent":"久保田行財政改革担当課長","answer":"私どもとしては、区の責任をもってきちんと対応していくですし、また、経費の問題等もあるかと思いますけれども、私どもは、設置工事の段階で一定程度の将来的なメンテナンス代も含めた形でケーブルテレビと契約しておりますので。","voiceIndex":30,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"その点ですが、アナログ放送が地上デジタル放送に変わったときには、区の方で、電波障害に対してもきちんとこちらの方で対策をとりますよという書面というのはあって、今、動いているわけですか。それともそうではなくて、こういう状況に変わったから、区有施設の影響でなっているから、区民サービスとして今回こういう周知事業をするという、どちらなんですか。","respondent":"久保田行財政改革担当課長","answer":"デジタル放送に切り替わった後も対応をしますという形で何か書面を取りかわしたということはございませんで、私ども、今回の切り替えに合わせまして、区の方針として、このままケーブルテレビを活用して電波を送るという、その旨を周知しているです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"内容をお聞きしたいと思います。それからもう一つは、区役所の相談コーナー、今もそこでやっておられましたが、一応９月で終了を１カ月延長するということのようなんですけれども、参考までに、９月末までに相談に来られた方はどの程度いらっしゃるんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"広報しながわですが、今回の地デジの巡回相談につきましては、基本的に限られた紙面ということもありますので、日程のご案内を中心に書かせていただくということでございまして、あとは、デジアナ変換も行いますというのを数行載せする予定です。","voiceIndex":34,"id":"exchange-016"},{"speaker":"堺委員","kind":"確認","question":"そうすると、今ご答弁があったんだろうと思うんだけれども、２番目に関連して、この約４,６００世帯に戸別訪問して説明に伺うんですが、これはいきなり行ってしまうんですか。あるいは事前にこういう人たちに対して、「この期間に説明に伺います」という何らかの広報をされているんですか。それをちょっと確認したかったんです。ないならないでいいんですけど、ちょっとその辺をお願いします。","respondent":"久保田行財政改革担当課長","answer":"今のところ、戸別訪問をいたしまして説明するということで、事前に電話をかけて行くかどうか、細かいところはありますけれども、直接お伺いをして、いらっしゃらなければお手紙を置いて注意を喚起するといった形で、その後さらに詳しいことを知りたい方につきましては。","voiceIndex":36,"id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"要するに、半年間という期間限定の中で４,６００世帯を回ろうというのですから、区の職員の人が当たるのですか。あるいは総務省の関係者、あるいはどこかの委託先が当たるのですか。要するに、区の職員の関係者が６カ月間で４,６００世帯を当たるとなると、大変な作業だなという心配から、やるなら事前に通告したほうが効率的かなと素直に思ったので、だれが４,６００世帯に当たるのですか。","respondent":"久保田行財政改革担当課長","answer":"ちょっと説明が足りませんでしたが、こちらにつきましては、私ども職員が直接ということではなくて、業者の方に委託をしてやっていきたいと思います。","voiceIndex":38,"id":"exchange-018"},{"speaker":"林委員","kind":"意見","question":"今、最後に説明があった研究会というか研修会の話で、ＣＳＲのお知らせなんかも、一般の人が参加していいものなのか、いわゆるＣＳＲの会員になっている企業の人たちだけの研修会というかそういうものなのかはっきりしなくて、入っていいのか、それとも内々の会合で、我々が行くのも考えなければいけないのかと、そういう周りからの反応があるという話は、今、中の「よかったよ」という感想は聞いたんだけど。","respondent":"伊勢総務課長","answer":"今回の９月７日の講演会と事例発表会ですけれども、基本的には２２社、区役所も含めてですが、協議会の方々に来ていただくということを主眼としておりました。それからもう一つは、企業の社会貢献活動ですので、所管を通じて東商品川支部の方に情報提供をしています。","voiceIndex":44,"id":"exchange-019","title":"議員研修会の内容と所要時間"},{"speaker":"林委員","kind":"意見","question":"運営の資金管理なんかも相当、企業メセナのときは１社から何十万円、あるいは何百万円というお金が出ていたんだけれども、この辺の会費と、会そのものの運営についての財政的なものについて、ちょっと説明してください。","respondent":"伊勢総務課長","answer":"講演会につきましては、区と協議会の共催ということでやっております。今後、情報発信だけではなくて具体的な活動をやるというようなことになれば、その段階で会員の方々とご相談させていただこうと考えています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"そんな中で、区長の言葉の中にも込められているし、企業との連携、コラボレーションをつくってやっていくということになっているんだけれども、今の話だと、会費は要らないよというと、企業にとってはちょっとつながりが薄いような感じを持つのではないですか。","respondent":"伊勢総務課長、市岡総務部長","answer":"こちらのいわゆる社会法人、財団法人の、税が軽減されるとかというのがありますけれども、これは企業と事業所ということで、現在は全部株式会社ということで。実はＩＳＯ２６０００という、企業が社会的責任を果たすための認証制度みたいなものが、今年中にスタートするというような報道もありましたけれども、そういう意味ではいろいろな連携の仕方、先ほど社会的企業の話もありましたけれども。","voiceIndex":48,"id":"exchange-021"},{"speaker":"林委員","kind":"意見","question":"ただ、私は企業の場合は、手弁当というよりも、財政も受け持ってくれるということを、頭から「おい、金出せ」というのは失礼な言い方になるかもしれないけれども、ゆくゆくは区というところから離れてＣＳＲ推進協議会という団体が区民に対していろいろな活動をしていけるというのを目指していくべきだと私は思うんです。お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-022"},{"speaker":"土井委員","kind":"質問","question":"そうなりますと、今回できましたしながわＣＳＲ推進協議会が事務局的に対応ができるようにぜひ進めてもらって、そこが、場合によってはこれは教育委員会とつながったほうがいいだろうとか、これは何とつながったほうがいい、これは商工の方とつながったほうがいいとか様々なものがあると思うので、そういう仕分けができるような、ちゃんと回るようにしていく仕組みにしていかないとと思うんですけれども。","respondent":"伊勢総務課長","answer":"ですから、今後事務局的対応を企業の方でどこまでというのは、お話を伺うと結構積極的なお考えを持っている方も大勢いらっしゃいますので、この辺はこれから各企業の中心になってやる方と相談しながら、どういうふうに運営していくか、お金のことも含めて。","voiceIndex":52,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"すばらしい取り組みだと思いますので、ぜひ発展させていただきたいと思います。品川区が中心となって、そこで事業をなされる企業、特に品川区との連携がまず第一だと思いますが、ここにも書いてありますが、ぜひとも地域の区民をまじえて、さらなる広い連携を充実させて、何とかいい方向へ持っていってほしい。いろいろあると思いますが、大変だと思いますが、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-024"},{"speaker":"堺委員","kind":"意見","question":"これは１９社がそれぞれ事例紹介を掲載されているんだけれども、品川区として、何か区が独自に貢献する活動というのはやっていいのかいけないのか。やっていいとすれば、企業に依頼するのではなくて、品川区という組織、機関、団体もやっているよと。そういう方向もどうなのかなと思った。その辺の見解をちょっと、いかがなものなのかなと思ったんです。","respondent":"伊勢総務課長","answer":"それともちろん、全部で２２社あるんですけれども、一つの事業所として品川区も大変小さいんですけれども、一番最後に「品川区」と、そういうふうになっています。","voiceIndex":55,"id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"これはまさに、今おっしゃったようなことを区がやっていますというのを掲載してはいけないんですか。その辺ちょっと遠慮されているんでしょうか。何もないから、私はどうなのかなと思って聞いたんですが、もしあるならば掲載していただいたほうがいいような気もします。その辺の拡充というか、そういうものを含めてご見解があればお願いします。","respondent":"伊勢総務課長","answer":"これは活動のほんの一部の事例ですので、今後はその中で区の紹介を検討していきたいと考えています。","voiceIndex":57,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと質問したいんですけれども、社会貢献活動というのは、企業としてやるのか、あるいは企業の社員がやるのか、そこら辺の線引きというのをどういうふうに考えておられるのか。ここに参加する企業の条件というか、一定程度こういう企業を考えているとか、そういうのがあれば伺いたいと思います。","respondent":"伊勢総務課長","answer":"先ほどの区役所の職員の事例と似ていると思います。それから、例えば情報モラル授業なんていうのがありますけれども、これはどちらかというと、企業がその得意分野において学校等と連携して社会貢献活動をしているということで、そういう意味では２種類あると考えております。","voiceIndex":59,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、今まで児童相談所に電話をしたら、そこで「まだいいんじゃないか」とか、そういう判断でなかなか動かなかったというのもミス等で出るんですけれども、もう１カ所そういうところが出てくるというふうにはならないかというのはどうなんでしょうか。","respondent":"中山人権啓発課長","answer":"できるだけ多くの声を、ここのラインを設けることでいただきながら、間違いなく、確実に保護できるような仕組みは、所管の方も十分に対応していく準備を進めているところです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"そういうことで期待したいと思います。緊急一時保護施設というのは、これは区独自で設置というのは、都とか国とかの関与がなくて区が設置すると。これは子どもでも高齢者でも、ＤＶの女性も含めて対応するということなんですか。","respondent":"中山人権啓発課長","answer":"こちらにつきましては、委員ご指摘のとおり、ＤＶであっても、子どもであっても、あるいは高齢者であっても対応するということで考えております。","voiceIndex":67,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この図で行きますと、例えば子どもやＤＶの場合は児童相談所等も経由していくんですけれども、そうではなくて、区の方から直の線になるということでいいんですか。","respondent":"中山人権啓発課長","answer":"あくまで緊急一時保護ということになりますので、区の方で先に対応させていただいて、後日、必要に応じて東京都児童相談所、あるいは東京都婦人相談所の方と連携をして、その後の措置について対応していくつもりでおります。","voiceIndex":69,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"そうすると、特別なのかどうかはわかりませんけれども、そういう一定の研修なり何なりをしっかりやった人たちがまず受ける。ほかの人は電話はとるけれどもすぐそこへつなぐ、こういうパターンにしていかなければいけないのではないかと思うんですが、その辺についてちょっと伺います。","respondent":"中山人権啓発課長","answer":"夜間・休日については宿直の方での対応ということになりますが、これにつきましてもしっかりとしたマニュアルの作成と、それから聞きとっていただいた情報の記録帳というようなものもつくらせていただいて、今月末には宿直サービスをする業者の方にも研修を行って。","voiceIndex":71,"id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"今の宿直のところで、宿直というのは、夜間窓口にいらっしゃいますよね。その方にお願いするということですか。それとも別な業者か何かがいらっしゃって、そのほかの仕事もなさっているんでしょうけれども、その中で「これを受けたときにはこういうマニュアルに従ってこういうふうにしなさい」という形になるのか。そこのところです。","respondent":"中山人権啓発課長","answer":"その中に、例えば、高齢者虐待の場合、児童虐待の場合ということで、新しくマニュアルのほかに、万が一のときの職員の継走網もつけさせていただきまして、悩んだ場合には確実に職員が対応できるような形で動いていくつもりでおります。","voiceIndex":75,"id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"その宿直の方というのは職員の方なんですか。職員ではないんですか。両方まざっているんですか。","respondent":"中山人権啓発課長、市岡総務部長","answer":"その結果、職員の方は継走網を準備しまして、必ずその所管の職員が宿直から回ってくれば電話をとって対応するような形で考えているところです。何回かご説明したとおりなんですが、もう一度整理をいたしますと、当然、平日、これは時間外を含めて、職員がいれば専用電話で、専用の電話ですから、この電話が鳴ったときはこの件だということで。","voiceIndex":77,"id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひその職員の皆さんは、今までにも増して緊張感を持たれることになるのではないかと思いますので、よろしく取り計らっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"２点ほどお聞きしたいんですが、まず、今回緊急に対応するという話だったんですが、一番の問題というのは、緊急に確保するということが私は大切なことだと思うんですね。そのときに法的な問題とかがあるわけですよね。そういうことは、虐待を受けている、そういう叫び声が聞こえたときに緊急確保する法的なことに対して、区として動くことは可能なのかどうか。","respondent":"中山人権啓発課長","answer":"緊急確保の対応が区として可能かということですが、高齢者の場合ですと市町村の事務ということで、区単独で行うことができます。ただ、児童虐待、それからＤＶにつきましては、その仕事を区で単独で行うことはできません。","voiceIndex":81,"id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"人権啓発課長のおっしゃる言葉と、ここにあらわされている文字から、品川区としての取り組みが前向きであるということはわかるんだけれども、この文章を読むと、最初の２行目の終わり、「通報につながりにくい現状がある」、これは現状を表現している。それで、市民・区民には通報する義務があるんですよということ。それから犯罪につながる場合もあるんですよと。そこをまず聞かせてください。","respondent":"中山人権啓発課長","answer":"万が一虐待に近いことがあったとしても、きちっとそれぞれの所管で対応してまいりますので、そうすることで悲劇的な事件は区の中では起きないようにしていこう、地域の見守りを強化していくことで、虐待という、今起こっている社会現象に対して一緒に区も協力して。","voiceIndex":84,"id":"exchange-036"},{"speaker":"林委員","kind":"質問","question":"非常に難しい問題なんですよね。そういうことも含めて、行政の中の体制づくりと、それから社会全体の虐待をなくしていくという活動というか、そういうことをはっきり分けてやっていくことが大事だろうと思います。その部署というか、その対応とはどこで区切りをつけるんですか。電話番号だけで区切りになるんですか。","respondent":"伊勢危機管理室長","answer":"それから個別にこういう家の中の虐待の事件もありますけれども、基本的にはそれぞれスペシャリストがいるところで処理するのがいいと思っていますので、そうした所管でやっていただくというふうに考えています。","voiceIndex":86,"id":"exchange-037"},{"speaker":"林委員","kind":"質問","question":"１１月１日から保護施設が活動を実施されるというんだけれども、こんなにすぐにでき上がるものなんですか。今、９月の半ば過ぎなんだけれども。","respondent":"中山人権啓発課長","answer":"この緊急一時保護施設につきましては、新たに何かをつくるというよりは、既にあるところにその機能を持たせるということで準備を進めておりますので、そういう意味では、１１月１日スタートというのは、職員の研修、その他準備を含めてという期間で。","voiceIndex":88,"id":"exchange-038"},{"speaker":"林委員","kind":"質問","question":"高齢者の場合と児童虐待、あるいはＤＶの場合だと、年齢層も違うし、それぞれ、どういう場所に保護するのがいいのかという問題も出てくると思うんです。極端な話、保育園等にいきなり高齢者をというのもあれだし、新しい箱をつくるのではないとおっしゃるから、どこかを兼用していこうということになるんでしょうから、その辺も考えながら対応してください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-039"},{"speaker":"堺委員","kind":"確認","question":"そこに新たにこれが加わってきます。それから、(1)のところ、夜間については宿直を経由して、とありますが、この宿直は、要するに夜間の出入り口のところにいらっしゃる方という理解でいいんですか。その辺の流れですね。ちょっと確認をしておきたい。その辺りはどうなんですか。仮に、場所はあります。はどこかの業者に委託してやるんですか。その辺がどうなっていくのか、ちょっと教えてください。","respondent":"中山人権啓発課長","answer":"どうぞ、秘密は守りますので、ご安心してお話しください」というような、そういうこともしっかりとマニュアル化して、対応する職員によってぶれがないような形はつくってまいります。","voiceIndex":91,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":33472,"voices":95}},{"id":"h22-20100915-14","meetingId":"h22-cm09","date":"2010年9月15日","dateIso":"2010-09-15","committee":"行財政改革特別委員会","time":"午後１時０１分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そういうところは出すことは可能なのか。併せて、こういうのというのは申し込みを受け付けているわけですけれども、それを各施設で打ち込んでいくわけですよね。それがすぐわかるようにシステム化できないのかというところは、１つの課題に、昨年の行財政改革特別委員会でも挙げられたと思うんですけれども、そういう意見もあったと思うんですけれども、そこら辺はどんな状況なのか教えてください。","respondent":"久保田行財政改革担当課長","answer":"２点ご質問ございまして、１点目ですけれども、午前、午後、夜間別の利用率という形ですが、こちらにつきましては年間の利用率等を出していますので、計算をすれば出すことは可能ですが、今回はちょっと資料の紙面の関係もございましたので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ですから、確かに電話でもすぐコンピュータに打ち込めるシステムになっているというお話ですが、年間、１年に一度でもいいんですけれども、そういった、コンピュータで、インターネット上で予約できるところだけでも構わないと思うんですけれども、さっきの夜間、休日の利用、あるいはもっと踏み込んで、できるのであれば個人と法人でどれだけ利用しているのかということもわかると。","respondent":"久保田行財政改革担当課長","answer":"委員のご質問の１点目ですけれども、そういった情報を区民の方がどれぐらい必要とされているのかといったところもあると思いますので、ちょっとそこの部分は今後の検討課題と考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"利用状況のこの一覧なんですけれども、この委員会があって、こういうことが議題になると一覧でこちらも出てくるのですごく状況がわかっていいんですけれども、やっぱり、その都度手作業で集計してというのは大変だと思いますし、あと、こちらとしては、さっきもちょっと言ったんですが、やっぱり、午前、午後、夜間というところでどうなっているのかというのももっと突っ込んで知りたい部分もありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いしたいと思います。休館日のところなんですけれども、改めて区民集会所の保守点検日の定め方、考え方を教えてください。特に高齢者の方とかが、もし地元に使える施設があれば使いやすいのかなと思ったりするんですが、これが減免規定には高齢者団体は入っていないんですが、この辺、なぜ高齢者団体が入れないのか、もしくは入れる可能性があるのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"休館日の考え方ですけれども、先ほどもご説明させていただきましたように、できるだけ隣り合ったり、同じ地区の中では同じ曜日にならないようにということで配慮をさせていただいているといったところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"児童センターといいますか、それぞれ借りる場所は多くていいと思うんです。それで利用率がそれぞれ高い。要望といいますか、少し考えていただきたいと思いますので、お願いします。やはり申し込み、用意どんのときに抽選になるケースとかも当然あるわけですよね。やはり数字で直接これですべて埋まっているのかどうなのかというのを見るのもなかなか難しいのかなと思います。それも要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"この年間利用率を出されていて、これを区はどのように思って、またこの利用率を何に活用していくのかなと。例えば、このパーセンテージが少ない場合に、民間だったらやっぱりこれを増やしていくのか、それとも廃止をしていくのか、そういう議論になっていくんですが、区として、この利用率を見てどのように考えて何に活用していこうとしているのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"ただ、そうは言いましても集会室として利用されている団体もありますので、その意味では集会室としての一定の利用も残しながら、他への転用ということで、荏原の在宅介護支援センターにつきましてはちょうど数が多い場所ということでありましたので、南北というんでしょうか。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"区民集会所のところなんですけれども、以前は使用日の属する月の１カ月前というところが２カ月前になって、大変利用がしやすくなったというところは評価をするんですけれども、一方で町会、自治会、認定団体が６カ月前ということであるならば、区民の希望としては、いろいろ広報をしながら進めるときに２カ月では短すぎるという企画もあるわけですけれども、それがこれだけ。","respondent":"久保田行財政改革担当課長","answer":"この辺の関係につきましては、人の手当て等もありますので、ちょっと所管課のほうと検討させていただいて、そういったことが可能かどうかといったところで利便性がより向上するという方向では検討していきたいと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"３ページの荏原西区民集会所の利用率なんですけれども、ここは極端にとは言わないんですが、結構利用率が低いということに対して区がどのようにこれを評価をし、また理由があるとお考えでしょうか。","respondent":"久保田行財政改革担当課長","answer":"私どもも、こちらにつきましては利用率的に問題意識を持っているところでございまして、ここの辺りにつきましては平塚小学校跡に文化スポーツ施設等も平成２５年にできますので、そういったことも踏まえながら今後検討していかなければならないと考えているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"利用率の低いところ、多分これは場所的なものもあるかもしれないんですが、和室と集会室が１０人という、そういうものでなかなか使い勝手が悪いという、中の構造上の問題もいろいろな施設の中でちょっと中途半端であったりとか、ニーズに合わなかったりというところもあるのかもしれないですので、ぜひそういうところの区民の皆さんの声とかも伺いながらということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"１つだけお聞きしたいんですけれども、区民集会所ですとか、各種のセンターの配置といいますか、今、まちの形態が随分変わってきて、地域的にはものすごくマンション住民が増加をするというような地域があると思うんですけれども、地域の皆さんが自由にこうやって使えるような施設の配置というのは、今、実際にそういうまちの形態が変わってきたことで。","respondent":"久保田行財政改革担当課長","answer":"特に近年では、例えば品川第一、品川第二とか大崎のほうといいますとマンションがかなり建ってきているといった状況もありますので、まちの様子も変わってきているのかなと思ってありますけれども、それに適した配置になっているかというと。","voiceIndex":22,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"もし、今ご答弁のあった、検討しているという、現時点で出せる中身があればちょっと教えてもらいたいんです。だから東品川の文化センターなんかの使用率はきっとこれだけ高くなっているんだと思うんですけれども、その辺の具体的な手当てというのが必要になっているのかなと思うんですけれども、その辺の具体性の問題と先ほどの話をちょっとお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"活用プランについてですけれども、こちらは今検討しているという状況でございまして、まずは私どもとしましては、区有施設全体を、それぞれの施設も含めましてどういった現状にあるかといった現状分析をしなければならないというところで、そういった作業を今。","voiceIndex":24,"id":"exchange-011"},{"speaker":"金野委員","kind":"確認","question":"１点、確認というか、考え方を教えてください。使用時間なんですけれども、大体、午前が平均３時間でしょうか。午後が３時間半、夜が４時間ぐらいなんでしょうか。この考え方を教えてください。","respondent":"久保田行財政改革担当課長","answer":"夕方につきましても、次の方への清掃等が入るというところで１時間ほど間をあけているといったところでございまして、一般的な午前、午後、夜間の考え方に基づいてこういう設定をさせていただいているです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問・要望","question":"そういう声を私もちょっとお聞きしているので、その時間帯を少し見直すというか、そういうことも考えられるかなと思うんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"例えば、午後２時、午後３時まで使いたいということであれば、午前、午後通してお使いいただければという形でお話はさせていただいているところです。","voiceIndex":28,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問","question":"通して使うというところで、今、午後２時から午後３時までという途中の時間帯になると、区民の皆さんは、皆さんはと言っても全体ではないんですが、届いている声からすると、時間帯で料金が、時間割りできるかと、そういう考え方も一部声を聞いておりまして、通して使うとなると、やはり午前中の時間帯、午後の時間帯という利用料金があるんですけれども。","respondent":"久保田行財政改革担当課長","answer":"例えば、午前９時から午後２時までお使いいただいて、午後２時から午後４時半まで使っていただける方がいるかどうかというのは、ちょっとなかなかニーズとしては少ないのかなといったところもありますので、私どもで一定の利用時間帯を設けて。","voiceIndex":30,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問","question":"私の質問があれだったかもしれないのですが、利用時間、いわゆる使用時間と料金と合わせて話をしてしまったんですけれども、要するに時間帯はこの午前中、午後の時間帯はそうなんですが、例えば続けて使いたい場合、午前は全部使って午後は１時から２時までしか使いませんとなった場合、料金を時間帯で割るということの考え方はどうでしょうかという質問をしたんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"今の時点では利用時間帯に応じて料金の設定をしていますので、例えば、実際に午後を借りられていても３時ぐらいで終わってしまったので、残りの金額をということはちょっと難しいというふうに考えているところですので。","voiceIndex":32,"id":"exchange-015"},{"speaker":"金野委員","kind":"意見","question":"区民の方の、いわゆる区の施設ですので、そういう時間帯の利用時間でそういう考え方がもし検討できるというか、声を聞いていただけるならというところでお話をさせていただきましたが、利用時間はある一定の時間帯で決められているものなので、理解はしているところですが、そういう声がありますということをお届けしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"そういう意味でやはり午後１時からすぐにはスタートしないで、スタートがちょっと遅くなった場合に、午後４時半という時間は、結構、それまでに退出しなければいけないというところで、利用者側にとっては不便を感じている部分があるんですが、その部分で、土日に限って午後５時までというような検討は可能ではないかと思うんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"その点につきましては、これまでの施設の利用の形態と、また人の配置等も、休みの日ですから、地域センターが併設ということであっても、職員が管理をしているものではございませんので。","voiceIndex":35,"id":"exchange-017"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"確認","question":"先だっての行財政改革特別委員会でもお話しが出ました、旧第一日野小学校跡の駐車場の件で、９月６日からちょうど稼働されたということで、地域の方も関心が高かったので、その確認で伺いたいと思います。前回も話に出ていました、区との契約形態が、確定されたとは思いますので、その中で、金額を含めた、あるいは期間、あるいは特記事項等、何かあれば報告を願えればと思います。","respondent":"久保田行財政改革担当課長","answer":"おおむね９月末に完成いたしまして、９月末から１０月にかけて供用を開始していきたいというふうに考えていると聞いているところです。そういったような計画を私どももご報告を受けているです。","voiceIndex":39,"id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"今の契約の金額のところなんですが、これをどうとらえるかというのが、今、鑑定等々と言われましたが、これは土地評価額とか鑑定のみの算定なのか、それとも、そのほかの含みというか、特記事項が含まれた算定なのかを教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"貸し付けにつきましても、校庭の部分の約２,０００m2のみですので、そういった意味では１０９万円というところで数字をいただきまして、先方もご了解いただいて、契約を結んだです。","voiceIndex":41,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"今の続きで、土地価格だけですか。例えば、財産価格審議会みたいな、そういうところには入ってないんですか。そういう、区の中で鑑定をほかではやってないんですか。判断基準はどこの部署で審査したというか、数字を固めたところはどこでやっているか、ちょっともう１回お願いします。","respondent":"久保田行財政改革担当課長","answer":"そもそもの土地の価格はそういう評価価格を得まして、その中で、公有財産管理運用委員会等のきちんとした経過を経まして、貸付料の決定をさせていただいたです。","voiceIndex":43,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":19879,"voices":45}},{"id":"h22-20100916-15","meetingId":"h22-cm09","date":"2010年9月16日","dateIso":"2010-09-16","committee":"環境対策特別委員会","time":"午後１時０２分～午後４時０６分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":2472,"voices":11}},{"id":"h22-20101022-4","meetingId":"h22-c-settlement","date":"2010年10月22日","dateIso":"2010-10-22","committee":"決算特別委員会","time":"午後３時５６分～午後４時０２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":1898,"voices":18}},{"id":"h22-20101025-6","meetingId":"h22-cm10","date":"2010年10月25日","dateIso":"2010-10-25","committee":"区民委員会","time":"午前１０時０２分～午前１１時０８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７１号議案 平成２２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７１号議案 平成２２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"山内委員","kind":"確認","question":"確認ですが、こういった申請というのは、区のほうに町会並びに商店街から申請をされて、それから大体どれぐらいの期間を要して設置までになるのか、その辺のタイムスケジュール的なものを教えてください。","respondent":"矢部生活安全担当課長","answer":"都の受付が６月、９月、１２月になっておりますので、今の荏原町の流れでいきますと１２月に東京都に申請を出しまして、東京都のほうで決定が出た段階で、多分設置につきましては１月か２月ぐらいから開始して、今年度中には完成する予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"今回の防犯カメラは町会と商店街が一緒になって取り組んでいるんですが、商店街には既に設置されているところが幾つかあると思うんですが、今まではたしか商店街が独自でやって助成が入ってくるという形だったと思うんですけれど、例えば今までにもう防犯カメラが設置されている商店街と、その近隣の町会で合同でやりましょうといった場合にはどういった、補助金とか町会の負担分とかいうのは。","respondent":"矢部生活安全担当課長","answer":"そちらにつきましては１町会、１商店街を対象としていますので助成については３分の１ずつということになります。今回の地域見守り活動につきましては町会と商店街の連携ということになりますので、都が６分の３、区が６分の２、事業者が６分の１という補助率になります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"もう行っているところで近隣の町会が一緒にやろうよといったとき、どういう動きになっていくのかなというところがちょっと。そこのところを再度教えてください。","respondent":"矢部生活安全担当課長","answer":"失礼しました。近隣のところでもう既に設置したのは、旗の台３丁目商店街が平成２０年度に１０台設置しています。これはあくまでも東京都の事業内容ですけれども、１商店街、１町会であれば今までどおり３分の１ずつということになります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"この広域にまたがる中で撮った後のデータというんですか、この管理の体制、日常の手間というかそれを１点伺いたいのと、もう１点はカメラのあり方で、当然というか感覚的には防犯の色彩が強いと思うので、カメラの取りつけ方あるいは見せ方というのですか、カメラがあることを意識させて防犯につなげるのか。その辺の考え方とかがあったらお願いします。","respondent":"矢部生活安全担当課長","answer":"それから見せ方という話ですけれど、この地区につきましては荏原警察署から指導をいただきまして、犯罪の死角になるような地点に、防犯カメラを設置しているということをある程度周知したほうがいいということで、今のところ見せるような形で設置を進める予定です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"意見","question":"最初のところで、３カ所の録画装置の管理となっていますが、地元の方のかかわり方、手間暇の部分と、今、警察の指導ということもありましたが、行政の設置してからのかかわり方、その辺をお願いします。","respondent":"矢部生活安全担当課長","answer":"設置後の行政のかかわり方ですけれど、当然設置し終わった後もまた商店街のほうからいろいろご意見とかいただければ、ご意見に基づきまして区としてもできる範囲でいろいろな事業を展開したいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"意見","question":"もう１つ、今のものと関連なのですが、地元の方の設置された後の労力というか、どのぐらいかかるものなのか。負担になるかならないか、機械はそのまま放っておいていいのか、あるいは何かのときにだれかがチェックをするとか、そういう負担的なところはどうなっているのかなと。","respondent":"矢部生活安全担当課長","answer":"地元のご負担ですけれど、基本的に装置とかが故障しなければそのまま自動録画になりますので、ふだんは特に必要はないんですけれど、ただ例えば犯罪が行われた場合は、警察から司法の手続に基づきまして、例えば録画したものを見せてくれという話にもなりますので。","voiceIndex":16,"id":"exchange-006"},{"speaker":"菊地副委員長","kind":"質問","question":"今の話の前段で要綱をつくるという話がありましたけれども、これはそれぞれに、いろいろな商店街でつけていって、そのそれぞれにつくり上げていくものなのですか。要はプライバシーの部分があると思うんですね、すごく大きく。一定の基準をもとにしてそうした管理体制がつくり上げられるのか、それともそれぞれのところで自由に要綱をつくるという話なのか、その辺を聞かせてください。","respondent":"矢部生活安全担当課長","answer":"したがいまして各商店街、各町会で１カ所だけ突出して１年間保存しているとか、そういったものはありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"菊地副委員長","kind":"質問","question":"大体同じつくりになっているということであれば、何か見本というか、国なり都から要綱づくりに当たって示されている中身というのが何かあるんですか、もとになるような。","respondent":"矢部生活安全担当課長","answer":"したがいまして管理体制、例えば個人情報の関係は特に重要となってきますので、個人情報には最大限配慮することとか、そういったものを織り込むようにはなっております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"高橋委員","kind":"質問","question":"細かいことですみませんが、（３）のベストとか腕章とか、４０万円で幾つぐらい買えるんですか。","respondent":"矢部生活安全担当課長","answer":"（３）の装備品の助成金の関係ですけれども、一応最大１０万円までという限度額がありまして、今のところまだ申請はないのですけれども、物によりけりというところもありますけれど、大体１回の申請が来た場合には最高額５万円ぐらいかなとは思っております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"商店街だと、以前にもお伺いしたんですが、商店街には電灯があってそこに設置とか、アーケードのところとか、設置場所というのがある程度はっきりして、また電気代も商店街全体から賄っていこうというような考えだと思うのですが、町会の場合は、例えば設置場所が非常に限られていると思うのです。以前も町会の方たちから、防犯カメラをつけようとしても場所がないと。","respondent":"矢部生活安全担当課長","answer":"ご指摘のように、確かに町会はなかなか防犯カメラを設置する場所が難しいというのは聞いています。今回も、町会の部分で一部は東京電力の電柱を借りまして、使用料を払ってやっていくという話です。","voiceIndex":26,"id":"exchange-010"}]},{"id":"topic-02","title":"平成２２年陳情第１４号 品川区内の中小企業の振興対策に関する陳情","agenda":"平成２２年陳情第１４号 品川区内の中小企業の振興対策に関する陳情","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"区への中小企業からの経営相談とか含めて、年間どれぐらいの数が実際あるのですか。その辺を内容的なものを含めて。","respondent":"福島ものづくり・経営支援課長","answer":"そのほか開業等が５００件程度、その他これも金融関係の５号認定をとりたいという相談が多いです。これは特に平成２０年、２１年から急増しているものでございまして、それ以前、平成１９年あたりまでは大体２,０００件ぐらいが相談件数として上っておりました。","voiceIndex":40,"id":"exchange-011"},{"speaker":"菊地副委員長","kind":"質問","question":"ものづくりの分野ですと、今は仕事がない、あるいは単価が安いということで、区のほうとしても川崎なども含めて、今、受注の施策をやっていますよね。そういう区の施策の中で、実際の受注に結びついたとか、そういう動きというのはこの一、二年の間でどうなのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"今ございましたように、さまざまな形で受注相談会というのは行われております。近いところでは今年の９月に大田区の産業振興プラザで行ったもので、そこには区内企業が２０社ほど行ってあります。","voiceIndex":42,"id":"exchange-012"},{"speaker":"菊地副委員長","kind":"意見","question":"いろいろな形で区が努力されているという部分はもちろん認めるところですけれども、本当に厳しい状況の中で、さらに中小企業に対するどんな支援ができるのか。緊急対策としていろいろ打ち出されましたけれども、それだけではなかなか追いつかない部分もきっとたくさんあるのだと思います。それで、今後どういう展開をしていくのかというところも、ありましたらお聞かせ願えればと思います。","respondent":"福島ものづくり・経営支援課長","answer":"今後ですけれども、実際は来年度予算という形になろうかと思いますが、来年度予算については今検討しています。昨年度から行っております融資あっ旋も、大きな事業ですが、これにつきましても来年度は実施するかどうか、それは国のほうの動きも見ながら検討しています。","voiceIndex":44,"id":"exchange-013"},{"speaker":"渡辺委員","kind":"意見","question":"自民党は結論を出すということで、趣旨採択が望ましいと思います。その中で理由等もあったのですが、最後に個別の施策等へのご意見ですが、例と銘打っていらっしゃるところがありました。それぞれ支持するかしないかで当然この陳情の取り扱いも変わってくるという懸念もある中で、理由のところの文面、そして表題と陳情の要旨を最重点において、趣旨ということで結論を出したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"結論を出してください。私は今のお話を聞く中で、区としても理由についてはまさにそのとおりだと、今、中小企業が置かれた現状はもう、区の認識も陳情者の方と一致をしていると思います。ですから本来は採択をしてもらいたいという思いはありますけれども、今の皆さんのご意見だと、今しばらく様子を見ていこうじゃないかということですので、私も趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"本日結論を出すという形で私も一緒なのですけれど、趣旨採択をさせていただきたいと思います。もう既にお話があったように、私どもも中小企業振興対策はぜひともしっかりと進めていただきたいという思いがあります。ただ先ほどもありましたが、これはあくまでも例として書かれているので、これを審議するというよりは全体を見させていただいて、やはり趣旨採択という形が望ましいのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"高橋委員","kind":"質問・要望","question":"結論を出すということで、趣旨採択でよろしいと思います。趣旨というのは、こちらの要旨の部分のところで、区のほうにもさらなる細かな対応策をとっていただきたいということを込めて、この例の部分を除いて趣旨採択という意味で、お話をしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"}]},{"id":"topic-03","title":"(1)の近隣セキュリティシステム「まもるっち」および「充電器」の全数交換","agenda":"(1)の近隣セキュリティシステム「まもるっち」および「充電器」の全数交換","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"私、今年の第１回定例会でこの「まもるっち」に関して質問させていただいて、早急に対応していただいたのですが、やはり機械ですから、また子どもたちが使うということで故障もどうしても多いのかなと。故障しないのが一番いいのですが、機械ですから故障も生じてしまうという中で、やはりどういう対応をとっていただくかということが重要だと思います。その２点を教えてください。","respondent":"矢部生活安全担当課長","answer":"それから２番目の学校ごとの交換の仕方ですけれども、今のところ当日と予備日を設けておりまして、１つの学校で３回予定を立てています。","voiceIndex":58,"id":"exchange-018"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"今回の不具合というのは、例えば私たちもそれぞれ携帯を、今はほとんどの皆さんが持っていらっしゃると思うのですけれども、こういう不具合というのは通常見られるものなのですか。「まもるっち」のシステムとして、これは特別に開発したというかつくり上げたものですよね。","respondent":"矢部生活安全担当課長","answer":"それと費用の関係ですけれども、今までかかった費用は、基本的にこのシステムは以前にご報告しました事故繰越の７,８５０万円で開発しておりまして、あと普通の通常経費でお願いしているのが、毎年大体２億円から２億３,０００万円となっております。","voiceIndex":60,"id":"exchange-019"},{"speaker":"菊地副委員長","kind":"質問","question":"毎年２億円ぐらいの経費が必要になると。そうすると、これを維持していくためにいろいろな形でこの２億円という予算が使われていくのでしょうけれど、最大の経費がかかるものというのはどのようなものになるんですか。","respondent":"矢部生活安全担当課長","answer":"掛ける児童数ですので、１万３,０００人強ぐらい今いらっしゃいますので、これだけで年間の予算が約１億１,０００万から２,０００万円ぐらいということで、通信料でほとんどかかっているような状態です。","voiceIndex":62,"id":"exchange-020"},{"speaker":"菊地副委員長","kind":"質問","question":"そうするとこの通信料というものを、これはソフトバンクとの直接契約になるんですか、通信料をまけろとかいう話は、こういうものって単独のシステムで契約しているんだから、できるのかなという気もするんだけれど、どうなのですか。","respondent":"矢部生活安全担当課長","answer":"例えば年間契約で、今回のソフトバンクの契約ではないんですけれど、２年間使っていると割引になるとかそういったところもありますので、何年間以上使ったら通信料を割り引くとか、いろいろな割引サービスをやっているところもありますので。","voiceIndex":64,"id":"exchange-021"},{"speaker":"高橋委員","kind":"質問","question":"平成２３年度の予算というのは２２年度とほぼ同額でやられていくのか。逆にいうと、平成２３年になったとき実はこの無料分が上乗せされて、知らない間に値上げするというのもあり得るわけですよね、機械が違うものになったのだから、平成２２年度と２３年度は値段が違うと言うことは可能ですよね。ですから、そうならないようにお願いしたいということなのですけれど。","respondent":"矢部生活安全担当課長","answer":"平成２１年度は２億２,０００万円ということで、平成２３年度は約２億３,０００万円のお願いを予定しています。今回端末が変わったからといって、２３年度でその分を使うということは全くありません。今までどおり、あくまでもシステムを運用するための分だけを計上しています。","voiceIndex":66,"id":"exchange-022"}]},{"id":"topic-04","title":"の海外進出推進事業等","agenda":"の海外進出推進事業等","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"その他の2)でＪＥＴＲＯのバンコクセンターは、実は私もこちらに伺ったのですが、これは大変すごいことだと思うのですね。いわゆるＪＥＴＲＯとの密接な関係で、協力のもとこのような形でサポートセンターができたということで、ＪＥＴＲＯとの関係というのですか、どのような形でここまで来られたのかといったことを教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"どの程度借りられるかということですけれども、私どもとしましては１日から借りられるということで、想定していますのは、長期間ではなく例えば１週間出張したいときに借りるとか、そういうことも考慮しまして１日単位で借りられるということで考えてあります。","voiceIndex":72,"id":"exchange-023"},{"speaker":"山内委員","kind":"質問・要望","question":"昨年は１回目の参加ということで、参加された企業からどのような意見、また出展することによってビジネスマッチングを行って現地の企業間との交流、もしくはそれがどのような形で発展をしたのかといった成果的な報告というものが多分上がっていると思いますけれども、その辺をお聞かせいただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"やはり１回行っただけではなかなか様子もわかりませんし、商談もすぐにはできないということもありまして、少し継続して、こういった展示会に出展したいという意見です。","voiceIndex":74,"id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"最後の質問ですけれども、今、課長のご答弁の中で中国という話が出てきました。その当時はもちろん友好的な部分もあったと思うのですけれども、今後の展開で中国といったことは、今の現状をかんがみてどのようなお考えでいるのかということを最後に教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"確かに中国というのはかなり広大ですし、市場もある、さらに経済発展も見込まれる国ということで、そういった面では魅力的な国であろうかと思いますけれども、今回の中国との関係を見ますと、だからといってすぐ中国進出を区として支援していくかといいますと。","voiceIndex":76,"id":"exchange-025"},{"speaker":"菊地副委員長","kind":"質問","question":"このサポートセンターは、開設をしたら実際に使用してみたいというか、可能性のある企業数は区内だとどれぐらいあるんですか。その辺の調査というのはされたのかお聞かせ願いたいのと、もう１つは日常管理、１７m2の小さなオフィスなので日常管理って別にないのかなという気もしますけれど、そういうものがあれば教えてもらえますか。","respondent":"福島ものづくり・経営支援課長","answer":"次に日常管理ですが、先ほど言いましたように１日単位で借りられます、あるいは１週間借りたときに、出ていくときに片づけですとか、あるいは新たに来た人へのかぎの受け渡しですとか、そういう管理は当然必要になってくると思ってあります。","voiceIndex":78,"id":"exchange-026"},{"speaker":"菊地副委員長","kind":"質問","question":"前段のことで、実際に今、海外進出を考えたりあるいはこういう展示会などに出展する企業というのは、ここに書いてある実際の出展企業は６社ですが、当然もっとあると思うのですけれど、区としてとらえている海外に進出をしている中小企業は、何社になるんですか。","respondent":"福島ものづくり・経営支援課長","answer":"そういう意味ではなかなか需要をはかり切れないところもありますので、需要を十分把握しながら、今後も含めて検討していきたいと考えています。","voiceIndex":80,"id":"exchange-027"},{"speaker":"菊地副委員長","kind":"質問","question":"せっかくこうやって開設したわけですから、必要なのではないかと思いますから、その辺はちょっと力を入れるというか、計画だけはつくっていただければと思います。","respondent":"福島ものづくり・経営支援課長","answer":"告知につきましては、これからさまざま行っていきたいと思いますし、実際に１１月２３日には向こうに行って、華々しくではないですけれどもオープニング式典を行いますので、そういった際には新聞記事にも載せるようにしたいと思います。","voiceIndex":82,"id":"exchange-028"},{"speaker":"山路委員","kind":"意見","question":"３番目の第４０回インターネプコン・ジャパンへの出展、別のビジネス展でビッグサイトで行われたものに品川パビリオンがありまして、私も見に行ってきたんです。ところが、あまり内容が理解できないんですね。今年の内容についてはどのように展開をしていくか聞かせていただけますか。","respondent":"福島ものづくり・経営支援課長","answer":"専門の説明員も配置し、来場者の方には品川区がこういうふうに行っているんだということを周知するように、徹底していきたいと考えています。","voiceIndex":84,"id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"昨年は説明する人も何か、担当者が１人いらっしゃったんですけれど、接触できないような状況で、聞いていいのか悪いのかわからないような。そういう面で外国での出展も大事ですけれど、このインターネプコンは日本全国からいろいろな方が来る、いい機会ですので、さらにその辺、先の先、企業が開けることを念頭に置いて、力を入れていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2592#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":18966,"voices":90}},{"id":"h22-20101025-7","meetingId":"h22-cm10","date":"2010年10月25日","dateIso":"2010-10-25","committee":"厚生委員会","time":"午前１０時０２分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"したがって、出入り口はどうなるのかとか、その辺の管理上の問題がどうなるのか、一つ聞きたい。これはこの施設の設置条例なので、あれですけれども、この間、何人ぐらい、今年度の入所の状況がどうなっているのかということと、９月にも入所調整会議が開かれたので、そのあたりの状況も、ちょっと教えていただきたいと思っています。そういうことで質問を中断して、とりあえず伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"ただ、これから生活施設になるわけですので、上が体育館、下が入所施設ということになりますので、当然、中で飛んだりはねたりということは制約が入りますが、その制約の中で、できるだけ地域の方にも施設をご利用いただこうと、校庭についても同じように、そういった趣旨で。","voiceIndex":32,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"とりわけ、高齢者の７０歳代ももちろんそうですけれども、８０歳代、９０歳代の方々まで、３桁の数で非常に増え続けているという現状を、どういうふうにとらえたらいいのかと思うので、改めて、高齢者の入所申請の現状を、単なる数だけではなくて、年代ごとに非常に増えているという実態を、区がどういうふうに認識していらっしゃるかということを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今の申請状況等々については、午後の請願審査のところでも改めて質問したいと考えています。飛んだりはねたりして、下に住んでおられる方々に、日常的に騒音等々の被害がもたらされては困りますので、やっぱりその辺、双方に配慮しなければいけないということは、できるだけ少なくしていく必要があるという点で伺っているので、ぜひ、どのような対応がとられたのか教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それをした上で、あわせて、やはり生活上の影響がないようにということで、一定の制限をつけさせていただきたいと思っているところです。","voiceIndex":37,"id":"exchange-003"},{"speaker":"三上委員","kind":"意見","question":"そういう中で、これをどういうふうにするのかと言われても、ちょっと私は自信のない話で、今、戸惑っているんです。体育館が２階にあったという話も、そういうところだったかなと、今思っているのであって、新しい沢田委員にしては、そういうことをご存じかどうかということもありますよね。そこらあたり、委員長としては、どういうふうに進めようとされますか。","respondent":"鈴木委員長","answer":"今回の委員会としては、確かに、審議としては、報告をしていないと思うんですが、最初の新委員会になったときの説明をいただいたときには、ご報告があったと思うんですが、それまでの前回の委員会になってしまうと、メンバーが違いますので、確かに、その辺は。","voiceIndex":39,"id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"どの程度のものだったら許されるのか。そういったことをもう少し説明がされないと、この目的外使用ということについて、ただ、この言葉だけで審査するという話になってくると、私はちょっとつらいなと思っているんですけれども、理事者のほうとしては、そういった点について、今日の説明で、どういうふうに説明しようとされたのか、そこらあたり、ちょっと伺いました。","respondent":"木下健康福祉事業部長","answer":"今回の目的外利用の件につきましては、若干経過があります。というのも、この施設を設置するにあたりまして、八潮団地の中でも説明会を実施いたしました。","voiceIndex":41,"id":"exchange-005"},{"speaker":"三上委員","kind":"提案","question":"八潮団地の中で、私も、もう４年以上前になるでしょうか、八潮団地の皆さんのご意見を伺ういろいろな形で接する場があって、私の代表質問の中でも提案してきた事実があります。ましてや、新しい委員がいるという現実を踏まえたときには、それに対する考慮というものはあってしかるべきであると、これは私は強く求めておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"「区長は、次の各号のいずれかに該当する場合は、施設の使用を承認しない」とあります。区長は承認しないんですが、では、(1)の場合、一体だれが認めるのか、その主体を教えてください。","respondent":"冨岡高齢者福祉課長","answer":"第１号の「日常生活に支障を及ぼすおそれがあると認めたとき」ですけれども、これはどういうことを想定しているかですが、先ほども申し上げましたように、旧体育館は３階にある、その下には、特別養護老人ホームがある。","voiceIndex":45,"id":"exchange-007"},{"speaker":"大沢委員","kind":"確認","question":"もう１回、整理すると、僕がちょっと心配というか、自分自身の個人的なものですが、(1)が伝家の宝刀で、すべてのオールラウンドに使用を規制してしまうような大きな条文だと思いますので、そこら辺の解釈方法、すべてにおいて、三上委員も、南委員もおっしゃったように、これは地域の方々のことを斟酌しながら運用していかないと、紋切り型だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回のグループホームの設置で、私の数だと、区内７カ所目になるかと思うんですけれども、ちょっと伺いたかったのは、本会議での副区長の説明で、十分に聞き取れなかったんですけれども、既存のものと区別して、条例の名称も改めるという旨の説明があったと思ったのですけれども、区別というのが、どういう意味を指しているのかよくわからなかったので、今までの認知症グループホームと。","respondent":"冨岡高齢者福祉課長","answer":"今後につきましては、グループホームは必要と考えておりますので、計画的に整備してまいりたいという方向で考えているところです。","voiceIndex":48,"id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほどのご説明ですと、サービスの内容や位置づけは変わらないというお話なんでしょうか。隣の大田区は、高齢者人口は品川区の約倍ありますけれども、グループホームの数で言いますと、２４カ所あると伺っています。もう一つ、グループホームについて、利用料が高いというお話をよく伺うんですよね。所得の少ない方への減免制度や支援の制度、こうしたものも必要だと思うんですけれども、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"利用料につきましては、国の制度をベースに考えているところでございまして、各施設で若干の違いはありますけれども、大体、介護費を除けば１６万円ぐらいと理解をしているところでありまして、国の制度を活用していただいて、例えば。","voiceIndex":50,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"月１６万円とおっしゃいましたけれども、実際にはそのほかにいろいろとかかってきて、大体２０万円かそれを超えるというのが、利用されている方の実態だと思いますので、所得の少ない方も利用ができるように改善は、引き続き求めていきたいと思います。経過についてのご説明、住民からの要望、また施設の利用状況がありましたけれども、その状況がある中で、なぜ目的外という方法を、今回とったのか。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、どういう利用であれ、高齢者のための施設ですけれども、現実の問題として、今まで旧八潮南中学校時代にご利用になっていた区民の方の便宜というものを考え、そして、今、健康福祉事業部長からも話がありましたけれども、住民と何回かにわたる説明会の中で。","voiceIndex":52,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"主に体育館の話になっていますけれども、今まで利用されている方がいらっしゃって、強い住民要望もあって、それを受けてという、そういう経過のご説明はわかったんですけれども、それを、ある意味反映するために、目的外という手法をとった、その理由は何のか、ご説明いただきたいと思います。よろしくお願いします。","respondent":"冨岡高齢者福祉課長、鈴木委員長","answer":"受付け等につきましても、区立の施設として指定管理者制度をとる、その中で、利用していただいて、受け付けをし、料金を支払っていただいて。その辺のご説明だと思うんですが。この施設自体は、高齢者の福祉が第１の目的です。","voiceIndex":54,"id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ただ、そうではない、調整という話で含みを持たせていた、そこの違いがどういう状況なのかがよくわからなかったので、今まで利用されていた方に不便をかけないようにしていただきたいと思います。なぜはじめから、指定管理者制度導入を前提に話を進めていらっしゃるのか、そこをちょっとご説明いただけますでしょうか。","respondent":"木下健康福祉事業部長","answer":"したがって、体育館の利用についても、品川総合福祉センターが指定管理者の予定ということで、既にご報告していますので、具体的な実務は、現地において品川総合福祉センターの事務局のほうと、利用する団体でやっていただくということです。","voiceIndex":58,"id":"exchange-013"},{"speaker":"中塚副委員長","kind":"意見","question":"管理運営上、一体のほうがやりやすいという、そういうお考えももちろんあると思うんですけれども、であれば、はじめから一体でというのを区でやらなかった理由は何かあるのか。そこには選択肢としては、区が直接やる、指定管理者にお願いをする、その二つがあるわけで、指定管理者にしたということは、要するに区でやらないという理由は、どんな検討や経過があったのか、ご説明いただけますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問","question":"施設の使用についてなんですが、大田区も近いということもありますが、従来どおりの使用方法というのでしょうか、区外の方に対しての考え方といいますか、それは何かお考えがありますか。","respondent":"冨岡高齢者福祉課長","answer":"区外の方は、これまで利用されてきたかどうかは存じませんけれども、利用については、やはり改修前と同じように保障していくというのが、基本的な考え方になるかと思います。","voiceIndex":64,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"２回目なので簡単に。高齢者施設ですから、外を歩くという状況はそんなにあるわけではないとは思うんですけれども、もう少し工夫があってよかったかなと思うのが一つです。とりわけ、小規模タイプの計画が上がってきていますが、小規模にしても、大規模にしても、ぜひ個室という方向でやるべきだと思っているんです。改めて、その辺の考え方を、ちょっと伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん承知して質問しているつもりです。私は、これからの検討のところで、ぜひ、個室ということにこだわって考えていくべきだと考えていますので、そのこともちょっと、初めて品川区としてつくる個室タイプの施設ですので、そういうことで伺ったところですので、ぜひ要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"安否確認のほうなんですが、品川区が今現在、夜間２２時から朝の７時までということで対応していますが、２４時間ですから、品川区で言うと、それ以外の時間帯のモデルをすると認識していいのでしょうか。ちょっとその辺のこと。それから、ナースコールをしただけで、利用する料金は発生するのか、しないのか、あるいは幾らぐらいなのかということを、ちょっと伺いたいと思います。","respondent":"冨岡高齢者福祉課長、平澤生活福祉課長、吉田品川区保健所保健予防課長","answer":"この２４時間対応型のモデル事業ですけれども、現在、夜間１０時から朝７時において行われております夜間対応型の訪問介護を。前期、後期ともほぼ同じ人数ですので、１,７００人ぐらいになるです。東京都では、この春に包括補助の１メニューとして子宮頸がんワクチンを盛り込んだところですが、既に品川区では。","voiceIndex":81,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ区長が、さきの区長選挙での公約の中で、医療の無料化というふうに、医療の無料化ですから、漠然としているんですけれども、でも、医療は無料化にしていきたいという見解を表明されているという点は非常に心強いというか、そういうふうに思っているので、その辺も含めて、区のこれからの方向を非常に期待して見ていきたいと思っているので、改めて、その辺も含めて見解を伺いたいと思います。","respondent":"冨岡高齢者福祉課長、平澤生活福祉課長、吉田品川区保健所保健予防課長","answer":"２４時間対応訪問介護サービスモデル事業ですけれども、これにつきましては、ご案内のとおり、業者が利用者にペンダント等を。法外のほうなんですけれども、こういったところにプラスアルファという意味合いで、法外の要綱に基づきまして。ということで、これからも動向を見守って対応してまいりたいと考えております。","voiceIndex":85,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"生活保護のほうですが、法内援助だけでは非常に不十分だというご見解のもとで、入浴券を法外として支給されていると、そういう設定でありますので、入浴券も、ほんとうに憲法第２５条に基づいてやっていく行政だという点では、ぜひ拡大していく方向にあるべきだと思うんですけれども、補正予算のこの部分については、全く否定するものではありませんので、これは、そういうことで要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"伺いたいことは、品川区の傾向について、いろいろな特徴的な傾向や件数や割合というのは把握されていらっしゃるのか。その特徴については、どういう状況なのか、ご説明いただきたいと思います。先ほどの課長のご説明ですと、負担ができる範囲だというご説明がありましたけれども、所得の少ない方が安心して利用できる範囲だと、お考えなのか、そこを伺いたいと思います。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長","answer":"これを、開始の傾向、事由別ということで見ますと、平成２０年度につきましては、世帯主の傷病というのが２４.３％、同じく平成２１年度が１８.９％、平成２２年９月が１８.１％ということで、先ほど申し上げました失業、それから。モデル事業の自己負担が５００円で高いですが、例えば、現に夜間でお使いになっている方が、コールをして、随時の訪問を受けたときは、１回につき、１人対応だと６４１円です。","voiceIndex":90,"id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そうした原因については、どう考えていらっしゃるのか。２３区の議長会の中でも、国の責任を明確にするため、全額国庫負担を求めておりますけれども、そういう点については、区はどうお考えなのか、どう働きかけていらっしゃるのか、あわせてご説明いただきたいと思います。もっと言えば、介護保険制度の中で考えていらっしゃるのか、その見通しについてお伺いしたいと思います。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長","answer":"区として、どのような対応をしていくかということなんですけれども、先ほど、委員からお話がございましたとおり、議長会のほうで、全額国の負担ということもございまして、私どものほうでできることでいきますと。いずれにしましても、これはモデル事業ですので、国の今後の検証を待ちまして、区としても対応していくという形でまとめてまいりたいと考えています。","voiceIndex":93,"id":"exchange-022"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"生活保護のほうですけれども、区としての対応のご説明はありましたけれども、国に対して、いわゆる全額国庫負担、それについては求めているのか、いく考えがあるのか。それとも、そこについては、今どうお考えなのか、ちょっとご説明いただきたいと思います。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長","answer":"市長会のほうで、議長会と同じような働きかけをしているということを聞いております。区市町村の段階では、そのような形で国へのお願いをしているです。保険料を担っている方と、それから、現にサービスをお受けになっている方は、１４％、１５％弱の方が介護認定を受けてサービスを受けてところですので、そういうこと全体を含めて考えていかなければいけない部分なので。","voiceIndex":96,"id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つ、予防接種委託３,０００件となっております。この下のところに、接種票作成送付、４７２万５,０００円になるのですかね。この３,０００件というのは、あくまでも任意ですから、全員ではないかと思いますが、一応、区としては、中学校１年生、２年生、３年生と２０歳の人たちは、人数的には何人と掌握なさっているのか、教えていただけますでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"接種の対象者につきましては、ご指摘のように、中学校１年生から中学３年生、それから２０歳の女子で、そのうちの３０％を接種対象者と見込んで予算を組んでいるところです。","voiceIndex":99,"id":"exchange-024"},{"speaker":"山元委員","kind":"質問","question":"今、３０％とおっしゃったんですが、具体的に人数的には何千人とか、何十人とか、今、おわかりになりますでしょうか。","respondent":"吉田品川区保健所保健予防課長","answer":"つまり、接種回数としては、本来３回なんですが、０、１カ月目、それから６カ月目という形での接種になります。そうしますと、年度内に３回接種を行うというのは極めて難しいということで、接種回数として３,０００回、それを今回、出させていただいているところです。","voiceIndex":101,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"今の３０％という見方は、通常の予防接種の場合も、そのぐらいしか見ていないんですか。３０％にしている根拠というのは、どこにあるのか。そういう数字に近づいてきたときに、この補正予算だけでは足りないということであれば、最後にまた補正予算という形は考えているのかどうかというあたりまで、ちょっとお知らせいただけますか。","respondent":"吉田品川区保健所保健予防課長","answer":"昨年までに実施しているものの実績としましては、大よそ３０％ぐらいですので、まず初回としては３０％で計算をさせていただいているところです。","voiceIndex":105,"id":"exchange-026"},{"speaker":"三上委員","kind":"確認","question":"先ほど、南委員が、区長が医療費無料に、ということを広報で、ということだったんですけれども、それは事実ですか。どういうような言い方になっているのか。そこのところは、事実、どういうことを言っているのか、ちょっと確認を。現段階で、そういう考え方をしているのか、していないのか、それは言ってもらわないと、このまま放置はできませんよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-027"},{"speaker":"鈴木委員長","kind":"提案","question":"私も、ちょっと先ほど気になりましたので、休憩時間に、それを調べさせていただこうと思っておりました。その上で、午後からご提案をさせていただこうかと思っておりましたので、その点につきましては運営としては、正副委員長で１回調整したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-028"},{"speaker":"南委員","kind":"意見","question":"選挙前に、９月２２日に、青年会議所が主催した公開討論会がありましたよね。あのときに、区長がお出しになった政策提言ということで、そこに書かれているのが、医療の無料化という表現なんです。そこで、そういうふうに、先ほど、私も取り上げて話したところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"調べていただくのは大いに構わないですけれども、医療健診の無料化という、そういうことですから、私の印象としては、医療費の無料化がというふうに、そこだけで見ると正確ではないかもしれないけれども、医療健診の無料化ということですから、私は、そんなに大きな違いはないのではないかと思って、医療の無料化ということも含まれて、医療とではなくて、医療健診の無料化ですから、どういう違うのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"すべてのレセプトの電子化のためも含んだ改修費だということなんですが、一般のまちの中で開業しておられる医者に対しても、これは電子化ということで、対応が求められることになるのかと思うんですけれども、その点の確認をさせていただきたいと思います。その辺がどうして違っているのかということを、ちょっと知りたいと思いました。その２点です。","respondent":"本城国保医療年金課長、冨岡高齢者福祉課長","answer":"レセプトの関係ですが、平成２３年度以降につきましては、すべての診療報酬請求について、電子化ということで、オンラインによる請求ということになってくるものです。毎年、それぞれの返還金の関係で違いが出て来るですが、それぞれの年に、例えば介護給付費の見込みを、こちらから報告しますと、それに基づいて一定割合で国が補助金をよこすです。","voiceIndex":119,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"介護保険のほうなんですが、額が一桁違う、そこの違いはどういうふうに見ているのか、質問したつもりなので、教えていただきたいと思います。毎年、区がこれぐらい必要だということで申請を出す。この話は聞いていないから全然わからないのですけれども、想像の範囲での質問で、大変恐縮なんですが、その辺はどうなのかということもあわせて伺っておきたいと思います。","respondent":"冨岡高齢者福祉課長、本城国保医療年金課長","answer":"前年度と比べて、桁が違うということで、すみません、前年度の数字を把握していませんでしたのであれですが、補助基本額というものがございまして、例えば介護給付費の交付金ですと、１５６億円といったような金額がございまして。今回のレセプトの審査システムの関係で、東京都全体、あるいは全国全体のシステムの改めということなので、その全体の額は、今、手元に持っているところではございませんが、ただ、趣旨としては、今まで紙ですとか。","voiceIndex":122,"id":"exchange-032"},{"speaker":"南委員","kind":"提案","question":"今の国民健康保険のレセプトの件ですけれども、かなり前にこういう提案をしてきているので、対応がほぼ整ってきているのではないかと、多分、平成２３年度から大丈夫ではないということで言っていると思っていいのかということです。その辺での対応も、一定期間あるので大丈夫だろうという認識か、どうかということを、ちょっと改めて伺っておきたい。","respondent":"本城国保医療年金課長","answer":"私どもとして把握している範囲では、導入の計画が出た後も、準備期間をつくらないといけないということで、その間、選択的に紙だとか、オンライン以外の形で認められていたものが、平成２３年度から、今、ご説明させていただいたような形で。","voiceIndex":125,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"質問し忘れたので、申しわけありません。失業期間中は、こういう保険料減免の対象になると理解していいのかというのが、ちょっとわからなかったので、教えていただきたい。そして、新しい仕事が見つからない期間は、その保険料減免の対象にずっとなっていくと理解していいのかどうか、その点だけ伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"今の要綱の中では、失業した日の翌日から翌年度いっぱいまでということで、失業した時点によって、２年弱から１年強までありますけれども、対象期間としては、失業した時点を基準にして最長２年ということで制度化されているものです。","voiceIndex":127,"id":"exchange-034"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどのレセプトの電子化についてですけれども、やりとりを聞いておりますと、まちの開業医が、この導入のために、経費や設備にどのぐらいお金がかかるのか、具体的に把握されていないということなのでしょうか。ちょっと伺いたいと思います。こういった不安の声は、品川区は把握されていらっしゃるのか。何らかの対応、支援を考えていく必要があると、私は思うんですけれども、その点はいかがでしょうか。","respondent":"山岡健康課長","answer":"つまり、年配の方の医者しかいなくて、なかなかうまく操作がわからないといったようなことへの対応につきましては、医師会のほうで指導なり何なり、手当てをしていると考えています。医療機関から直接、私どものほうに話がきているわけではございません。","voiceIndex":129,"id":"exchange-035"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"直接聞いていないということなんですけれども、ぜひ、状況を把握していただいて、必要な対応策は講じていただきたいと思うんですけれども、改めて、いかがでしょうか。それから、いわゆる社会問題化している派遣切りの問題、それから今ですと契約期間内であっても、期間工切りという言葉まで生れていますけれども、そういう解雇についても、しっかりと減免されていくのか、お伺いしたいと思います。","respondent":"山岡健康課長、本城国保医療年金課長","answer":"ただ、１カ所ということであれば、そういうこともあろうかと思いますけれども、複数カ所あるということであれば、同じような問題意識ということであれば、医師会のほうにとりまとめていただいて、私どもとやりとりをするといったほうが。対象となる範囲につきましては、雇用保険と連動する形で、雇用保険のいわゆる特定受給資格者、あるいは雇用保険の特定理由離職者ということで、倒産、解雇などによる離職ですとか、あるいは、いわゆる雇い止めなどによる離職。","voiceIndex":131,"id":"exchange-036"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ぜひ状況を把握していただいて、きちんと対応していただきたいと思います。国民健康保険のほうですけれども、倒産、解雇というお話ですけれども、ということは、派遣切りも雇い止めということで対象になるということなのでしょうか。実際に、仕事を失って収入が減った方に、しっかりと減額されていく、そういう制度にしていく必要があると思うんですけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"今の派遣切りということで、実態的にどんなものか、それによって個々に変わってくるかもしれませんが、ただ、この制度自体は、雇用保険上の認定を前提として運用されているもので、ハローワークにおきまして特定受給資格者、あるいは特定離職者に当たるかどうかを確認した後に。","voiceIndex":134,"id":"exchange-037"},{"speaker":"三上委員","kind":"意見","question":"電算システムの改修費の件ですが、要するに電算化しなければならなくなった理由というのは、レセプトの問題点はたくさんあったと思うんですよ。そこらあたりで、国も考え、東京都、品川区も、各自治体がそういった点でやってきたということだと思うんですけれども、そこらあたりちょっと、簡単でいいですけれども、ご説明いただけませんか。","respondent":"本城国保医療年金課長","answer":"主にその二つが、趣旨として掲げられているところです。","voiceIndex":136,"id":"exchange-038"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、この電算システムについて、先ほどからちょっと話が出ているように、確かに、ＩＴについて非常に取り組みづらいという方はいると思うんです。ですから、その方について、さっき、何か随分遅いような副委員長の発言がありましたけれども、そういうようなことであるならば、むしろ逆に、積極的にご協力いただいて、一日も早く１００％電算化するということは求められる話だと思えてならないのです。","respondent":"木下健康福祉事業部長","answer":"基本的には、言ってみれば、診療報酬をもらいながら事業としてやっているわけですから、国の方針を受けて、診療所がそのことについて適切に対応するというのは当然のことだと考えています。","voiceIndex":138,"id":"exchange-039"},{"speaker":"三上委員","kind":"質問・要望","question":"ぜひ、そういった形で、仮にそういうふうに申し入れてくる方がいれば、その方に対応していただければいいだけの話であって、品川区としては、粛々としてきちっとやっていっていただきたいと、こう要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-040"}]},{"id":"topic-02","title":"特別養護老人ホーム等の新たな整備","agenda":"特別養護老人ホーム等の新たな整備","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"９カ所目ということです。それから、小規模特別養護老人ホームですから、２９人以下と思っているんですけれども、その施設規模を知りたいと思うんです。認知症高齢者グループホームも、何人ぐらい入所を考えておられるのか、小規模多機能型も、具体的な内容がどういうふうになっているのか、ちょっと杜松小学校の跡にできる施設の内容を教えていただきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"地域利用施設として介護予防拠点とか、集会所機能とあって、ここは１階と書いてあるんですけれども、ちょっとその辺の、大枠の、私たちが想像できるような内容で、もし教えていただける範囲でいいですから、ちょっと教えていただきたい。これだけだと、全然何もわからないですよね。ですから、これだけではわかりませんので、もう少し詳しく教えていただきたいという率直な、素朴な質問です。","respondent":"木下健康福祉事業部長","answer":"その他の詳細については、今後、基本設計などを進める中、あるいは地元への説明、そういう中で整理をしていきたいということであります。","voiceIndex":153,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"それはそれとして受けとめて、伺っておきたいと思います。当然、こういう発表を本会議の答弁でされたんですから、教育委員会との調整も含めてされたということで理解していいんですよね。その辺は、今のご説明で、ちょっと気になったので、質問させていただいたんです。","respondent":"木下健康福祉事業部長","answer":"今回の部分につきましては、区のほうで行政の施設跡利用検討委員会というプロジェクトチームを設けまして、そういう検討を踏まえてまいりましたので、その中には、当然、教育委員会もメンバーとして入っているということでございまして、このような方向性については。","voiceIndex":155,"id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そうはいっても、多少はイメージがあるでしょうから、どんな施設ができるのかよくわからないので、現状を教えていただきたいと思います。それから、今回、健康福祉事業部長のほうから、方向性を示したというお話でしたけれども、なぜ、この方向性にしたのか、その理由を伺いたいと思うんです。","respondent":"冨岡高齢者福祉課長","answer":"方向性につきましては、特別養護老人ホームの設置につきましては、区の方針ですので、それによって、今回、杜松小学校について跡地を利用する、活用すると判断をしたところです。","voiceIndex":157,"id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"現在のところ、中身はこれだけということなのでしょうか。では、この計画の検討はいつから行ってきたのか。いつまでに、何をつくるのかというその具体化がないわけですけれども、今回の杜松小学校跡の施設は、区の方針にどう位置づけられるのか、今の方向はどこを向いているのか、もっと言えば、どこまでを向いているのか、それがよくわからないので、ご説明いただけますか。","respondent":"木下健康福祉事業部長","answer":"今回の区長の方針もありまして、この２系統が同じペースで進められるかというと、財政的な問題もそうですけれども、場所の問題等がありますから、やはりより緊急度が高いものということで、特別養護老人ホーム。","voiceIndex":159,"id":"exchange-045"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この後の請願審査もあるので、今の健康福祉事業部長の答弁について、一つだけ伺いたかったのは、今後の介護を要するというお話がありましたけれども、どういう意味なのか。私は、今のお年寄り、特に特別養護老人ホームに申し込んでいる方にとって、特別養護老人ホームが全然足りていないと思うんですけれども、今後の介護を要するというのは、どういう意味なのか教えていただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"そうしますと、例えば介護保険の介護度で言えば、３以上ぐらいの方々が施設で対応する方の、大きい意味での枠の中に入ってくる方々と考えています。ただこれだけではないということです。","voiceIndex":161,"id":"exchange-046"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今の待遇改善のところから触れたいんですが、そうすると、国の交付金も含めて、４点ぐらいやっているので、国に対して求めないというか、動向も含めて見守って、このままでいくという説明でしたけれども、人材確保、あるいは労働条件については、請願の方々のご意見の主張の中には、あまりにも不十分だと書いてあるんですが、不十分だとは思わない、こういうふうに区は認識していると受けとめていいのか。","respondent":"冨岡高齢者福祉課長","answer":"今回の５９５名、前回は５２５名の方は、在宅と施設と両方の場所から申し込んでいただいている方が入っているのと、今回、要介護度１の方が７２名、要介護度２の方９３名というふうに、軽度の方でもお申込みいただいているという数字ですので。","voiceIndex":169,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"その辺についての認識は、全然紹介されなかったので、あえてもう１回、伺いたいと思うんですけれども、ぜひ教えていただきたいと思います。ですから、小規模特別養護老人ホームでいくのであれば、それはそれでいいのですけれども、やっぱりしっかりと１カ所にとどまらずに、３カ所、５カ所、６カ所、７カ所つくっていくという方向がないと、五百何人は解消しないのではないですか。","respondent":"木下健康福祉事業部長","answer":"これは、公的サービスだけではなくて、今、地域福祉計画の改定をやっておりますが、共助の部分も含めて取り組んでいかないと、これからの時代は乗り切っていくことができないということでありますので、施設も大事ではありますけれども。","voiceIndex":171,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"空き待ちでしか入らないわけですから、新設がないので、どうしてもそうならざるを得ないわけですよ。それで質問しているんですけれども、ぜひ、現在の特別養護老人ホームの整備状況が２０番目という事態について、しかも待機者が年々増え続けて５００人をオーバーしているという事態についての品川区の認識は、どうなのかということを、最後に伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"そういう点で、ご希望される方は若干増加傾向に、今日、あるという認識に立っているところであります。","voiceIndex":173,"id":"exchange-049"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"幾つかお伺いしたいと思います。高齢者福祉課長もご存じだと思いますけれども、要介護度１以上の方は申込み資格がありますから、それはご存じの上でおっしゃったと思いますので、必要でないのに申し込んでいると思っているのか、どう思っているのか伺いたいと思います。数字のことは、もう１回伺いたいと思うんですけれども、まず、どれぐらいの方が入所されているのか、数字を伺いたいんです。","respondent":"冨岡高齢者福祉課長","answer":"先ほどの要介護の部分ですが、要介護度１と２というのは、軽度の方であるという意味で申し上げたところでございまして、申込みの受け付けをしている以上は、その方がどうだと、こういうことを考えているところではございません。","voiceIndex":175,"id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ですから、それは、答弁は訂正していただきたい。これは訂正をお願いしたいと思います。今回の審査で、もちろん何人が入れるかは、それはちょっとわからないですけれども、今年の前半の経過を見ると、７５人しか入れていないわけですから、圧倒的に足りないというのは明らかだと思うんですけれども、足りていると思っているのか、足りていないと思っていらっしゃるのか、ご説明いただきたいと思います。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"この在宅期間がカウントされるというのは、在宅で苦労されている方を極力救ってあげようということでありますから、先ほど申し上げましたように、特別養護老人ホームを申込みされている方が、今、５９０人余になっておりますけれども。申込みにつきましては、ケアマネージャーを通じて申し込むというところがございまして、その中では、例えば要介護度１とか、軽度の方であっても、在宅はまだ大丈夫なんだけれども。","voiceIndex":177,"id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"伺いたいのは、なぜ待機者の解消を目指さないのか。実際に、６７歳で、くも膜下出血で倒れて、要介護５になった方、在宅介護がないわけですけれども、特別養護老人ホームに申し込んだときに、在宅介護期間がない、年齢が６７歳だと、要介護度５であっても入れませんよと、そう冷たくケアマネージャーに言われて、こんなことってあるんですかと、そういう話も伺いました。","respondent":"木下健康福祉事業部長","answer":"そういう意味で、入所調整制度を設けてやってきていますし、今後の高齢者人口の増を踏まえたときに、具体的に、今回、新しい施設の整備についても発表していますので、そういう中で、ご判断をいただきたいと考えています。","voiceIndex":180,"id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あわせて、請願では、老人保健施設のこともありますので、一言伺いたいと思うんです。なぜ、品川区はできないんですか。それからやる気の問題なのかどうか。答弁がなかったので、ぜひ伺いたい。一緒に言いますが、請願第１８号のことについて、冒頭の説明で触れてなかったので伺いたいんですけれども、第１８号の請願には、高齢者住宅の整備、充実も求めているんです。私も、もっともだと思います。","respondent":"山田副区長、冨岡高齢者福祉課長、間部高齢者いきがい課長","answer":"ただ、計画的に、いつまで、何戸という形は、あまりにも絵にかいたもちになりかねませんので、過度な期待を皆様方に与えても。現場の状況については、私どもの所管として把握をしていますし、あわせて、あくまでも経営自体は、第一義的には、それぞれの事業所、事業者において。ただ、２０年経ちまして、入居者の生活実態や、見守りの考え方等が変わってきたということもございまして、現在。","voiceIndex":182,"id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これで最後にします。要介護度４の人を足すと２４５人ですよ。要介護度４、要介護度５の方が、地域の助け合いやネットワークで、ほんとうにその人の人間として生活が保障できるとお思いなんでしょうか。高齢者住宅につきましては、この請願にも、高齢者住宅などの整備充実と書かれておりますけれども、しっかりと区民要望を受けて、さらなる増設を具体化すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-054"},{"speaker":"三上委員","kind":"質問・要望","question":"請願第１６号と第１８号ということで、二つ一緒に審議が始まったものですから、どうのこうのということは、ちょっと言いづらくなっています。どういう判断をするべきかということについて、本日のところ、こういう形ですから、何とも言いようがないので、とりあえず、私の所感的な部分だけは、申し述べさせていただきました。答弁を求めるとかという話ではないと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"ほかにご質問がなければ、もう一度、行いたいと思っているんですけれども、いいですか。一つは、私、一番最初に質問したんですけれども、介護現場で働く方々の処遇改善の部分なんですが、四つの対策を行って十分だと考えているのかと質問したんですが、先ほど副委員長のほうからも、同様の趣旨の質問があって、答弁では、区長会に要望しているという説明がありました。その点について、伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"介護人材の問題ですけれども、国のほうも３％の介護報酬会計と、基金をつくった交付金制度で、一定の対応をしてきたわけでありまして、各法人が、事業者が、それを踏まえて一定の処遇改善をしています。","voiceIndex":188,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"私は、待遇改善のほうは、今の現況で十分だと考えているのかということを聞いたので、そこはちょっと触れていないので、ぜひそこは認識を伺いたいと思います。それから、小規模も含めて、ぜひぜひ、どんどん推進をして、それこそ待ったなしという状況ですので、安心を提供できるようにしていただきたいということを、強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-057"},{"speaker":"三上委員","kind":"意見","question":"先ほどもちょっと申し上げたが、請願第１６号については、十分な審議をするという部分について、果たしてどうなのかということについて、私は疑問を持っておりますので、これについては継続をするということで考えていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":194,"id":"exchange-058"},{"speaker":"南委員","kind":"意見","question":"今のことがよく理解できないんですけれども、継続をしたいという趣旨が、十分に審査をする必要があると、そういうことで継続したいとは、ちょっと聞こえなかったので、どういうことなのかと思ったんです。私は、結論を出すということで構わないと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"請願第１６号につきましては、今、いろいろとお話を伺いましたけれども、多少の部分で、私も問題があるとは思っておりますが、この内容を見た場合に、先ほどの報告事項にもあって、特別養護老人ホームの新たな整備についてということで、１については、十分にされているということで、十分に納得ができるところであります。以上によって、趣旨によって採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-060"},{"speaker":"三上委員","kind":"意見","question":"本日の当委員会にあっては、継続にすべきという趣旨がわからないという発言がありましたけれども、私はきちっと申し上げたとおりでありまして、署名活動にあってのやり方等についての疑義があるということであります。私どもはすべて賛成はしたいけれども、しかしながら、前提となる部分でその思いには至りませんので、本日のところは不採択とすると、こういうふうにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"今のご発言は、私はやっぱり何回聞いてもわかりません。ぜひ、言っていただきたいと促したいとお願いしたいと思います。この請願については、私は採択をしていく方向で、自民党からも、趣旨で採択していきたいと考えているという表明がありましたので、それから、公明党からも、中身はわからなくはないというお話もありましたので、ぜひ採択をしていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"最初、自民党から、１については納得すると。だから、１番は趣旨採択と理解し、２、３も、十分に理解するには不足しているので、趣旨採択だということなので、全体的に、自民党の態度としては、趣旨採択になるのかなと伺ったんです。それはそれとして、そういうふうに受けとめたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-063"},{"speaker":"大沢委員","kind":"意見","question":"請願の要旨のところで、最初の文言のところで、高齢者が安心して品川区に住み続けられるよう整備、充実に努めるようということですので、これは、先ほど、私、請願第１６号のときに申し上げたように、総合的な施策をまさに要求していると、私どもは十分に理解できますので、これに関しては採択をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":212,"id":"exchange-064"},{"speaker":"南委員","kind":"意見","question":"この請願された方の趣旨は、高齢者住宅とか、そういう部分が入っているという点ではあれですけれども、しかし基本的に第１６号の請願の趣旨とほとんど全く同じだと認識しています。したがって、ぜひ、採択をしていきたと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-065"},{"speaker":"稲川委員","kind":"質問・要望","question":"採択でお願いします。ここに書いてあるように、福祉はトータル的に判断していかなければいけないと思いますので、先ほど、副区長もおっしゃっていましたが、両輪というのですか、在宅福祉、施設福祉とか、さまざまな部分でバランスよく福祉を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-066"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"熱中症の緊急搬送のご報告、ありがとうあります。ただ、前回、伺ったときに、救急搬送と、それから残念ですけれども、死亡のことを伺ったので、緊急搬送は１６６人ですけれども、残念ながら死亡になってしまった方がどれぐらいになるのか、伺いたいと思います。それから、実態は実態でご報告いただきたいんですけれども、私は、これに伴ってやっぱり対応策が必要だと思うんです。","respondent":"荒井品川区保健所生活衛生課長","answer":"対応策についてですが、品川区におきましては、７月、８月の熱中症が一番急激に増加した時点で、既にホームページについては、熱中症情報というのを提供させていただいたところですが、そこにさらにつけ加えるという形で、水分補給の点であるとか。","voiceIndex":221,"id":"exchange-067"},{"speaker":"中塚副委員長","kind":"提案","question":"死亡者のほうは、そういう事情なんですね。民生委員というお話もありましたけれども、やはり区としてどう対応していくのか、本会議で具体的に提案していますので、繰り返すことは避けますけれども、やはり区として特別な対策、対応策はしっかり講じていかないと、来年以降、また同じような状況を繰り返してはならないと思いますので、重ねて、特別な対応策の実施を求めたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":223,"id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":77707,"voices":224}},{"id":"h22-20101025-8","meetingId":"h22-cm10","date":"2010年10月25日","dateIso":"2010-10-25","committee":"建設委員会","time":"午前１０時０３分～午後２時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"上の私道整備のところですけれども、新たに今年度、追加で必要になった理由といいますか、そちらがありましたらお願いします。それとあわせまして３９ページのところの防災生活圏の促進事業のところで、こちらは用地を取得したということだと思うんですけれども、買い上げた用地はどこのどういうところで、この取得によりましてどんな防災用機能の充実が図られるのかご説明いただきたいと思います。","respondent":"藤橋都市整備下水道課長、中村建築課長、品川防災整備担当課長","answer":"今回、５,８４８万５,０００円を対策工事費として追加計上しているものでございまして、全体としてはこの金額が上乗せされるというものです。個々の事情の中で１つ例を挙げますと、例えば着手しようと思ったところ、近隣の建築工事が始まったということで。豊町二丁目の防災ビル用地の件ですが、まず場所ですが、豊町二丁目５番１８号の土地となっております。広さとしては約１３０m2となっております。","voiceIndex":8,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"最後のところですけれども、あちらの場所ですから、戸越公園のすぐ隣地という感じのところだと思うんですが、空地率を上げることは大事なことだと思うんですけれども、空地率を上げたことで結果、どういう防災上の住民にとっての機能が向上するのかというのが大事だと思うので、そこ以外にもっと必要な、ほかに何か必要だと思われる土地もあるんじゃないかと思うんですけれども、そこら辺は。","respondent":"品川防災整備担当課長","answer":"それから２点目の空地率の件ですが、これはやはり空地を設けることで火災の延焼を防ぐことができます。","voiceIndex":12,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"戸越幹線貯留管中流部整備ということで、これの原因がはっきりわかって工事をするということなんですか。原因がわからないけれども、とりあえず工事をするということなんですか。その辺をちょっとお聞かせください。","respondent":"藤橋都市整備下水道課長","answer":"こういう状況ですので、本日現在で、主に立坑内の水を取り終わるという予定で進めておりまして、今後引き続き立坑内にたまっている土砂を清掃したり、原状回復を進めて残る人孔築造工事を進めたいと考えております。","voiceIndex":14,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"一緒に聞けばよかったんだけれども、この工期、来年度の梅雨期というのかな、雨のたくさん降るときには間に合うようにはできるということなんですか。その辺をちょっと教えてください。","respondent":"藤橋都市整備下水道課長","answer":"全体の工事の予定ですけれども、残る人孔をつくる工事がおおむね今年度いっぱい、平成２３年３月までかかると考えています。したがいまして、来年の４月以降は貯留管としての機能を発揮できる状況にあります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"阿部副委員長","kind":"質問","question":"１点だけ教えてください。戸越幹線なんですけれども、これはたしか区ではなく、全額都のほうで事業費をみるという話だったと思います。それで歳入のほうの２８ページでしたっけ。こちらのほうで都からの補助金、排水施設の建設費収入が６,１００万円ですか。そうすると、この数字というのは一致しないのかなと。その辺の仕組みを教えていただけますか。","respondent":"藤橋都市整備下水道課長","answer":"工事費用につきましては、これは東京都下水道局の受託事業ですので、全額東京都下水道局が負担します。今回、２８ページの歳入補正のところでごらんいただきますと、排水施設建設収入という形で６,１９９万４,０００円を計上しています。","voiceIndex":18,"id":"exchange-005"}]},{"id":"topic-02","title":"第７７号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第７７号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あせわせまして、今回あわせて空き室対策についてという資料が出ましたけれども、今回のこの条例改正によって空き室対策を行う住宅は２住宅というご説明だったんですけれども、入居率が平均を大きく下回っている住宅はほかにないのか、そういう住宅はほかに、例えば５０％を切っているような住宅というのは何棟あって、その入居率はそれぞれ幾らなのかお伺いします。","respondent":"柏原住宅担当課長","answer":"それからあと、ほかにあいている住宅があるかです。借上型区民住宅にいたしますと、先ほどのあれで言いますともう１棟ございまして、そちらのほうの建物が、平成２１年度末現在で１１戸中５戸という入居でございまして、４５.６％という入居の状態になってあります。","voiceIndex":25,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"最初のほうの質問で聞きたいんですけれども、オーナーと新しく契約を結び直せば、定期使用で入った方も事実上住める可能性はないことはないということですが、今回のこういう改正にあたって、現時点ではオーナーはどういうお考えを持っているのか、どんな感触なのかというのを。入居者にとって、区民にとって、これが適用されないことによる不利益というのはあるかをお伺いしたいと思います。","respondent":"柏原住宅担当課長","answer":"今回のこの件に関しましてずっとお話をしていく中で、オーナーのほうも一定のご理解をいただいた中でやるわけですけれども、その後住むかどうか、その判断につきましても、オーナーも今、検討されているです。","voiceIndex":27,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"確かに２年間だけでこの入居率を上げるというのも至難のわざだと思うんですが、それならば思い切って、住宅が埋まらない場合の区の負担は変わらないわけですから、もっとシフトして、例えば住宅困窮者の方が今たくさんいらっしゃいますし、年末とか年度末にかけて、非常に労働条件が今、苦しいとか、経済が厳しいので、住宅喪失に陥る人もいると思うので。","respondent":"柏原住宅担当課長","answer":"それからもう１つ、パレスガルの想定が低いというところで、ほかの用途に使えるかどうかというお話じゃないかと思うんですけれども、基本的にこちらの借上型区民住宅はオーナーから区民住宅として借り上げているものですので。","voiceIndex":29,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところですけれども、区民住宅として借り上げているという点ではそうかもしれませんが、オーナーとの協議で、もしオーナーが納得していたというのであれば、区民の皆さんにとって資する住宅というのは、いろいろな住宅のあり方があると思いますので、そこに特に困窮する住宅喪失者の方々に対する対策というのはあまり進んでいないというのが実態なので、ぜひそういったところにも心を寄せていただいて。","respondent":"柏原住宅担当課長、岩田都市環境事業部長","answer":"繰り返しになってしまうんですけれども、今回のこの対策につきましては、まず、区の歳出と歳入の収支バランスが悪い、それから設定の家賃に大きな問題があるということで。そういうことで担当課長はわからない、わかりにくい説明をしたのはそういう部分が若干残っている。区としてはできるだけ住み続けていただけるように、オーナーとは今後も引き続き話し合いをしていくということです。","voiceIndex":31,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった中で、高ければ入れないわけですね。ですから、ストックを活用するというのであれば、これは区がかかわっている住宅ですから、パレスガルですと約１６％しか埋まらないわけですから、そこにとどまらず、ぜひそういった対策にまで視野を広げていただきたいなと私は思いますので、ぜひご検討いただきたいなと思います。これは要望ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"１５万５,０００円と１７万５,０００円の家賃ですけれども、これに設定した根拠を教えていただきたい。","respondent":"柏原住宅担当課長","answer":"こちらのほうにした理由です。実は不動産鑑定を行っております。不動産鑑定で出た数字と、それから近傍の家賃を参考にしながら、この金額にさせていただいたです。","voiceIndex":35,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"最初からの契約ですから、その契約の家賃をオーナーに払うというのは、これは契約上のことだから当たり前なことだと。都営、区営もあるわけですから。なかったですよね。オーナーのとかいろいろな関係というのがあるんですけれども、納得できないというのは、どうしてもう１つ外したのかなという思いがあるんですけれども、その辺をもうちょっと明確に答弁をしていただきたい。","respondent":"柏原住宅担当課長","answer":"折衝させていただいたんですが、なかなかご理解といいますか、ご協力がいただけなったものですから、今回はこの２住宅で進めしますけれども、引き続きご相談といいますか、折衝させていただいて、ご協力をいただいたところで。","voiceIndex":37,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"家賃のあれはわかりましたけれども、だったら資料に出してくださいよ。所得のあれでこうなります、こうなりますという金額を出さないとわからないというのが１点。それとさっきの３つ目はという質問なんですけれども、この２つの住宅の方は、よくご理解してくれたということですね。区がこういうふうにお願いをしに行ったけれども、区の施策についてお断りしたということでよろしいんでしょうか。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"ただこういう現況をまずやった上で、それ以外のもう１つの住宅とか、それ以外のまた借上期間の満了時期を迎える住宅等々について、市場家賃を踏まえて検証し直すということで。空き室の多いところというのは、年数が古くなってくると、どんどん空き室率が多くなっていくんですね。現状で６割とか７割確保しているところでも、これから一年一年おそらく空き室率が増えてくるということは想定しております。","voiceIndex":39,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"規則であるからぱっと決めて、報告事項で今後、建設委員会で流れてくるのかという確認をまずさせていただきたいのと、これをやるというのがとりあえず２件、２つの対象だということなんですけれども、各建物にオーナーがいらっしゃって、例えばこれをやるよという話をほかの借上型住宅のオーナーに対してアナウンスが１回かかっているのか。今回やる対象オーナーじゃなくて。","respondent":"柏原住宅担当課長","answer":"基準といいますか、今考えておりますのは、入居率が５０％以下で、それからオーナーとの期間が満了する５年を切ったところで考えております。今回、募集でどのくらいの人気が出るかどうかというところもありますので、これはちょっと考えながら。","voiceIndex":42,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"この借上型区民住宅の傾斜家賃の問題は、ずっと議会の中で出ながら、今まで手つかずにいたというのは、１つには補助金の関係で、補助金が出ているのは、これはなくすということになると、個人的に返せとか、出なくなるとか、そういうことがあるんでしょう。その関係のほうは聞いていないんですけれども、その辺はどうなんですか。","respondent":"柏原住宅担当課長","answer":"ただし、建てたときの建設費の補助の部分についてはいろいろ折衝しまして、返還しろとか、そういう話にはならないような形で、この制度の設計といいますか、ここに至ったところですので、そちらのほうまでは影響はないというところです。","voiceIndex":44,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"家賃補助をもらわないというのは、これは金額的にどれぐらいになるんですか。","respondent":"柏原住宅担当課長","answer":"今回の場合は、例えば先ほど申しました資料に、パレスガルであると９戸入居して５０％の入居率ですという説明をさせていただいたんですが、実はこの部分につきましては、家賃補助をもらわないで、この家賃を下げたところで、今までの収入、プラスになるか。","voiceIndex":46,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"ちょっとわからないんですけれども、パレスガル、９戸、入居率５０％、大文字ビル、９戸、入居率７５％を想定すると、２,０００万円の収入になりますよというけれども、これはあくまでもシミュレーションで、入らなければかえってマイナスになるんだよね。その辺について内部ではどんな話がされているんですか。","respondent":"片田防災まちづくり事業部長","answer":"ですので、今後の部分についても、５０％以下のものをどうするのだということもありますので、それは当然対応していきたいという思いはありますけれども、そういうバランスを見て、うまく検証して、次の形につなげていきたいと思いますし。","voiceIndex":48,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"実際に区民の方がこれだけ空いている中で、入りたい人が入れないという中で、努力してくれて、５０％、７５％入るまでのシミュレーションまでしてくれているわけですから、これがその部分も入れば利益が出る云々というのは、困っている区民の方が入れるということではそれはいいことなんですね。ただ本当に２年間を限度として、どうするんだよね。町場のほうの不動産で考えたら、専門家はどうなんだろうね。","respondent":"岩田都市環境事業部長","answer":"パレスガルは現在、最高家賃が２０万円、年収１,０００万円ぐらいで見れば、この価格を払ってもらわなければいけない。ただし同じ住宅でも、年収が４００万円弱でお子さんがいて奥さんがいると、十二、三万円の最低家賃で入れるんです、今でも。","voiceIndex":50,"id":"exchange-018"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ちょっと記憶だけ確認させていただきたいんですけれども、表のほうで借上料としての歳出が７,３００万円、これは契約が切れるタイミングで少しずつ支出分が減っていくと思うんですが、平成２３年度はまだ状況がフルなので７,３００万円だと思うんですけれども、平成２４年度、平成２５年度、平成２６年度のそれぞれ支出のほうがどうなっていくのかというのを教えてください。それが１点でお願いします。","respondent":"柏原住宅担当課長","answer":"平成２４年度につきましては、パレスガルのほうが、この借上料が１１月で返還するということになりますので、こちらのほうが５,６００万円ほどになります。その後は大文字ビルだけになりますので、こちらが２,８００万円ほどということになります。","voiceIndex":52,"id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ここの平成２１年度の入居使用料、歳入は１,６００万円で、これは国・都の補助金が入った額なのかということを教えていただきたいのと、それから新しい賃料のほう、これは近傍家賃と比較して妥当な額ということなんですけれども、さっき別の委員からありましたように、定期の場合は少し安めに設定するのが一般的であるかなと思います。","respondent":"柏原住宅担当課長","answer":"後段のほうのご質問ですけれども、普通の近傍の家賃を基準に若干安めにということで考えたものです。それから、最初のご質問は補助金が入っているかどうかということですけれども、新しいほうは補助金を入れておりませんで、黄色のほうは補助金が入った状態です。","voiceIndex":54,"id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問","question":"例えばオーナーとさらに相談をして、当然契約の相手が変わるわけですから、一たん契約は完全に終了しますよというのは仕方ないと思うんですけれども、賃料は若干変更するにしても、双方の意思で住み続けることができますよというアナウンスができるような話というのは、オーナーとの間ではできないものなんでしょうか。それとももうされているのか。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"もう一方のオーナーにつきましては、正直申し上げまして非常に悩んでいらっしゃるところがございまして、募集まで十分時間がありますので、その中でオーナーともう少し話し合いになるという感じはあります。それで仮に経営者としても、現時点の金額で引き続きそこに住み続けたいということであれば、金額を継続して、改めてオーナーと契約をして、引越しすることなく住まわっていただくという調整に入るという考えです。","voiceIndex":56,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"住宅全体として、話の中で収支のバランスがこれでとれるとか、プラスに転じるとかという話がありましたけれども、要するに全額、２０万円とか１９万５,０００万円とか払って、それに対して空き室の分だけ収入が入らないということで、要するに１００％入らないと、区民住宅というのはプラスマイナスゼロにならないのかなと思ったんですが、どういうふうに理解したらいいんでしょうか。","respondent":"柏原住宅担当課長","answer":"今回は、今おっしゃるように、１００％入って初めて収入と支出の部分の均衡がとれるということになるんですけれども、今回のこの対策につきましては、少しでも歳入を多くしようという考えで行われておりますので。","voiceIndex":59,"id":"exchange-022"},{"speaker":"若林委員","kind":"確認","question":"条例の趣旨がちょっと違う質問なので、あくまでも空き家対策ということなので、そういった趣旨での条例改正というのは理解をしているということです。もう１つだけ。契約上そういうものなんでしょうか。それとも借り上げている側だからという見方もあるかもしれないですけれども、そこはぐっと踏み込んだ次の対応というのがあるものなんですか。そこをちょっと確認させてください。","respondent":"柏原住宅担当課長","answer":"こちらの事業といたしましては、区の借り上げたところでこういった入居者が入らないというのは区のほうの話になっていますので、極端な話をすれば、オーナーの理解が仮になくても、実施できます。","voiceIndex":61,"id":"exchange-023"},{"speaker":"若林委員","kind":"意見","question":"オーナーはよくそこら辺を、おそらく理解の声とか、区の対応とかを理解されている、わかっていると思いますので、そこは再度、いわゆる理解ということを一歩超えた対応が、私は今後、ほかの住宅も含めてそうなると思いますので、そこはよくよくお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"ただ提案内容としては、さらに具体的にもう一住宅に関しても交渉をと提案させていただいたんですが、更なる改善の余地がある印象はありますけれども、区民、とりわけこれから入居される方にとっては、家賃が下がるということで、安くなるということで利益がある改正だと思いますので、採択に賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-025"}]},{"id":"topic-03","title":"の３、請願・陳情審査","agenda":"の３、請願・陳情審査","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"ミニバスの運行というふうになっておりますが、今、課長の説明の中で、ご自分でもコミュニティーバスということをおっしゃっていましたけれども、これはコミュニティーバスと考えてよろしいんですよね。","respondent":"松代都市計画課長","answer":"２３区のうち１９区でいろいろとやられている中で、一般的に使われているのがコミュニティーバスという言い方をされております。そういったことから、一番それがなじみがいいのかなと思って説明をしました。","voiceIndex":73,"id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"そうすると、区としてはコミュニティーバスに対して、どういう姿勢でというのはある意味出ていますよね。ということを確認したいんですが、でもその反面で、この請願を読んで、区内の循環バスがあればいいよねと書いてありますけれども、何か自分もそう思っちゃうんです。循環バスがあるといいよねと。そういう意味においてはわかるんですね。","respondent":"松代都市計画課長","answer":"そういったことが今の状況下では想定できないというのが現状ですので、これまでもいろいろと検討してまいりましたし、今後もさらに何かいい方法等があれば研究はしてまいるつもりでおりますけれども、今、１９区のうち１７区ぐらいで実行している。","voiceIndex":75,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"ある意味その権利が侵害されている面があると思うんです。そういった点で交通権の保障というのはすごく大事な土台だと思うんですが、そういった点で、区民の交通権が保障されるべきだと私は思うんですが、それについてはどうお考えなのか。それが現在保障されている状況だとお考えなのかどうか、お伺いします。","respondent":"松代都市計画課長","answer":"先ほど言いました１９区のうち、目黒区と品川区がそういった形で残っております。豊島区とあとは墨田区が検討中ということで、調査をされていますけれども、目黒区は先般導入しないという方針を出されているところです。","voiceIndex":77,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"交通権という言葉を使ったんですが、そちらが今の状況でしっかり保障されているとお考えなのかどうかというのをお伺いします。南大井のほうからはこういった地域から請願が出たわけですけれども、前段の説明で、大丈夫なんですと。品川区は十分保障されているので大丈夫なんですという説明だったんですけれども、じゃ、なぜこの地域からこういうバスの運行を求める声が出てくるのか。","respondent":"松代都市計画課長","answer":"そういったところで、ほかで実施しているところで言いますと、バスと停留所だとかそういったハード整備、それとそれに伴うソフト整備、いろいろ考えますと、やっぱり１億円台かかっているところが多うあります。","voiceIndex":79,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そうした中で、長期基本計画の中を見ますと、利便性の高い公共交通網の整備という中で、区自身が交通網が脆弱な東西を結ぶ公共交通としてバスを活用し、区民の利便性を高めていきますと、まさに品川区の長期基本計画の中で方向性として打ち出しているわけですけれども、こちらに照らすと、この請願というのは、まさに実行してしかるべき内容だと私は思うんですけれども、ここら辺の整合性はいかがですか。","respondent":"松代都市計画課長","answer":"基本に私どもが据えて行っておりますのは、都市計画道路とあわせまして、若干の時間はかかりますけれども、補助２６号線の整備、補助１６３号線の整備等々、そういったものをきちんと計画的に進めようと、それをまず大前提にしております。","voiceIndex":81,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところですけれども、今回の請願の内容を見ますと、その地域にお住まいの方が、そこで住んでいるわけですよね。生活実感から切実な声が出ているわけです。いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"確かに今、ジャスコとかあるいはＴＯＣなんかでも、それぞれの企業がそういうバスをお客さんを呼び込むために運用しているところもありますので、あとここに補助２６号線が将来的に開通するということになってくれば。","voiceIndex":83,"id":"exchange-031"},{"speaker":"市川委員","kind":"質問","question":"何点かお聞きしたいんですけれども、先ほどの道路の中で、平成２０年の区の調査によると、９割の方が品川に住み続けたい、また８割の方が交通が便利と答えているということで、非常に大ざっぱな話を聞いたんですけれども、８割の方が便利と答えているということは、２割の方は不便だということですよね。何をどのくらいのところにバスを走らせたいと思っているのか、その辺も。","respondent":"松代都市計画課長","answer":"しかしながら一方で、そういう話の中で出てきますのは、最近、非常に採算性が悪くなっていて、撤退等も考えたいということも逆に出るようなことで、それはぜひ何とかやってほしいということで、全体の中での採算が見合う中で、引き続き継続してもらいたいという話をしています。","voiceIndex":85,"id":"exchange-032"},{"speaker":"市川委員","kind":"質問・要望","question":"それと区民の方が意外に思うのは、区が事業者に問いかけをしていると言ってはいるけれども、どこの路線をこの考え方で走らせようとしているのかとか、事業者と交渉しているのかというところも、区民の方がわからないというところも、こういう循環のバスを走らせてほしいという請願につながっているんじゃないかなと思いますので、私は目黒の調査を参考にするというよりも。","respondent":"松代都市計画課長","answer":"その１つは、今、運行している福祉タクシーがありますので、そのほうがよりその方の目的がきちんと実行されるという点からも、そういう点で行政としては対応してまいりたいと思っているところです。","voiceIndex":87,"id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"ただあの地域というのは電車で来るしかない。荏原文化センターは非常に不便なところにある。例えばコミュニティーバス、僕も近所の方から話を聞いて、走ってほしいという声はあります。質問したいというより要望になりますけれども、コミュニティーバス全否定をするというのだけは、また今後いろいろな形で出てくるかもしれないので、お願いしたい。要望になっちゃいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"私からも幾つかお伺いしたいと思います。それについてのお考えを聞かせてください。これが１点です。あわせてその平成１９年度の調査ですか。そういったことが手元にあって初めて、じゃ、品川区ではやるほどのことはないねとか、いや、このぐらいはやったほうがいいんじゃないかという具体的な議論になるかなと思うんですが、いかがでしょうか。以上、ご答弁いただければと思います。","respondent":"松代都市計画課長","answer":"そういったところと提携できるのかどうか、それはまた次のはなしかもしれませんけれども、今、いろいろ新宿なんかでも新しい手法でやり始めたところが出てきていますので、そういったものを先ほど言いましたように研究して、それが品川区にとってどうかというのは。","voiceIndex":90,"id":"exchange-035"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"そういったところに、例えば区で何か運行して逆に民業を圧迫するよりは、何か既存の路線に対して、補助金かどうかは別として、何らかの形で支援をすることで利便性を向上するというような、民をつぶさない形での整備というのがあると思いますので、これはまたぜひ今後とも継続的に研究はしていただきたいと思います。","respondent":"松代都市計画課長、片田防災まちづくり事業部長","answer":"具体的にこれだということはございませんけれども、我々部署だけではなくて、職員間のいろいろな研修テーマでやるとか、我々だけの専門でやることはせず、いろいろな意見を職員の中で、また福祉分野とか、企画分野とか。都市マスタープランの策定も検討を開始したものですので、いろいろなまちづくりの状況を踏まえた中で、今の委員からのお話、それぞれ民間の企業なり、幼稚園の貸し切りとかの話がありましたけれども。","voiceIndex":92,"id":"exchange-036"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"だからといって１００％税金を突っ込んで整備していくということはちょっと現実的ではないなと思いますけれども、何らかの工夫をしながら、より攻めのある交通政策というのを検討していっていただきたいと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"},{"speaker":"若林委員","kind":"確認","question":"今回の定例会の本会議でこの質問が一般質問でありまして、メモをとっていないんですけれども、あのときの答弁では、いわゆる固定化していた、ある意味ではきっぱり否定をされた答弁を私は耳に残っているんですが、もし今の二者択一で言うとすごくそうじゃないんだと。もうちょっと確認をさせてください。","respondent":"岩田都市環境事業部長","answer":"ただ、部長が先ほどお答えしたのは、都市マスタープランの中で、鉄道網あるいはその他の交通網、道路網を含めて、一応向こう４０年から５０年後の品川区のあり方を今年から検討してまいりますので、そういった中で、かなり長期的なスパンを含めて。","voiceIndex":96,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"その林議員が、高齢者が地域振興につながるという理由で求めていたわけです。そういう意味で言うなら、まさに今回の請願内容と、住民要望で一致すると思うんですけれども、自民党のこちらの請願、コミュニティーバス運行に対するお考えをぜひ聞かせていただきたいなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"ですから、そんな意味で言うと、ここに書いてある荏原文化センターや区立総合体育館、私どもの地域は荏原文化センター、皆さん３０分もかけて歩いていきますよね。ですから、そんな意味で言うと、ここで挙げている文化センターや区立体育館に行くには交通の便がなく大変不便です。でもそれが、今お話を伺いましたけれども、費用対効果とか、いろいろなそんな意味でなかなか実現が難しい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-040"},{"speaker":"若林委員","kind":"意見","question":"ほとんどの路線、各自治体の路線が赤字だと。何で赤字になっているのか。要するに料金が安過ぎるのか、利用者が少な過ぎるのか、対象者、ターゲットが間違っているのか、今、否定されている一番の要因が、品川区においてはその採算性、経済性ということが一番に出てきましたので、そこにある程度壁があるのであれば、まずそこら辺の分析をお聞かせください。","respondent":"松代都市計画課長、齋藤道路公園課長","answer":"幾つかあるんですけれども、停留所が必要であり、かつまた望まれる。そうすると、非常に時間がかかる。そうしますと、時刻どおりになかなか運行できない。信頼性が失われる。そういったところで利用者が減っている。足立区を例にすると、現在つくばエクスプレス舎人ライナーが開通しましたが、当時は、人口６４、５万人いるのに、主要駅が５つしかなかった。どういうことが起きるかといいますと、駅に行くのにバスに乗って２０分、３０分かかります。","voiceIndex":100,"id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"今の意見を言って、採決でやると。今で翻しちゃうんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-042"},{"speaker":"松澤委員","kind":"質問","question":"私たちの本会議での質問については、今、ここでも答弁がありましたけれども、全く考えていないというお話をいただいておりますし、私たちの中でも、委員が質問したので、この請願に対してどうだろうかという全員で討議をした結果、私たちの会派では不採択ということになっております。願意に沿いがたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問","question":"私もさっきの発言の中で、私の一般質問と、会派としてもミニバスがあったらいいねということでお話をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"今の段階ではなく、コミュニティーバスの運行を考えて一般質問になりました。今回、請願項目の中に、１番と２番とあります。特にこの南大井地区から文化センターや区立総合体育館に行けるよう、区内を循環するミニバスを運行してくださいという、具体的にこれをしてくださいとなっている内容に関しまして、これは申しわけないですけれども、請願としては願意に沿いがたいという形をとらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"普通にかかってしまいますので、かわりにはなかなかなれないんじゃないかなというのと、あと福祉のほうは福祉的な面では対応が必要だということでありましたけれども、現在の福祉タクシー券が、品川区の場合は非常に額が低く、２,３００円で、補完することに全くなっていないので、それであるならば、あわせてきちんと交通弱者の皆さんをどうするかというところで、全庁的な議論でのつながりで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-046"},{"speaker":"市川委員","kind":"意見","question":"私は継続で審議ができればと思ったんですけれども、今日結論を出すということであれば、趣旨は理解ができます。ただここの南大井から荏原文化センターとかのこのルートは、早急に決めることではなくて、これから研究をしていくということでもありますので、そういう中で趣旨を採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-047"},{"speaker":"阿部副委員長","kind":"意見","question":"ただ、この請願、タイトルはいいんですけれども、請願項目の中があまりにも具体的過ぎて、南大井地域から文化センターという請願項目ではちょっとお答えしづらい。具体的にどういうルートというのは先の先の議論であろうかと思われますので、この請願項目である限りは、このことには願意に沿いがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-048"}]},{"id":"topic-04","title":"専決処分の報告について（報告第１９号）","agenda":"専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"普通は、歩行者とかだったらその日によって状況が違うわけですけれども、毎週そこで作業する方だから当然わかっていることだと思うんですけれども、そこら辺については何かあったんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"今後は十分気をつけて収集、あるいは安全な作業、安全運転に努めていきたいと考えていますので、どうぞご理解をいただきたいと思います。","voiceIndex":133,"id":"exchange-049"}]},{"id":"topic-05","title":"専決処分の報告について（報告第２０号）","agenda":"専決処分の報告について（報告第２０号）","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"区民住宅の滞納と違うパターンじゃないかなと思うんですけれども、まずわからないんですけれども、３番のこの息子さんがお父様が亡くなった翌日にお母様とという形で書いてあるじゃないですか。だから、入っているのは低所得者の方でしょう。もし相続人として来るんだったら、相続人というのは、負の財産というのは相続しないというのもできると思うんですが、その辺について教えてください。","respondent":"柏原住宅担当課長","answer":"ただ、いろいろ条件がありまして、滞納があったということで、この滞納について解消するように努力してくださいというお話をさせていただいたところで、継続している中で、お母様のほうがご病気で亡くなられるというところがございました。","voiceIndex":139,"id":"exchange-050"},{"speaker":"藤原委員","kind":"確認","question":"確認しますが、やれることはすべてやったけれども、どうしようもなくてこういう形で結果的に裁判という形が起こったという形でよろしいんですよね。","respondent":"柏原住宅担当課長","answer":"説明の後段でもお話ししたんですが、途中からこの息子さんの方と連絡がほとんどとれなくなってしまいまして、今も部屋にはおそらく戻っていないだろうという状態で、郵便物なんかも書留等で送るんですけれども、たまってしまっている状態というところで。","voiceIndex":141,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"訴訟の目的の価格という、２６３万７６１円ですが、これは内訳を教えていただきたいんですが。","respondent":"柏原住宅担当課長","answer":"こちらの評価額を床面積で割りまして専有部分の面積を掛けたもの、さらにその２分の１という一定の計算式がございまして、こちらに当てはめますと、こういった形で２６３万円という形になっております。","voiceIndex":143,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"これは期間といいますか、そういう計算式はわかったんですが、それをどういう期間で出していくのだろうかと、もう少しわからないので、教えてください。","respondent":"柏原住宅担当課長、齋藤道路公園課長","answer":"期間と申しますのは、この出した部分につきましては、その実際撤去するときの建物の評価額、これをまずベースにいたしまして、いわゆる建物を明け渡してもらうというのが一番の目的ですので。訴訟を提起するときには、民事訴訟における訴訟額の額を算定する法律というのがありまして、１００万円の借金を返せ、１,０００万円の借金を返せという、この借金の何％かを訴訟の訴状に印紙として貼らなければいけない。","voiceIndex":145,"id":"exchange-053"},{"speaker":"阿部副委員長","kind":"質問","question":"確かにこれまでの明け渡しとは随分違うなと思って、ここまで聞いていいのかどうかわからないんですけれども、被告の方はもうお仕事はされている年齢の方なんですよね。収入がどのくらいあった仮定なのか、どこかで生活保護とかがかかっていたのか、まずその辺を教えていただけますか。","respondent":"柏原住宅担当課長","answer":"個人情報の部分もありますけれども、年齢としましては４０代の方でございまして、自営的といいますか、お仕事をなさっていたようです。ただ、この後、どんなお仕事をされたかというのはちょっと把握してございません。生活保護等にも手続はされていないということのようです。","voiceIndex":150,"id":"exchange-054"},{"speaker":"阿部副委員長","kind":"質問","question":"その中で訴えの提起、その前にもっと福祉としてできなかったのかという疑問がやっぱり起こります。今、被告の方は所在不明のまま、こういう言い方をしたら何ですけれども、生きているか死んでいるかわからないわけでもあるわけでしょうか。下手したら自殺したとか、そんなこともあり得るんでしょうかね。そうすると、果たしてこういう方法しかなかったのかなと思うんですけれども、いかがでしょうか。","respondent":"柏原住宅担当課長、岩田都市環境事業部長","answer":"ただ、お父様、お母様が亡くなったあたりから、ご自身が、どういう事情かはわかりませんけれども、ご自宅のほうにあまり戻らなくなってしまったということで、その福祉のお話もさせていただいたところですけれども。したがって、現在、区のほうで内部的に債権管理検討委員会で、こういった絶対取れない債権でも、現行ではずっと残さなければいけないシステムになっているのを、新たな条例を提案させていただいて。","voiceIndex":152,"id":"exchange-055"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"この方のケースというのは、福祉というのはまだ何かケースとして残っているんでしょうか。部署が離れてしまうので、ただ、ここは連携をぜひしていただきたいところなんですね。なので、一たん相談したけれども、連絡がとれなくなってしまったから、こっちだけが進んでいくということでいいのかどうか。その辺を何かご存じでしたら、教えてください。","respondent":"岩田都市環境事業部長","answer":"ここがベースです。したがって、例えば区民住宅、区営住宅に募集で当選した方の所得調査は、我々は内部ではできない。したがって、本人から直接、わざわざ課税証明を出していただかない限り、情報をとることはできません。","voiceIndex":155,"id":"exchange-056"},{"speaker":"阿部副委員長","kind":"意見","question":"具体的に今、何を言うべきかというのは言葉として出てこないんですけれども、課題があるなと感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":157,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"３月末までに施工を着手したいということですけれども、現地だと構造的な制約から、今、日常的に住民の方が利用している通路をどうするか、ふさぐか、ふさがないかという問題があると、課題があると伺っております。最後は、区として、地元の自治体ですから、東急にどういうことを要請して、注文をつけているのかというのをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":56673,"voices":162}},{"id":"h22-20101025-9","meetingId":"h22-cm10","date":"2010年10月25日","dateIso":"2010-10-25","committee":"文教委員会","time":"午前１０時０２分～午後２時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第７８号議案、品川区立学校設置条例の一部を改正する条例","agenda":"の第７８号議案、品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"当事者の子どもたちから、生徒から、どういうふうな心配の声とか聞き取り調査をして対策を立てているのか、現状を教えてください。","respondent":"和氣小中一貫教育担当課長、冠木指導課長","answer":"そういう中で、子どもたちにも新しい学校に、新しい慣行になっていくのだという機運も高めながら、ソフトランディングできるようにしていくことが重要であろうと考えております。教育内容につきましては、もう既に１学期の後半から両校の子どもたちの交流活動であったり、それぞれの教員がそれぞれの学校を訪問して、それぞれのところで授業を行うというような取り組みをしておりまして、生活指導。","voiceIndex":9,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"あの中で、先生たちは子どもたちが不安であろう思いと本人の不安は全然違っているということはもう明らかなので、しっかりとそこはないということもあるかもしれませんけれども、子どもたちにとってどういうことを不安に思うかというアンケート調査をしっかりして教育委員会としてこういう形で学校をつくっていこうとされるのであれば、そのくらいは最低限必要であるということをこれは要望しておきますので。","respondent":"和氣学務課長","answer":"ですから、１年生はありませんけれども、現在の在校生、今の１年・２年生のみ公費負担となります。もちろん新１年生はほかの中学生と同じように新しく買うわけですから、それは別に特に公費で負担をする必要はない。","voiceIndex":12,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"ここはちょっとよくわからないのですけれども、教育上そういうふうな教師の側から、教育委員会のほうから提言をすると言うかもしれないけれども、子どもたちにとっては学校が統合されるので、その辺はやはり自分の以前の制服がいい、そういうところもないのかなというところも、納得してそうなっているわけではなく、大きく品川区の教育として小中一貫校をつくるというふうにかじを切っていって。","respondent":"和氣学務課長","answer":"一部にはいるかもしれませんが、全体として子どもたちは新しい標準服ができるのを楽しみにしているというのが現状であります。","voiceIndex":14,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"こういうふうに新しいことなので、よくしていくような方向で進まなきゃいけないというときに、やはりそこに学校が、子どもたちが主役であるべきだというふうに思いますので、ぜひこういう大きくかじを切るときには、当事者の思いというものをしっかりと、どこかで聞いていますから大丈夫ですということではなくて、ちゃんと聞くという姿勢で変えていくということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"施設一体型の小中一貫校が６校目であるというところで、この間、あちこち見せていただいたのと、前回ここの図面も見せていただいたということで、質問に入りたいと思いますけれども、まずこの小学校１校と中学校が１校あった場所に、どうしてこういう大きなというか、小学校２校、中学校２校、そして幼保一体施設。","respondent":"武内委員長、田村庶務課長","answer":"答弁いただく前に、飯沼委員、一応、前回も学校の説明をいただいていますので、答えていただきますけれども、今日はご存じのように学校設置条例の一部改正の条例なので。それで、おそらく１,０００人規模の希望者がくることになりますが、これからの学校運営については実際にオープンは平成２５年４月ですから、これから学校長と調整しながら使い方、使い勝手も含めて検討していくです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委員長から前回報告しているというお話ですけれども、小中一貫校の大本のところは常に常に振り返りつつ、いろいろな意見をしていかないと、だって毎年の積み重ねですけれども、私は今日、私の責任でこの議案に対して意見を言わなくちゃいけないという意味では、単に納得のいくご説明を受けたいというところで、ぜひお時間をいただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面で、たびたびきれいな言葉で説明は受けますけれども、本当に地域の方とか子どもたちの将来を考えたとき、本当に十分に、反対意見だって十分聞きながら取り入れていくという姿勢がない限り、私はいい意見は出ないと思うのですが、この間、地域ではあきらめなくちゃいけないのかな、ここまで来たからしようがないのかという段階で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"提案","question":"よろしいですか。そのためにいろいろ苦労して、優れた提案ですというこの間ご説明もありましたけれども、先にありきの小中一貫校に当てはめて考えているというところでは、私はこの子どもたち、１年生から９年生、９歳も年の差がある、環境の問題ですけれども、９歳も年の差がある１,０００名もの子どもたちが一緒の行事を行ったり、生活をすることが本当に窮屈で無理があるなと思っています。","respondent":"田村庶務課長、冠木指導課長","answer":"は個別に自分のマンションが日陰によってどういうような影響が出るのかというような質問もあったので、それはマンション自体の設計図面がないと、壁面日影というのですが、個別の日陰の影響が出ないので、それを提供いただければ。中間テスト、期末テストについてのご指摘がございましたけれども、こういった機会に子どもたちに今まで学んできた学習を一度きちっと振り返る、そんな機会を与えて、子どもたちの成長を図っていくという意味合いにおいても。","voiceIndex":25,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"指導課長から基礎学力とか生活習慣、規範意識、効果が上がっている、ホームページにも載っていますということでしたけれども、これも毎度伺うご答弁なのです。この間、答弁をいただいても、そこが全然払拭されないのが、今、小中一貫の全国の、私、全国のサミットも行きましたし、よその話も伺っていますけれども、なかなか納得がいきません。そのところをもう１回お願いします。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"そういうのを総合的に見ながら私どもは経営策を進めているわけですし、いまや全国に小中一貫教育が広がっておりますので、それぞれの場所でそれぞれの検証をし大変効果が上がっているということを私どもは聞いております。ただし、それはそれで可能な限り、こういう理由があってこうせざるを得ないのだという説明は繰り返し行っておりますので、引き続きこれからもそういう形をとっていきたいと考えています。","voiceIndex":28,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"町会長さんは本当に地域の方からたくさんいろいろな意見を聞いている頼りになる存在ではあると思いますけれども、もちろんそのルートは重要であると思いますけれども、それ以外のところで、例えば小中一貫教育についてもっと一般の方にもご理解をいただくような説明会をしながら質疑をして中身を深めるとか意見を伺うとか、そういうのは今まで行われていないですよね。","respondent":"和氣小中一貫教育担当課長","answer":"説明の話ですが、私どもいろいろなさまざまな保護者会など、今まで小中一貫教育を始めるころからずっと保護者を対象にした説明会をやりながら、小中一貫教育についていろいろなお話をして、まだまだ足りないものがあるかもしれませんけれども、機会を得るごとに。","voiceIndex":31,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"この多くの理解というのがどういう根拠なのかと思いますけれども、私は今さまざまなと言ったけれども、参加されている方はまだまだ区民のうちの一部であるし、教育というのは本当に先の先まで考えて影響があるものであるのに、やはり多くの方の理解を得られないと、多くの方の参加ももちろんそうですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"生徒たちに制服を支給するということも含めて、お話をお伺いしたいと思いますが、保護者に対して、それは学校の校外の保護者の方たちに対しては説明会をいっぱいしているのじゃないかと思うのです。だから、そこのところでこまめに説明会を学校の中でも教育委員会でもしてあげたら、理解が深まってきてくれるんじゃないかと思うんですが、それに関する見解をお伺いしたいと思います。","respondent":"和氣学務課長","answer":"これはもう町会中で全部回っていますので、保護者のみならず新しく入りたいという方についても周知をしているというのが現状です。それから、小中一貫教育をもう１回丁寧に説明をしたほうがいいのではないかというご指摘。これはそのとおりだと思います。","voiceIndex":35,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ただ、ニュースというと一方的なものになってしまって、かえって半年に１回ぐらいでも勉強をするので、ＰＴＡの方、地域の方でも構わないと思いますけれども、ぜひＰＴＡの人たちに説明会をしていくとか、現状はこうだと説明していくとかという、ちょっと不安な人は疑問がどんどん出てくると思うのです。それでちょっと説明をする機会をもったらいいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"伊藤副委員長","kind":"意見","question":"中身のことではないのですが、今日いただいた学務課のこの資料に、「学校設置条例の一部を改正する条例の立案請求について協議する」とあるのです。少し気になったのが、内部ではこれでいいのでしょうけれども、議会に対して立案請求という資料にしたのはどうなのかということを思いましたので、どういう意図でこの資料を出されたのかお聞かせください。","respondent":"和氣学務課長","answer":"失礼いたしました。教育委員会資料をそのまま使ってしまって、これは立案請求した条例の改正についてということで出したものでした。大変失礼いたしました。","voiceIndex":39,"id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"質問","question":"そんなに大したことではないのですけれども、やはり多分、おそらく内部についてはこの立案請求という表現でいいのでしょうけれども、議会の立場からすると、条例を審査して可決する責任があるわけですから、やはりこれは条例についての表現で出せばいいと思いますので、お願いというのはそれだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対です。品川区の教育改革は学校選択制から始まって、小中一貫教育が今進んでいるわけですけれども、施設一体化でも分離型でも格差が生まれたり矛盾が出ているということで、共産党としては立ち止まって見直しを求めていきたいということで、本条例には反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-016"}]},{"id":"topic-02","title":"の第７１号議案、平成２２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"の第７１号議案、平成２２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"民間保育園２園が開設するに当たって、この経過、個々についてどういう経過でここが決定をしたのかということについて教えていただきたいのと、あと、とうかいどう保育園については認証の保育園が認可に引き上げられるということで、この点もやはり良い環境にもなってほしいと思って前から求めていたところでもありますけれども、この認証に引き上げるに当たってどういう支援が必要なのか。","respondent":"吉岡保育課長","answer":"２園の保育園の開設の経過ですけれども、これは、それぞれ別の設置者がそれぞれ設置をするものでございまして、従前から設置をしたいということでお問い合わせをいただいている中で、その設置の予定をしております場所と。","voiceIndex":57,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とうかいどう保育園のほうはＮＰＯが認可され社会福祉法人にということなんですが、取得というか、何か一体この後、社会福祉法人になった結果、ちょっとここのところをもう１回教えていただきたいのと、他の認証も経営とか人材とか財政とか、この辺も勘案して支援できれば検討していくというところなんですけれども、なかなか法人格を取るというのは大変だと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課長にお伺いしたら、現状においても園庭はなくても認可はおりるとおっしゃっていたのですけれども、この辺は今まで区立のところも園庭、少なくても、せめてちょっとぐらいは裏庭程度というか、少しはあって、特に０から５歳児のところということで本当にホームぎりぎりのところに建って、電車の音、放送の音、全部聞こえたりする場所だったわけですけれども。","respondent":"吉岡保育課長","answer":"それでグローバルキッズにつきましては、確かにこの敷地の中に園庭は取れないのですけれども、近隣の立会川緑道の上にあります荏原町公園、歩いて三、四分のところなのですけれども、そちらを園庭として活用するという形で認可申請を出す予定です。","voiceIndex":62,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１回ちょっとその辺をお答えいただきたいのと、あとグローバルキッズは結構あちこちの市町村でこのところ展開をしていて、認証と認可と両方のタイプがあるみたいなんですけれども、私たちとしてはこの間、指摘もしたと思うんですけれども、株式会社立というところにおいては、経営主体によっては閉園も余儀なくされる状態とかいろいろよそでも生まれていますので、その辺。","respondent":"吉岡保育課長","answer":"それから園庭の確保についてですけれども、先ほど申し上げましたように２歳以上の子ども１人当たり３.３平米という基準がありますので、園庭の確保ができるのにこしたことはございませんし、そのほうが望ましいという期待は持ってありますけれども。","voiceIndex":64,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"スプリンクラーの設置義務はあるのですか、保育園５階建て、高齢者のところは住居があるからスプリンクラーの設置と言われていますけれども、ここはどうなっているのですか。","respondent":"吉岡保育課長","answer":"スプリンクラーの設置義務の件について直ちにお答えできませんけれども、先ほど来申し上げたように、十分に基準はクリアをした上で開設をするというように考えてあります。","voiceIndex":66,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"万全の体制というか、立てていただきたいと思います。５階建てというのはすごく心配しておりますので、多分スプリンクラーを設置するとなると、またお金の面でもかなりかかるんではないかと思うので、その面、なかなか経営的にこれから軌道に乗るまで大変かと思うので、ぜひ設置するんだったら、この辺の支援を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。スポーツ教育推進事業についてですが、アスリートの講演料、これは高いのではないですか。","respondent":"冠木指導課長","answer":"ですので、限られた予算で１校当たり５０万円ですので、実際にどういう体力向上の取り組みをするか、そちらに今後はお金をかけますので、そちらは限られた予算でやらせていただくということになろうかというように思います。","voiceIndex":70,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"スポーツを推進している人は区内にもいると思うんですよ。別にアスリートでなくても地域で活躍している人たちもいますから、そういう人たちに協力していただければいいのかな、と思うのですがいかがでしょうか。","respondent":"冠木指導課長","answer":"今、委員お話しのように品川区にもたくさんいろいろなところで活躍等をされていて、記録的にも人間的にも非常に子どもたちによい教えを説いていただける方がたくさんいらっしゃいますので。","voiceIndex":72,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"先ほどの認可保育園のところで本当に今、子どもたちの遊びというのがもう一回見直されているというところではとても重要な視点であるということでお伺いをするんですけれども、先ほど立会川緑道の荏原町公園、３、４分とか、北浜公園のところもそのぐらいかかっているということなんですが、子どもたちが移動するのには、これは多分、大人の時間で言っているのかと思うのですが。","respondent":"吉岡保育課長","answer":"実際、子どもを歩かせて計測しているわけではございませんけれども、数分の増はあるかと思いますが、その範囲で行けるものというように考えてありますので、通常、園外へ行かせる子どもはそれなりの年齢に達した子どもですので。","voiceIndex":75,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"保育士さんの立場で子どもたちに、０歳児は乳母車の大きいもので移動したりするのをよく見かけるのですけれども、自分の足で歩いて移動して遊びに行かせようとしたときに、どのぐらいの移動までがいいんじゃないでしょうかというふうにあるのでしょうか。","respondent":"吉岡保育課長","answer":"繰り返しになりますけれども、近ければ近いにこしたことはないのですけれども、先ほど申し上げたように、特に荏原町についてはまさに駅に隣接しておりますが、それは反面、騒音の問題とかありますけれども、利便性から言うと非常に高いという面もありますので。","voiceIndex":77,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"待機児解消というところで行政がしなければいけないというところと利便性があるということは理解をし、さまざまな対策をとってほしいということでは当然なんですけれども、まずは考えなければいけないのは子どもたちにとってというところを考えると、利便性があるから仕方がないでしょうということではないところにちゃんと立脚していただきたいというところはしっかり押さえていただきたいのですが。","respondent":"吉岡保育課長","answer":"それから支援についてですけれども、基本的に保育の実施については経費については国が２分の１、都が４分の１、区が４分の１ということで負担をしていますので、その基本保育の経費を負担する中で十分、子どもたちにとってよりよい保育ができるように。","voiceIndex":79,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問・要望","question":"保育士さんも３人以上いないと公園に今までは行かれないという話を私は聞いていたのですが、最近はそうでもなく、安全のほうは大丈夫なんだろうかとか、でも、人がいないと遊びにも行かれないというようなことを保護者の方からもいろいろなケースを聞いていますので、やはり今ある資源を有効に活用するのには、そこに区としてもサポートをしなければいけない部分というのはあると思うので。","respondent":"冠木指導課長","answer":"今年度につきましては３校応募して、３校とも認められたです。","voiceIndex":81,"id":"exchange-028"},{"speaker":"金野委員","kind":"質問","question":"今の委員の質問にちょっと関連してというか参考に、この３校を選ばれた理由というのでしょうか、３校応募して３校指定を受けたという、そもそも論ですが、そこがなぜ応募したのでしょうか。","respondent":"冠木指導課長","answer":"そういった中で、この３校はそれぞれの学校の中の工夫の中で、例えば筋力、スポーツテストの中では幅跳び的なところになってくると思うのですけれども、そういったところとかそれから持久力的なところ、その辺のところの向上をどうやったら解決できるかというようなところで。","voiceIndex":84,"id":"exchange-029"},{"speaker":"金野委員","kind":"質問","question":"わかりました。先ほどの説明の中でスポーツ交流のといったお話もあったかと思うのですが、この事業の中でこの３校が、あるいはこれを活用してそれぞれの学校の中での異学年でのスポーツ交流という意味だったのか、ちょっとそこら辺、私の解釈が違うので、もう一度、その言葉があったかと思うのですが、すみません、説明をお願いします。","respondent":"冠木指導課長","answer":"このスポーツ推進校事業の中のいろいろな考え方の中にそういった取り組みは都全体ではあるのですが、品川区の場合はもちろん小中一貫しての部活動の育成であるとか、それからなかなか指導者が確保できない場合には、中学校の横の連携で合同部活であるとか。","voiceIndex":88,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"このスポーツ教育活動、教育のところですけれども、今のに関連して、いつからスタートして、品川区内の小中学校は何校ぐらいこれを受けているのかちょっと教えてください。","respondent":"冠木指導課長","answer":"この事業自体は３年目というように聞いてあります。２年目からこの３校が手を挙げまして、今、２年目ということです。まだ少し歴史は浅い事業です。","voiceIndex":92,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"２年目ということは、継続して支援を受けられているということですか。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおり継続して認められたというように理解しております。","voiceIndex":94,"id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"質問","question":"すみません、まとめて聞きます。もう話が出ておりますので、ある日、突然、保育園が閉園したということも報道されていますよね。それから当然、今後こういう有利な条件があれば、いろいろなところが手を挙げてくる可能性がありますから、それが例えば株式会社であったり、いろいろなところから出てくるでしょうから、そういうことについてどう対処していくのかということ。","respondent":"吉岡保育課長","answer":"それから将来的に子どもが減ってきて、ということは中期的、長期的な人口動態の展望としてはそのようになると考えていますけれども、現在のところ、出生数も微増しておりますし、それが一体どこの時点でなるのかというのはなかなか難しいところもあります。","voiceIndex":97,"id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"質問","question":"そうですよね。前半のところの話をお伺いして、言葉で言うのは簡単なんですけれども、実際それを見ていくのは大変なことだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成いたします。保育園のところは別に意見を言わせていただきたいのですが、民間保育園の増設、まずは自治体自身が責任を持ってつくるということを大前提にしていた上で、待機児解消についてちょっとここというところで、今回の認可保育園の増設、賛成いたします。の２件も賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-035"},{"speaker":"本間委員","kind":"意見","question":"賛成いたします。これからもいろいろな場面で、先々のこともにらみ合わせながらの例も出てくるかと思いますけれども、実質的に来年度に向けてのこの２つの開設の運びになったということは、努力の成果というふうに評価したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成します。学校の校庭も同じようなことが言えると思いますので、そこのところはしっかり区としても大切なことだということを押さえた上で、ぜひともこういった施策を展開していただきたいということで意見をお伝えして賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-037"}]},{"id":"topic-03","title":"平成２２年請願第１７号、来年４月に開設する２園にとどまらず待機児解消を目指しさらに認可保育園の増設を求める請願","agenda":"平成２２年請願第１７号、来年４月に開設する２園にとどまらず待機児解消を目指しさらに認可保育園の増設を求める請願","exchanges":[{"speaker":"金野委員","kind":"確認","question":"朝夕の園舎を移る時間、また、朝の時間帯、おやつ以降の時間帯にも異年齢の交流もしっかりされている中で、あえてこの５歳児が取り組む時間帯というのでしょうか、しっかり保育を受ける時間帯も安心して、またゆったりとした中で保育を受けているという、本当にいい環境だというのを見てとれました。そこで、私たちはそのような認識で帰ってきたのですけれども、区の認識はどのようにされていますでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"学校の１年生から６年生の児童の皆さんとの交流も進んでおりますので、５歳児への教育的な面でもよりよい形で今、進められていると考えております。","voiceIndex":113,"id":"exchange-038"},{"speaker":"金野委員","kind":"質問","question":"たしかこれは、この請願の同じような、趣旨は違っても項目の同じようなのが４カ月前に出されていたかと思うんですけれども、どうなんでしょうか。このときの採決の結果も踏まえると、この項目が同じように出されてくるということはどうなのかと思いますので、問題提起して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-039"},{"speaker":"井桁委員","kind":"質問・要望","question":"それからもう一つ、先ほどもありましたが、５歳児だけを保育園から切り離しというような形、切り離しを理解できませんとあるのですが、もう一度、再度、区のジョイント期カリキュラムでしたか、小学校のときにスムーズに上がれるような、そういう小１プロブレムの問題について多分リンクしてくると思うので、やはりこの年長組として飛躍的に成長する時期であるというのもそうなのですが。","respondent":"伊崎待機児童対策担当課長","answer":"最初のご質問です人数の件についてですけれども、区といたしましては以前にもご説明をしたかと思うのですが、保育園に入れなかった待機児童数は６６人と考えております。","voiceIndex":117,"id":"exchange-040"},{"speaker":"井桁委員","kind":"質問・要望","question":"やはりただただ増設ありきというような考え方というのは品川自民党としては持っておりません。しっかりと計画を持って取り組んでいただきたい。これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、何回かお聞きしているのですけれども、高齢化が進むというのは明らかになっていますし、今の状態だと少子化も心配されていて、少子化の対策が強く求められていると思うんですが、ピークが来るのを待っているのか、それとも受け身でなくて、子育てをしやすい、２人目も３人目も楽しく子育てをできるような品川区にしていきたいという意欲があるのか、ちょっとその辺を。","respondent":"伊崎待機児童対策担当課長","answer":"それから少子化につきましては、広くは国の政策とかかわってくるところですので、区であれこれ言う立場にはございませんが、ただ、区といたしましては子育てがしやすいまちづくりをしていくというこれまでの方針には特に変わりはございません。","voiceIndex":121,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本来的に言ったら、子どもが生まれてよかったと思うのと、大変な時期なので、ゆったりとほっとして子育てをしていただきたいのに、来年の４月、どうしたらうちの子は入れるのでしょうかとそういった思いですごい不安になって、とりあえず聞きたいと言っていろいろな質問をたくさん伺ったのですけれども、そういったお母さんたちが、さっきのピークが来るとか財政負担になるという言葉を聞いたら。","respondent":"吉岡保育課長","answer":"さまざまな手段をとってそういう区民の皆様の声におこたえするように努めているというところでございまして、先ほど来ちょっと話がありました６６人の待機児ということで、それは完全に０にはなっておりませんけれども、この待機児に対応する施策については。","voiceIndex":125,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、なぜそれを真っ正面から受けとめ、さまざまな意見、さまざまじゃ嫌だというご意見、認可保育園をつくってほしいという要求に対して、なぜ真っ正面から受けとめられないのかというところをちょっとお伺いしたいのですが、昨日いらした方の１１人中６人が育休明けの予約をしていたり、予約がだめだったりとかいって、本当にせっかく育休制度があって、安心して子育てができる時期なのに。","respondent":"古川子ども未来事業部長、吉岡保育課長","answer":"財政につきましては限りあるものだと、このように考えております。詰め込みの問題ですけれども、これも従来から何回もお話をしていますが、基本的には児童福祉法で定めております配置の基準、施設基準等々をクリアする中で合理的な運営をしていますので。","voiceIndex":127,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"財政のことはこの間、同じ答弁なんですけれども、やはり少子化対策とか将来を見据えたときに切り換えていくときが必要であるといった意味で、意見として切り換えてほしいということを申し上げたいと思います。行事のとき一緒です。なので私は、さっきから首を振っていますけれども、５歳児を切り離している保育がどこにあって、成果を生んでいるんだったら、ぜひそれをお話もいただきたいと思います。","respondent":"古川子ども未来事業部長","answer":"学校との関係はいずれは必ず子どもたちが通過していくものです。５歳児で成長がとまるわけではありません。その後、６歳児になって小学校１年生になるわけですから、小学校との関係をいかに活用していくかは大事な課題であったと思います。","voiceIndex":130,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"断片的に言っていてもよくわからないので、また後で教えていただいて調べていきたいと思っていますけれども、私は学校の先生が、親御さんが見て感じているというのと、本当に子どものトータルで生活を考えて、長期的に見て結果がどうかというのは全く違うと思うんです。だから、早期教育みたいに学校のほうに学校のほうに近づけようとして、今、品川区の方向は私は子どもにとってよくないと思っています。","respondent":"古川子ども未来事業部長","answer":"学校の中の分園ではありますけれども、保育園児でありますので、そのことについてはご認識をしていただきたい。あくまでも保育園の園児として１年間生活するということになっております。","voiceIndex":132,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど１、２、３について担当課長から答弁されていたことについて、まず確認します。ですから、一般的ないずれピークが来るというところでは当たらないのではないかというふうに思っていて、実際、ここ５年間で就学児前の児童がどのぐらいの増加を見ているのかというのをしっかり行政はとらえているのか、その数値を確認させていただきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"１つ目のご質問でございました最低基準の緩和というのを区はどのようにとらえているのかですが、先ほども申し上げましたように、そちらにつきましては法案の中でどのように定められるのか、また、それを受けて区は条例で、どういった理由で。","voiceIndex":135,"id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう中でさらに品川区は子ども支援というものに力を入れていこうというふうな施策がある中で、やはりここで２人目、３人目の子育てをしたいというのは当然の要望だというふうに思うし、そこはそういうふうな施策で子どもたちが増えていることをよしとするのであれば、もう少し先々どうこうしますということよりも、今本当にぎりぎりのところで必要だということに対して。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"確かに目的を待機児解消と学校への滑らかな接続ということで進めてまいりましたが、こちらの第一義的な目的が待機児解消緊急対策の中でお話をしましたように待機児解消というのがまず第一の目的であると考えております。それから実態調査のお話がございましたけれども、調査をすれば何か実態が正確に把握できて、それで何かいい対策が打てるというようなイメージもありますけれども、実際のところその実態調査の精度ですとか。","voiceIndex":137,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"そうじゃなくて子育てを不安にさせないような施策もということで逆なバージョンでお話があったんですけれども、実際にそういうニーズもあるんだということをもう少し広い視野で、それは調査方法はいろいろ手法があるので、そういうところも含めてぜひそういう広域なニーズ把握をした上でこういう施策を展開していかないと。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"基本的には先ほどお答えしたとおりなのですけれども、請願は同じ請願が二度出てくるというのは、それは業態が改善されていないからということよりも。在園児につきましては３９０人増加をしておりますので、定員の拡大とあと弾力化の拡大を含めまして、保育のニーズにおこたえしてきていると考えております。","voiceIndex":140,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"平成２１年から２２年という数で、そこは定数を明らかにして増やしていった部分というので、その前の段階で言えば、私たちが調査をしたところでは、弾力化というところで増やしているということは事実だと思いますので、今回、ここの平成２２年度の場合には、スペースを計算をし直してということで、タンスや家具があっても、そこは広場と考えますというような計算においてやっているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-050"},{"speaker":"井桁委員","kind":"質問・要望","question":"結論を出していただきたいと思います。この請願なんですが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国と自治体が社会の宝物と言われている子どもたちのために税金を投入して、しっかり育てるという、この認可保育園の増設なくしては子育て支援は進まないということで、ぜひ実現をしていただきたいこと、あと５歳児問題は区が一方的に勝手に進めることではないと思うので、このやめてくださいというところは本当に立ちどまっていただきたいと私は思いますので賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-052"},{"speaker":"本間委員","kind":"意見","question":"あるいはこれまでの経過も十分理解している中で、１番、３番は少し関係あるのかもわかりませんが、いずれにしましても品川区としては多様な政策をもとに、待機児解消という本来の目的といいますか、この中にもありますが、その意味で忠実に努力をしているということと、それから小中一貫教育に取り組んできているとともに、さらにあわせて両方、保幼小連携の就学前教育にも一層、何といいますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-053"},{"speaker":"井上委員","kind":"意見","question":"私は前回も決定していたのですが、今回同じ請願というところで、やはりこの請願趣旨のところで保育事業はいずれピークが来るとか、財政的な負担になるとか、そういったところをしっかりとデータで示した上でこういった議論が初めてされるのかというふうに思うので、継続にしてほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-054"}]},{"id":"topic-04","title":"幼稚園預かり保育事業の拡充","agenda":"幼稚園預かり保育事業の拡充","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今、現行でも預かり保育事業をやっているわけですが、この利用状況というのはどのぐらいの割合で今推移しているのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"単独幼稚園での預かり保育事業、幼保一体施設でない幼稚園での預かり保育事業ですけれども、ただいま６園でやっておりまして、平塚幼稚園につきましては２５年度に、御殿山幼稚園も来年の６月から幼保一体施設になりますので。","voiceIndex":158,"id":"exchange-055"},{"speaker":"井上委員","kind":"意見","question":"今回の待機児対策としてのモデル実施だということで今お話があったのですが、実際こういうふうにされている方で、今回は時間延長をするということですが、利用者ニーズとしてどういう声が上がってこう変えたのか。あるいは、来年４月からの入園に向けて、もう就労する人もこちらでどうぞということを考えているのか。","respondent":"伊崎待機児童対策担当課長","answer":"確かに浜川幼稚園も現在のところ定員の空きが３名ということで、決してがらがらということではないのですが、一つは今入っていらっしゃる方でお仕事を拡大したいというご要望の方がアンケートからも見えますので、そちらのニーズに対応していくということが一つと。","voiceIndex":160,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"浜川幼稚園で多かったということで地域性を見ていらっしゃるのかというふうに思うのですが、例えば子どもを５時までの預かり保育を導入したときに、本当に以前ここが導入されたときに、もう少し何か本当に働こうというか、フルタイムの人たちでは５時では厳しいのではないかというふうな思いがあって意見を言ったことがあるのですけれども、そういったニーズでは。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、公立幼稚園につきましては私立幼稚園の補完的な制度として区といたしましても設置をしていますので、まず私立幼稚園へのご入園等をお考えいただき、公立幼稚園につきましても。","voiceIndex":162,"id":"exchange-057"},{"speaker":"井上委員","kind":"確認","question":"これは浜川幼稚園は今年は３学期からモデルで、そのモデルはいつまでで本格実施がどうなるのかということの確認と、今後どういうふうに展開をしていくものと、方針をちょっと知りたいのですけれども、どういうふうに進めていかれる予定なのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"モデル実施の件ですが、この３学期から始めるところでございまして、当初は今年度と考えておりますが、状況次第でモデル実施の期間はまた再度検討したいと考えて、年度内と考えておりますが、その実施の状況次第ではもう少し延ばす必要も出てくる可能性もあるとは思っております。","voiceIndex":164,"id":"exchange-058"},{"speaker":"井上委員","kind":"確認","question":"今数字は持ち合わせていないということですけれども、後日、明日でもいいので、どういう推移にあるのかということを数字として出していただけるかとちょっと確認をしたいということと、今よくわからなかったのは、浜川幼稚園の場合には年度、３学期だけをとりあえずやってみるということで、その先、運用の状況などを調査しというか何というか、先々それを広げていくためのモデル実施と考えているのか。","respondent":"伊崎待機児童対策担当課長","answer":"４月以降につきましては、今度新しく入園される方が今度入ってこられるわけですので、この期間も継続して事業を実施していく予定ですが、ただここもモデルとしてもう少し状況を検討する期間を置くのか、あるいは切りかえをするのかというのは、申しわけありませんが。","voiceIndex":168,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"補欠の数ということでぜひ委員会のほうに提出していただきたいということを要望を一つすることと、モデル実施でモデル実施の中で検討していくということで、例えばどういうことが課題と思われていて、どういうことをチェックをしながらその後の展開につなげていくのかという、その内容についてが見えてこないのですけれども、どういうことを今後。","respondent":"伊崎待機児童対策担当課長","answer":"幼稚園はもともと長時間の在園を予定してつくられている施設ではございませんので、もちろんこちらに当たりましてお子様の保育環境ということを整えて行うわけですが、そちらで課題はないかということなど検討していきたいと考えております。","voiceIndex":172,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが１点目と、あと料金がこの６００円の根拠を教えていただきたいのと、あと私立でも預かりしているところ、いろいろだと思うんですけれども、その辺との比較とかでどうなのかという点をお伺いしたいのと、あと給食等のところでお弁当持参、おやつは市販のものと書いてありますけれども、これが現行の１７時までのところと違いがあるのかどうかということも教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"そのほかの方は就労はしていない、今後就労を予定しているという方も含めて、今は就労していないという形でいただいております。それから、６００円の根拠ですが、こちらはおやつ等を含めた実費ということで設定をしております。","voiceIndex":175,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私立のところの状況と、あとちょっと私立のところの料金設定のところをちょっとお伺いしたかったのが一つと、あと待機児対策の一つということなんですけれども、今、保育園が足りなくて、特に認証保育園のあたりが５歳児までなかなかいられないということで、その先がなくて困っているというあたりでは、その辺の認証を卒園された方の受け皿という考えがあるのかどうか、ちょっとその点をお伺いいたします。","respondent":"伊崎待機児童対策担当課長","answer":"もちろん、そこから年齢が上限に達しましたときに、保育園をお申し込みになる方もいれば、現在でも私立幼稚園、公立幼稚園に行っていらっしゃる方もいらっしゃいますので、こちらの受け皿の一つとしても考えられるとは思っております。","voiceIndex":177,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"そうすると、保育園のほうが安くなるということはないですか、ということが一つと、それから今までの現行の預かりの保育というところですが、これとこの実際のモデルというのは、浜川幼稚園でやるということですね。これはどういうふうな人が利用するということになるのでしょうか。それともう一つは３学期からということなんですけれども、要対象者は今、働いている方ですよね。","respondent":"伊崎待機児童対策担当課長","answer":"現在の親御さんたちが１７時までで間に合っているのにモデル実施をしても利用者の実態がつかめないのではないかというご質問ですが、こちらアンケートを先ほど申し上げまして、同意を取らせていただきまして、これは希望という形ですので。","voiceIndex":181,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、実際はやはり幼稚園教育をさせたいという親御さんが結構いらっしゃると思うのです。だから、本当にこういうのがどのぐらい必要なのかというのは、もう少し見極めた上で、実施していただきたいと思っています。それから最後に、保育士の体制はどうしているのかということだけお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"そこがちょっと保育園と異なるところなんですけれども、ただ、区といたしましては今、モデル実施の中でやっていくものなのですが、こちら朝と夕方に有資格の非常勤をそれぞれ１名と無資格の非常勤をそれぞれ１名配置をいたしまして。","voiceIndex":183,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"そこをちゃんとやっていただかないとどうも違う方向に行ってしまうという懸念がありますので、気をつけていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-065"}]},{"id":"topic-05","title":"の５、その他","agenda":"の５、その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"２日目の堺委員のところで児童虐待防止対策の推進についてということで、安心ネットワーク、これは子ども未来事業部長が答えられていたので、そこのところで所管は総務委員会と関連するのかもしれないのですけれども、この部分で１０月１日から始められた２４時間見守りホットラインのところについてもう少し研修内容とか体制について詳しく質問をしたいというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4712#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":59250,"voices":193}},{"id":"h22-20101025-5","meetingId":"h22-cm10","date":"2010年10月25日","dateIso":"2010-10-25","committee":"総務委員会","time":"午前１０時０２分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"質問がまとまっていないんですけれども、まず１つ、直接契約とは違うかもしれないんですけれども、この図面のところで、多目的ホールの上がスポーツ室になっていますけれども、スポーツ室だといろいろ音とかの対応があるかと思うんですけれども、そこのところはどういうふうになっているのかということを伺いたいのが１つ。とりわけ音、振動です。","respondent":"宍戸施設整備課長、阿部経理課長","answer":"したがいまして、図面の中で遮音性能についてもきちっとうたうとともに、工事中につきましても、測定し、確認しながら進めていきながら、指導についても努めて、音の影響については万全を期すようにしたいと考えています。空気調和設備工事の契約金額の件ですけれども、直接落札業者に聞いたわけではございませんけれども、綿密な積算をした上でこの金額でしたらいけるという判断でこの金額で入札したというように考えています。","voiceIndex":8,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今回の議案とは関係ないんですけれども、この絵にもかいてあるので伺いたいんですけれども、外構工事もこれからやるかと思うんですけれども、区のほうも駐車場の緑化といいますか、そういうものの支援を始めるという話なんですけれども、こういうところはそういうのも考慮されるのか。","respondent":"宍戸施設整備課長","answer":"それと、上下、スポーツ室を１階に、多目的ホールを２階に、あるいは上階にというふうに入れ替えたほうがいいのではないかということですが、我々もその点を考えまして検討はしたんですけれども、２つの理由で今のような形としています。","voiceIndex":11,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。最後の点は、これからいろいろ助成制度もやるとかという話なので、できたらやっぱりこういう区の施設が率先して導入するというのが実際に広げていく上でも必要かなと思います。これはこれからの検討に生かしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほど、あそこの場でも近隣の建物との影の問題等のお話がありましたけれども、近ごろのソーラーはそんなにかんかん照りでなければ電気を起こせないような代物ではないですから、そういうことで必要だったと思うんですが、そこら辺をちょっと聞かせていただきたいのと、それからもう１点は契約なんですが、これの契約の中の給排水衛生設備工事と、空気調和設備工事、ここの参加された企業が。","respondent":"宍戸施設整備課長、阿部経理課長","answer":"ところが、この間、武蔵小山の創業支援施設につきましても、大井林町につきましても、この平塚小学校跡施設につきましても１０kwというようなことで、少しずつ努力しているというものです。ただいまの空気調和設備と給排水衛生設備の関係ですけれども、実は次の大井林町の議案では、１つになって機械設備という形で出てまいります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"後のほうから行きますと、結局、入札という形で小分けをしている意味というのは何なのかという話にもなるので、小分けをする、必要によっては同じところに行ってしまう可能性だってなきにしもあらずなわけですね。そこら辺もちょっとあると思ってお伺いをしたところです。ソーラーのほうは、もうちょっと最初からやっておいたほうがいいに決まっています。これからちょっと考えておいてください。","respondent":"阿部経理課長","answer":"委員おっしゃるとおり、分けているというのは受注機会の拡大を図っているという、そういうことを根本として考えてありますので、今後ともこういう形でできる限り受注機会の拡大ということでやっていきたいというふうに思っています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"堺委員","kind":"確認","question":"確認で３点ほど、申しわけないんですが、今、駐車場の件についてはお尋ねがあったんですけれども、この場で聞いていいのかちょっとよくわからないんですが、第７９号議案に添付されている書面等を見た中で、駐輪場をこれから計画されていくのかなと思うんですけれども、６ページの図面の右側のほうには、職員用駐輪場という記載はあるんですけれども、一般の利用者の人たちも、車でみえる方と。","respondent":"宍戸施設整備課長、阿部経理課長","answer":"ここに組み立てのプールを設置するのですけれども、そのプール用に、まだ小さいので、少し気温が寒い日や何かについては、給湯設備を利用してお湯や何かを出してあげるというふうなことで。先ほどの空気調和設備の件ですけれども、これは先ほど申し上げたとおり、業者としては積算をきちっとした上で、この額でいけるということで、これで応札をしたというふうに考えてあります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"最初にお聞きしたいんだけれども、この施設は、ここに出ているもので全部で３４億円強かかるんですよね。外構工事が入ってくれば相当かかる。大きさというか、床面積から行くと、学校とは相当違うと思うんだけれども、この３４億円、３５億円というものに対して、行政としては地域と幼保一元、それからホール等、区民のニーズにこたえるということからすると、いかがな金額なのかなというのをお聞きしたい。","respondent":"日下部企画部長","answer":"今、委員からご指摘ありましたように、３４億円ですから、確かに学校１校分です。ただ、私どもとしましては、この間いろいろな角度から検討いたしました。","voiceIndex":22,"id":"exchange-007"},{"speaker":"林委員","kind":"質問・要望","question":"一般質問でも、これからのいわゆる財政の安定した運営が、区長あるいは品川区に求められていると思うんだけれども、かけるときはかけるんだねという念押し的な話になってしまうんだけれども、やっぱりこれだけかけて施設をつくる、これでまた相当この後、運営費が、経費がかかってくると思うので、気を引き締めて当たらなければいけないなというふうに思います。全体的な話はそれです。","respondent":"宍戸施設整備課長","answer":"中から使えるトイレが右の２つでございまして、左側の３つが、だれでもトイレも含めまして外から使うようなトイレということで、大分奥まってしまいますが、例えば防災訓練ですとか、あそこの広場でイベント等が行われるような場合には、外からの使用も可能というふうなことで。","voiceIndex":24,"id":"exchange-008"},{"speaker":"林委員","kind":"意見","question":"それからもう１つ、複合的な機能を持たせた施設ができていくんですけれども、幼保の安全性というのは、ちょっと今の６ページの絵で見ていくと、何となくここの左端の保育室とか、遊戯室とかというところと、多目的ホール、あるいはその他の施設と、だれでも行き来できるように見えてしまうんだけれども、そこの安全性の確保というのは、もちろん考えていらっしゃるんだろうけれども、説明していただけますか。","respondent":"宍戸施設整備課長","answer":"内部につきましては、非常に入り組んでおりますけれども、完全に文化スポーツ施設側とは分離されておりまして、非常時以外は内部の出入りは全くできないようにきちっと区画されております。","voiceIndex":26,"id":"exchange-009"},{"speaker":"林委員","kind":"質問","question":"あるいは、３階、４階という上のほう、人がふだんはあんまりいない場所になるんだろうけれども、大丈夫なんでしょうか。","respondent":"宍戸施設整備課長","answer":"その右の倉庫、ＷＣ３つ、この辺から文化スポーツ施設というふうな区切りになってございまして、色分けしていないので非常にわかりにくくて申しわけないんですけれども、基本的には完全に区画しているというものです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"最後に、入札の件なんですけれども、何人かの方から出たんだけれども、先ほど、数が多くなって安くなって、７４％という部分もあるんだということなんだけれども、全体的な施設の入札は、この３ＪＶが応札しているんだけれども、応札したのは最初から３つのＪＶなんですか。","respondent":"阿部経理課長","answer":"応募してきたのはこの３社です。","voiceIndex":30,"id":"exchange-011"},{"speaker":"林委員","kind":"意見","question":"そうすると、９９.４％という数字は、これも逆に言うと、異常に高い数字だろうと思うんですよね。それから、先ほどの約７４％という数字からすると、９９.４％というのは、相当な高率という言葉があるのかどうかわかりませんけれども、予定価格を下回っているという意味でいうと仕方ないのか。","respondent":"阿部経理課長","answer":"結果的には、今、委員がおっしゃったように９９.４％ということでしたけれども、ある面では、区側の積算がきちっとなされているという面もあり得るでしょうし、ただ、先ほど申し上げたとおり、そのほかの空気調和設備以外の工事については、やはり９０％台ですので。","voiceIndex":34,"id":"exchange-012"},{"speaker":"林委員","kind":"質問・要望","question":"そうすると、予定価格の計算をするときにも、そういう区の財政のこれからというものを精査していかなければいけないなというふうに思いますので、私たち素人が判断して、この予定価格が高いよとか安いよとか言える問題ではないと思いますので、これからのいわゆる財政の運営には、相当シビアな考え方で挑んでいっていただきたいなというふうに思いますので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"安全性というのは、ちゃんと確保できるのでしょうか。やはり深夜、また早朝なんかも、状況によってはこの辺は小さい家族連れのファミリー層も多いので入られる、また、子どもだけが入る、この一体施設が休みのときもあるわけですから、その辺についてどうなのか。ここはちょっと勉強のためにどういうことなのか教えてください。","respondent":"宍戸施設整備課長、阿部経理課長","answer":"これは２４時間使えるのかどうなのかというご質問ですけれども、実はコミュニティ広場を夜間閉鎖するのかどうなのかという問題ともかかわってくるんですが、もう今はいませんけれども。ＪＶの場合の責任ですけれども、実は説明の中でも申し上げたものですけれども、例えば、このＪＶの場合には、代表者というのを置きます。","voiceIndex":37,"id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"１つだけ。この３社になると、なかなかまとまりというのがつきにくいのかなと。特に建物なんかは責任なり施工なりというのは、３社それぞれ三様の考え方も出てくると思いますので、ほかもそうなんですが、２社ぐらいのＪＶに持っていったほうがいいような気がするので、それだけちょっと意見として述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私はもっと部屋数が増えたのではないかと思うんですけれども、こういうときにどういう考え方でつくっていくのか、そこのところを聞きたいと思うんですけれども、どうでしょうか。","respondent":"宍戸施設整備課長","answer":"確かに指定建ぺい率が６０％のところ、計画建ぺい率が４２.２４％、それから指定容積率が２００％のところ、計画容積率が１３５.５２％と、少し余裕があるように見えるかと思いますが、１つは、前面道路が５ｍというふうな関係で、一定の高さ制限なんですが。","voiceIndex":55,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、私には今ちょっとよくわからなかったんですけれども、制限のところは目いっぱい使ったということなんですか。そこのところはどうでしょうか。","respondent":"宍戸施設整備課長","answer":"建ぺい率については、法規制からすればもう少し建てられたかもしれないですけれども、いろいろ諸条件等を勘案してこの建築面積に落ち着いたというものです。","voiceIndex":57,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"例えば、ファミーユ下神明なんかで、近所の人たちがもっと小さくしてくれという声があったんだけれども、やっぱり大きくしましたよね。施設をどういうふうな考え方でつくっていくのか。要するに、ここの場合だと、部屋数をどういうふうに確保していくのかというのは、私は行政側のほうの姿勢をもっと積極的にやっていく必要があるというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"何部屋できて、何人の方が入居できるのか、そういう数字をちょっと教えてくれますか。","respondent":"宍戸施設整備課長","answer":"新高齢者住宅ですが、全部で９０戸できます。八潮等の住替え住宅がそのうち２０戸というふうな内訳です。","voiceIndex":60,"id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"単身用が何戸で、３Ｋのファミリーというか、家庭用というのは何戸ですか。","respondent":"日下部企画部長","answer":"ですから、単身の方は基本的に８２人、世帯用というのも高齢者世帯を前提にしておりますので、２人世帯ということになりますと、合わせて９８人、約１００人の方が入居可能と、そういうことで計画をしております。おおむね１００人です。","voiceIndex":64,"id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"屋上に太陽光をつけるんですか。この辺をちょっと説明してくれませんか。","respondent":"宍戸施設整備課長","answer":"屋上に１０kwの太陽光発電設備を設ける予定になっております。","voiceIndex":66,"id":"exchange-021"},{"speaker":"林委員","kind":"質問","question":"単純に高齢者の住まいということで、ケアとかいろいろなその他のものはつかないんですか。","respondent":"宍戸施設整備課長","answer":"それと、それに加えて、各住戸には、緊急通報ですとか、見守りの機能というのが組み合わさってございまして、トイレですとか、それから、居間はもちろん、気分が悪くなった場合には、この下の支援センターだと思いますけれども、こちらのほうに通報が可能だということと。","voiceIndex":68,"id":"exchange-022"},{"speaker":"林委員","kind":"質問","question":"そうすると、ここに入居する人の入居費用というか、入居費というのは、そういうような付帯されるケアの分も入ってくるわけですか。高齢者住宅はほかにもあるでしょうけれども、ここは特別にそういうようなケアつきという触れ込みで募集をかけるというふうになっていくわけですか。","respondent":"金子企画財政課長","answer":"今、施設整備課長が申し上げた見守り機能等々については、これの費用負担もいただくというふうな形になっております。","voiceIndex":70,"id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"一般の既存する高齢者住宅にプラス付加価値がついていますよという、そういう形で募集をかけていくというふうになるわけですね。わかりました。それから、２６ページのＪＶが２つで応札をしているんだけれども、これは問題ないんですか。２つあればいいと。","respondent":"阿部経理課長","answer":"第２グループは３社ということでした。これは格付で第１グループはＡ、第２グループはＡからＣというふうなことがあったんですけれども、実は今申し上げた第１グループのほうに申し込みが偏りました。結果としてこの２グループができたです。","voiceIndex":72,"id":"exchange-024"}]},{"id":"topic-02","title":"８番目、第８６号議案、大崎駅西口南地区関連歩行者デッキ整備工事委託契約","agenda":"８番目、第８６号議案、大崎駅西口南地区関連歩行者デッキ整備工事委託契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"これが１点聞きたいと。西口南地区のところでは、以前の説明ですと、権利変換がいろいろうまく進んでいないという説明があったんですが、その後どういうふうになっているのかということ、これが聞きたいということと、もう１つは、このデッキの、今回は５億２２３万６,０００円なんですけれども、この中での国の補助金がどういうふうに幾らになっているのかということを伺いたい。","respondent":"三宅都市開発課長","answer":"ご質問の中でもございましたが、やはりグレードアップ分というのがありますので、その辺は考慮して、補助対象の２分の１が１億３,４４０万円ということですから、２億６,８８０万円程度がその標準のデッキの工事であると見込んでおります。","voiceIndex":87,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１点目のほうですけれども、先ほど、権利変換の合意が、ほぼ合意できる段階だというお話なんですけれども、そのほぼ合意というのは具体的にどういうことなのかということを伺いたいことと、やっぱり基本的にこの本体といいますか、このデッキは再開発と結ぶデッキですから、本体のところがまだはっきりしていない時点で、これが先に契約をしていくわけですよね。","respondent":"三宅都市開発課長","answer":"実際に全国でさまざまなそういう公共施設の整備に実績があるというところを見込んでのお願いであるのと、あと、こちらの都市開発課のほうでも、土木職の職員を配置してその中身も見るという体制にしております。","voiceIndex":89,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"この合意できない人は、結局、当初、再開発の場合ですと、じゃあ、出ていくかということになっていくのでしょうか。今合意できない人は実際にどういう選択肢があるのでしょうか。グレードアップのところなんですけれども、夢さん橋からずっと同じ仕様でやりますよ、そういう話だと思うんですけれども、私がちょっと聞いたのは、いわゆるグレードアップというのはどういう考え方なんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"自分たちの開発事業者のところでグレードアップできるのであれば、税金投入、補助金をやる必要というのは全くないというふうに私は思うんです。この問題はその問題で指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"全く話が聞いていてわからないんだけれども、国でやると約２億６,０００万円で、品川区がやると約５億２００万円というような話しっぷりをしているんだけれども、この５億２２３万６,０００円というのは、財源はどういうふうに分かれているんですか。","respondent":"三宅都市開発課長","answer":"財源ですが、まず国費が先ほどの１億３,４４０万円です。整備費などにつきましては、今、先ほどから出ている再開発の西口南地区などのご負担をいただいているという状況です。ですから、国費に対して区費が同じだけ１億３,４４０万円、残りにつきましては地元からです。","voiceIndex":95,"id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"国がやると２億６,０００万円かかるのを、何で品川区が５億円でやるんだというような話しっぷりが出ていたから、正しくは財源がどこから出されて、品川区は幾ら負担をしてこのデッキに費用をかけるのかというのを私たちは知りたいので、今言われたように、約１億３,４００万円、その品川区からの財源の出費があって、残りの３億７,０００万円ぐらいが事業主からの負担だと。","respondent":"三宅都市開発課長","answer":"はい、おっしゃるとおりでございまして、補助対象事業というのは国でおよそこのぐらいの標準の仕上げだとこのぐらいですねというのを国と区が半々ずつ持つという、そういう補助の制度なものですから、ですから、国の標準で行くと幾らかという話を先ほどしておりました。","voiceIndex":99,"id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"それで話が、私が言いたいことを言うんだけれども、実はここで夢さん橋で大崎の皆さんが楽しんでいる行事が１年に一遍あるわけだけれども、その行事に今までは大崎ニューシティからこういうデッキ、ペデストリアンデッキのような場所から使わせてもらっていたんだけれども、ここ２年ぐらい使用禁止になって、今年も夢さん橋から、大崎ニューシティのほうではなくて。","respondent":"三宅都市開発課長","answer":"おっしゃるように、まだこれから契約するという段階ですので、そういう話はまだ出ていないんですけれども、委員ご指摘のような点もありますので、今後そういうお話も間違いのないように何かの形で約束といいますか、ご協力いただけるように気をつけてまいりたいと思います。","voiceIndex":101,"id":"exchange-031"},{"speaker":"林委員","kind":"質問・要望","question":"この資料の裏にある地図で行くと、この先に工事をやらなければいけない部分があるのかなというふうに素人の目で見るとあるから、いろいろな向こう側との協議をするチャンスは何回もあると思うので、こうやって行政がせっかく財政負担をしていく中で、区民の人が喜べるようなことを、ただ工事をするというだけではなくて、先のことも含めて話し合いをしておいていただきたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-032"},{"speaker":"須貝委員","kind":"確認","question":"確認です。今回のものも何らつくるデッキに関しては、従来のものより高級になったとか、そういうことではなくて、そのままの流れで設置していくということではないかと思うんですが、それをちょっと確認ということと、それと、我々は建築に関しては素人ですが、建物とデッキというのは、だれが見ても構想があるわけですよね、つくっていく過程で。","respondent":"三宅都市開発課長","answer":"１点目ですが、デッキの仕様ですけれども、こちらにつきましては、今まで整備してきたものと同水準で継続、延伸してまいります。","voiceIndex":104,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"それが何で一体の建築に対して最初から織り込まれなかったのかというのが、ちょっと最初から工事として一体工事、契約の中に私は組み込まれていいんじゃないかなと、いや、最初から全然つくる予定がなかったんだよというんだったら、今おっしゃるとおりだと思うんですが、その辺はやっぱりこういうふうな手法をとらないと、まとまってつくっていかれないということなのでしょうか。","respondent":"三宅都市開発課長","answer":"実は、ちょっとこの図で見にくいかもしれませんけれども、このデッキはあくまでも道路部分です。それに対して建築のほうは民地、民間の敷地ということで、どうしても契約自体は分ける必要があるというところから別の契約でやっております。","voiceIndex":106,"id":"exchange-034"},{"speaker":"堺委員","kind":"確認","question":"ちょっとこの図面だけ見たのではよくわからないので確認だけさせてください。３２ページの下に平面図というのがあって、太い部分と、それから先が細くなっていますよね。ここで延長が約５６ｍというのは、この太い部分から細い部分の先端、ここまでが５６ｍということですか。それで、この細いところは何なんですか。階段で下におりるのか、ちょっとよくわからない。","respondent":"三宅都市開発課長","answer":"長さにつきましては、平面図で見たときの中心でとって約５６ｍということでございまして、この右下に細く伸びているのは階段で地上におりていくものです。","voiceIndex":108,"id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"そうすると、将来的にはそっちまで延伸する、このデッキが延伸していくという理解でいいんですか。","respondent":"三宅都市開発課長","answer":"はい、こちらのＤ地区の南地区と書いてある再開発ビルのところも同じ高さでデッキの延伸部が建物の一部としてつくられていきますので、そこにこれがつながっていきます。","voiceIndex":110,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどから言っていますけれども、国標準から言っても、すごくグレードアップしていく、国の標準では２億６,０００万円が標準なんですが、そこに事業者負担自体がもう既に３億７,０００万円、それを超える負担を自分たちもしている、それだけできるところになぜ補助金を投入する必要があるのか、これはやっぱり筋が通らないというふうに思います。ですから、今回の契約は賛成できません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-037"}]},{"id":"topic-03","title":"鮫洲運動公園改修工事（遊戯コーナー）請負契約","agenda":"鮫洲運動公園改修工事（遊戯コーナー）請負契約","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"フットサルが野球の２つの面と別にあるんですけれども、これは野球２つと、フットサルも同時に使える、そういうことで想定しているのかというのが１つと、あと、ホームベースとか、ピッチャーのマウンドと言ったらいいんでしょうか、各ベースのところがアンツーカになっているんですけれども、サッカーで使う場合は、このアンツーカのところはどういうふうになるのか、とりあえずそこのところを２つ。","respondent":"藤橋都市整備下水道課長","answer":"３点のご質問にお答えいたします。１点目のバックネットの関係ですけれども、現在のグランドの敷地が約９,５００m2、非常に狭い土地です。そこを一応３面の形がありますけれども、実際的には２面、しかもその２面の中では、外野の方が交差している中での利用でございました。","voiceIndex":123,"id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、サッカーでやるときはこのアンツーカのままで、サッカーのときはアンツーカの部分を埋めるとか、技術的に可能じゃないのかなと思うんですけれども、そこら辺のところはどうなのかなと思うのと、あと、人工芝に対してはいろいろ意見もあって、特にスライディングをやったりすると、やけどをしたりとか、そういう心配もあるんですけれども、ベースの間の走塁スペースといいますか。","respondent":"藤橋都市整備下水道課長","answer":"したがって、少年の利用を前提とした形ですので、やはりスライディングしたり、そういうことを経験をして利用していただきたいという思いから、このグランドの部分につきましてはアンツーカを残してございまして。","voiceIndex":125,"id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この鮫洲運動公園のところは、今まで少年野球の方々が優先使用でやったところ、使用料も無料でやっていたところなんですけれども、今度はいろいろ利用料等が発生するような話を聞いているんですけれども、可能な限り、私は今まで、とりわけ少年野球にかかわってずっとやってきたという経過も踏まえて、そういう利用のほうも検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"それが一番大きな理由かと思うんですが、そうすると、これから品川区もあちこち運動公園、これから荏原平塚中学校の跡地なんかもありますが、やはり近隣が環境に対して厳しくなって、粉塵等ということは、洗濯物、あとは家の中に砂ぼこりが入るということになると、日常茶飯事という状況になると思うんですが、今後はやはりそういう運動公園になるようなところは、人工芝に持っていかないとだめだと。","respondent":"藤橋都市整備下水道課長","answer":"それからあと、平成元年からいわゆる土ぼこりに対する対応を区でやってきておりまして、これまで雨水ますの設置ですとか、土の入れ替え、防塵ネット等の整備を行いまして、約９,５００万円ほどかけてやっておりましたけれども、現在でも地域の方々から多くの苦情。","voiceIndex":128,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、時代とともにそういうふうに変わってきたならば、近隣の住環境を見て、こういうふうに人工芝に整備しなければいけないような感じがありましたら、やはり積極的に進んでいかなければいけない、区の財源も投入していかなければいけない時代が来たんだなと、ちょっと今日見て思いましたので、ほかのところもこれからやるかと思いますが、いろいろ検討してやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-042"},{"speaker":"本多委員","kind":"意見","question":"これまでのグランドの使い方や近隣への配慮等で難しかったんだとは思うんですが、夜間照明等の整備が、近隣配慮で非常に難しかったんだとは思うんですが、検討されたのかどうか、その点だけお聞かせください。","respondent":"藤橋都市整備下水道課長","answer":"現在このグランドにつきましては、昼間の開放を前提としています。ここはいわゆる有料施設として今検討を進めているところでございまして、夜間の利用は考えてございません。","voiceIndex":131,"id":"exchange-043"},{"speaker":"本多委員","kind":"質問・要望","question":"近隣に配慮しながら整備を進めていくことは当然だと思います。これだけのいいグランドが改修されるので、より有効に使えるように、ここに限らず、区内のグランドが夜間照明、ナイター照明などを有効に使えるように考えていただければなと。近隣にもちろん配慮しながら、難しい部分もあるかもしれませんが、有効に進めていただければと思います。要望的なことを申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-044"},{"speaker":"土井委員","kind":"質問","question":"そういう公園もあったので、何かそういうバランスみたいなことを、日常的な手入れも含めてこれからやっていかないと、また見えないから何かがあったとかという話にならないようにしたいと思うんですが、そこら辺は何か考え方というのはあるんですか。","respondent":"藤橋都市整備下水道課長","answer":"設計段階で樹木医に見てもらったのと、それからもう１回樹木医に見てもらって、この樹木の配置が適切なのか、組み合わせがいいのか、あるいは樹木にも病気がありますので、そういったものがないかすべてチェックして。","voiceIndex":134,"id":"exchange-045"},{"speaker":"堺委員","kind":"質問・要望","question":"それからもう１つは、ともに工期の関係なんですけれども、平成２３年３月、遊戯コーナーは３月１５日で、グランドが３月３１日、平成２２年度末までには両方とも完成させるという、同時期に両方が使えるようにしていくということなんでしょうが、遊戯コーナーのほうについては確かにそのぐらいかかるのかなと思いますけれども、グランドについては、何かもっと早くできないかなという。","respondent":"藤橋都市整備下水道課長","answer":"そこで、グランドにつきましては、本当に申しわけございませんが、これは目いっぱいの工期でございまして、実は今、区長杯については大会が終わって利用されていないんですが、これから大井少年野球軟式交流会等も１１月頭に予定されておりまして。","voiceIndex":136,"id":"exchange-046"},{"speaker":"林委員","kind":"質問","question":"グランドのほうから行きます。さっきの説明の中に、小学生対象にという野球の件はあったんだけれども、中学生は使えないという仕組みというか、決まりにしていくということでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"私ども、運用の仕方についてはまだ決まっているわけではございませんが、今、検討している状況で行きますと、現在、ここのグランド自体が少年の野球に利用した形で地域にすごく根ざしています。毎週木曜日にはサッカーもされているといった状況です。","voiceIndex":138,"id":"exchange-047"},{"speaker":"林委員","kind":"質問","question":"使うのに有料でしょう。そういうことも考えると、条例改正して、小学生が使うというふうに決めておかないといけない。それから、先ほど言った塁間の距離、それからピッチャーのマウンドとホームベースの距離も全然違うわけですから、そういう施設が安全に使えるようにという配慮もしていかなければいけないなというふうに思います。ピッチャーマウンドは持ち上げてなく平らでつくり上げていくんでしょう。","respondent":"藤橋都市整備下水道課長","answer":"今の考えているマウンドにつきましては、マウンドの部分は、例えばサッカーで利用したときでもマウンドの部分が入らないので、少し盛る形でのマウンドを考えてあります。","voiceIndex":140,"id":"exchange-048"},{"speaker":"林委員","kind":"提案","question":"書いてはいないけれども、自転車の駐輪場もつくられるのだろうと、３６ページはそういうことが説明されていないので、それを１つお願いしておきたいのと、それから、遊戯コーナーで、しばしば子どもたちのニーズにというか、アンケートというか、リクエストに沿ってつくるというのは、区が、区長が提案した子どもの公園をつくりますという、その公園とはこれは別なんですね。","respondent":"藤橋都市整備下水道課長","answer":"ただ、それは用地の確保にかなり時間もかかるということから、当面の間、いわゆる公園の改修の中で子どものアイデアを活用できないかということを考えたときに、既存の公園の形態ですとか、樹木の配置状況、さまざまな制約のある中で。","voiceIndex":142,"id":"exchange-049"},{"speaker":"林委員","kind":"質問","question":"グランドのほうはできるだけ安全に子どもたちがスポーツを純粋に楽しめるように、関係者の人とよく協議をして決めてほしいと思います。平成２０年に打ち出した子どもの公園をつくりますというのは、これではなくて、まだまだその考えは生きていて、これから子どもの公園をつくっていきますというのは、新しい２期目の区長の思い入れがあるというふうに私たちは理解をしておくことですか。","respondent":"藤橋都市整備下水道課長","answer":"ここについては、１,５００m2という極めて小さい土地ですが、ここでも子どものアイデアを５つほど採用する予定でございまして、ここが第２号の公園というふうに考えているところです。","voiceIndex":144,"id":"exchange-050"},{"speaker":"林委員","kind":"質問","question":"第１号、第２号となっていくわけですか。ただ、公園と言っても、例えばここをそういう思いやりを込めて子どもたちのアイデアを生かしていくと言うけれども、一般的に考えてこの公園には、例えば旗の台の子どもは行けないんですよ。だから、そんなにあせらずに先をしっかり見据えて、期待をしていますのでお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問","question":"今の関連で、二葉四丁目のところのＪＴ跡地は上と下があるんですけれども、どっちのほうをその計画、子どものアイデアを取り入れた公園にするんですか。","respondent":"藤橋都市整備下水道課長","answer":"住所で行きますと二葉四丁目１３番の土地でございまして、いわゆる交差点の部分の坂の上のところの土地です。","voiceIndex":147,"id":"exchange-052"},{"speaker":"浅野副委員長","kind":"質問","question":"１点お伺いしたいんですけれども、遊戯コーナーのほうですが、子どもたちがいろいろなアイデアを、知恵を絞って、どきどきわくわくのこのような遊具ができてくると思うんですけれども、先ほどお話のありましたとおり、全く新しい、区も経験をしたことのないような多分遊具が出てきていると思います。","respondent":"藤橋都市整備下水道課長","answer":"公園の遊戯施設につきましては、国の安全基準というものがございまして、施設と施設の離隔ですとか、それは細かいところで規定があります。それの安全の基準を確保しつつ、今回、少し考えましたのは、例えば外から見える位置がどうであるのか、それは外からの見通しの面です。","voiceIndex":149,"id":"exchange-053"}]},{"id":"topic-04","title":"請願・陳情調査","agenda":"請願・陳情調査","exchanges":[{"speaker":"林委員","kind":"質問","question":"結論を出すということで結構ですけれども、これは意見書を出してくれということですから、意見書を出してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-054"},{"speaker":"林委員","kind":"質問・要望","question":"時期があると思うので、できるだけ早く、その意見書作成についての委員会を開いて決定をしていただきたいなと思いますので、委員長によろしくお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-055"},{"speaker":"土井委員","kind":"意見","question":"我々としても賛成です。要するに、全国一律に決めた基準で東京ははかれないんだということをみんなで認め合ってもらわないと、何か東京だけ得をしているみたいにみんなは思っているけれども、実は中身は全然違うわけで、その辺をこれからどう宣伝していくかのほうがよほど重要な課題ではないかなと思いつつ、とはいえこれは意見書を出しましょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":169,"id":"exchange-056"}]},{"id":"topic-05","title":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"行革委員会で調査事項になったのは昨年度の行革委員会なんですよね。荏原第四中学校と杜松小学校の跡地利用については。行革委員会でというふうにおっしゃったんですけれども、行革委員会で特定事件調査としてやっていたのは昨年度の委員会なんですよね。それで、今回は、そういう一般質問で行われて、企画部長が答弁されていたので、当然ここでできると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、扱いはどういうふうになるんですか。明日できるかどうかを行革委員長と調整するんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-058"},{"speaker":"堺委員","kind":"質問","question":"こういうことを私が発言していいかどうかわかりませんが、私も今は総務委員ですけれども、行革特別委員会の委員長を仰せつかって委員会の運営に携わっている身として、確かに今回の一般質問で、この件については、宮崎委員のお話があったような形で出ました。その辺等を含めて委員長のご判断をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、厚生委員会というふうなお話だったんですけれども、私は荏原第四中学校と杜松小学校と、その跡の計画について聞きたいと。荏原第四中学校のほうは私立学校の改築のときにお貸しすると、そういうお話だったんですけれども、そういうところも含めて私は伺いたいと思っているんですけれども、一般質問でのフォロー質問ですから、ぜひさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"今、たまたま隣に行革委員長がいるんですけれども、荏原第四中学校、杜松小学校の荏原東地区の一貫校ができた後の活用について、昨年度、行革でもどうするかということを議論して、一定のまとめをして提言も出したんですけれども、今年度の行革でも荏原第四中学校、杜松小学校の空いた跡の件については議論しているということなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-061"},{"speaker":"宮崎委員","kind":"質問・要望","question":"行革委員会の今年度の調査事項というのは決まっているわけですよ。そこに荏原第四中学校、杜松小学校のその後の利用計画を今年度の行革委員会でやることになっているというふうに私は知らなかったんですけれども、そこのところをちょっと確認していただきたい。一般質問のフォローについてどうですかということがあったんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問","question":"調査事項ではないんですよ。だから、計画があれば、それは総務委員会になるんですから、行革委員会の今年度の調査事項になっていないんだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"今年度の行革委員会の調査事項は何なのかということなんですよ。それを杜松小学校、荏原第四中学校の跡利用を今年度の行革委員会でやるんだということになっている、それはそうなんですけれども、なっていないからここで質問するんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-064"},{"speaker":"宮崎委員","kind":"質問","question":"調査事項になっているというふうにおっしゃっていたんですけれども、やっぱり私はそれは納得できませんよ。今まで今年度の行革委員会でそういう議論をしていないんですから、一般質問のフォローというのをここで各常任委員会でやるんですから、関連するものは一般質問のフォローは常任委員会でやるんですよ。だから、それができないということは、私はその仕切りはほんとうにおかしいと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"それは納得できません。そんなの納得できない。そんな質問を封じるようなやり方は断じてやってはいけないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-066"},{"speaker":"須藤委員長","kind":"質問","question":"いやいや質問を封じるのでなくて、仕切りがありますので、その仕切りを崩していったら、委員長としての責任がとれなくなりますので、ご理解のほどよろしくお願いします。ほかにいらっしゃらないようですので、一般質問にかかわる所管質問につきましては終了いたします。ほかにその他で何かありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":49815,"voices":201}},{"id":"h22-20101026-6","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"区民委員会","time":"午前１０時０２分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに、(1)プレミアム商品券発行事業への助成","agenda":"を行います。 初めに、(1)プレミアム商品券発行事業への助成","exchanges":[{"speaker":"石田委員","kind":"質問","question":"これ、プレミアム商品券ですからお金と同じ扱いだと思うんですが、おつりが出るところと、出ないところがあるということを聞いて、ある商店では、これを安いもの、例えば１０円のものを買って、現金化ではないですけど、そういうのが多発したところはおつりとして現金を出すということをやめたいとかというところもあれば、また、なかなかおつりが出ないと使い勝手が悪いというような面も。","respondent":"諸岡商業・観光課長","answer":"おつりの件ですけれども、そもそも目的からいいますと、商店街振興ですので、例えば５００円券で１００円だけお買いになって、４００円現金でお返しすると、その４００円を持って、大型店で物を買われてしまいますと、そもそも商品券、プレミアムの意味がなくなりますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"１点。これまでの経緯だと、過去の実績では完売という中で、どういう想定をなされているのかなという思いがあります。たしか、前回実績は２週間程度と伺ったので、その前回実績と、今回どのように想定されているのかなと思います。おおむね前回実績２週間程度であれば理想的というか、適正だなと思いまして、想定だけ伺えればと思います。","respondent":"諸岡商業・観光課長","answer":"昨年の秋、それから今年の春、いずれも１カ月ですので、今回についても大体１カ月ぐらいと見込んでおります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"意見","question":"１カ月というのはとても大事なことだなと思っています。なれていらっしゃる方、リピーターの方は手に届くにしても、例えば引っ越してきたばかりの方も含めて、まだまだ初めて購入される方には、それぐらいの想定が望ましいのではないかなという思いがするので、それだけ意見として。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"菊地副委員長","kind":"質問","question":"私、財源のところでよくわからないんですけれども、当初予算で６,０００万円の予算を組んでいるんですかね。それで、今回のこの３,０００万円分というのは、そのうちの半分という考え方でいいんですかね。そこを聞きたい。それから、取扱店のところで、実際に区内の商店総数に対しての比率というか、総数はどれぐらいあって、実際に取扱店はどれだけなのかというところを教えてもらえますか。","respondent":"諸岡商業・観光課長","answer":"予算の件ですけれども、春、秋、大体ほぼ同額で予算のほうは計上しておりまして、春も３億円で、３,０００万円のプレミアム、プラスいわゆる事務的な経費ということで、ほぼ同額で予定はしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地副委員長","kind":"質問","question":"そういう中で、例えば今回の補正を使ってさらに上乗せをするだとか、そういう考え方というのはあってもいいような、今の商店街の状況なのではないのかなと思うんですけれども、その辺の論議というのは実際にあったのかどうかというところと、それから、こうやって補助を出していくわけですから、実際に、今８０％ぐらいという話がありましたけれども。","respondent":"諸岡商業・観光課長","answer":"商店街の関係ですけれども、どれぐらいの実態にあるのかについて今、調査をしていますので、もう少しこの辺は、なかなか、商店街、店がなくなったり、増えたりということで難しいんですけれども、一定の調査を行おうということで予定はしています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"製造業ほどではないんでしょうけれども。だから、その都度、その都度やはり、もう少し強化しなくちゃならないんじゃないかということも含めて、庁内での議論なり、議会での議論なりがもう少し必要なんではないのかなという思いがありますので、その辺も今後の課題としてぜひやっていっていただきたいし、議会にその辺も報告していただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"山路委員","kind":"質問","question":"非常にこのプレミアム商品券は地元では評価が高いんですけれども、私どもに相談に来る方は、加盟店でなくても使えるようにという方が多いんですね。加盟店と非加盟店とを一緒にすると、加盟店はお金を払って、区商連に入っているわけですよね。商店街全体の、何回かこれも一般質問の中でやりましたけれども、その辺は絶対難しいんでしょうか。交渉でどうにかなるものなんでしょうか。","respondent":"諸岡商業・観光課長","answer":"ですから、商店街の組織力強化の一環としてもすごく、このプレミアム商品券は有効だということで連合会でもとらえておりまして、なるべくこれを機に連合会、あるいは商店会に加盟していただいて、取扱店になっていただきたいというような取り組みをしていると聞いています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"商品券をうちでも使えるようにというので、急いで加盟したという話を聞いて、今、課長が言われたとおりなんですけれども、加盟していないというのは全体の商店の何パーセントぐらいあるんでしょうか。","respondent":"諸岡商業・観光課長","answer":"実数、厳密に調査しておりませんが、大体８０％ぐらいが加盟されていて、残り２０％ぐらいが非加盟というような状況だろうと思います。この辺がもう少し、例えば先ほどもご質問がございましたけれども、詳しく調べて、申し上げたいと考えています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"山路委員","kind":"意見","question":"全部、区商連に加盟されたらいいんですけれども、これを機会にどんどん増えているということを言われているのでいいんですけれども、使う側に立ったら、加盟店にメリットをあげて非加盟店も使えるようにというのは、これは検討を今後できないのか。","respondent":"諸岡商業・観光課長","answer":"基本的に、非加盟の中で、大型店とかという一定のところにつきましては、このプレミアム商品券の性格上、難しいかと思いますけれども、商店街で非加盟のところについて、難しいところがありますけれども、それで使えるようになると。","voiceIndex":20,"id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"来年度の予算、もう今、予算編成されていると思うんですけれども、これを続けていくのか。だったらば、一度バルーンを上げちゃったんだから、これを継続してやっていく。緊急的なことで考えているのか、そのあたりというのは非常に、もしやめるときになると、区民には非常に周知が難しいと思うんですけれども、そのあたり、どのようにお考えか教えてください。","respondent":"諸岡商業・観光課長","answer":"秋については補正という考え方もあったんですが、商店街の立場に立ってみますと、商店街の大体、総会が６月ごろに毎年あるんですけれども、その時点で秋やるのか、やらないのか、区として取り組むのかわからないと、商店街としてもこのプレミアム商品券の発行を受けて。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山内委員","kind":"質問・要望","question":"それで、私が言いたいのは、経済がどの状況になったときに、この緊急経済対策といったものを一たん休憩をするというか、やめるのかといった、その判断といったものを庁内である程度、こういう数字になったときに、ちょっと一回やめましょうといった、そういうような具体的な何かお考えがあるのかといったことと、そういったときには、やはりどのように商店街を含めて区民に周知していくのかと。","respondent":"諸岡商業・観光課長","answer":"プレミアム商品券、実際行わないとなった場合のことですけれども、これは非常に難しい部分だと思います。やはり景況判断、景況報告等によって、国全体の経済というよりも、地元の商店街としてどうなんだろうかというところが中心になろうかと思います。","voiceIndex":25,"id":"exchange-011"}]},{"id":"topic-02","title":"高齢者の消費者被害防止に向けた地域での見守り","agenda":"高齢者の消費者被害防止に向けた地域での見守り","exchanges":[{"speaker":"菊地副委員長","kind":"質問・要望","question":"わかれば教えていただきたいのと、それから、最初の説明の中で、ヘルパーさんからこんな通報があったりとかということで発覚するという話がありましたけれども、この中では民生委員さんの方々に協力を仰ぐということなんですけれども、民生委員さんだけではとてもじゃないけれども大変なのかなというふうに思うんですけれども、先ほどあったヘルパーさんだとか、ケアマネジャーだとか。","respondent":"諸岡商業・観光課長","answer":"あと、民生委員さんだけじゃなくてヘルパーさんとか、ケアマネジャーとかということで、これはお年寄りの見守りですので、高齢者福祉課とも連携を図りまして、そういったところに出向いて、相談員が研修ということで講演を行ったり。","voiceIndex":31,"id":"exchange-012"},{"speaker":"菊地副委員長","kind":"質問","question":"そういう中で民生委員さんに改めて、民生委員さんの仕事そのものが、高齢者の方たちの生活状況をつかんでいくというのが一つの大きな仕事なんだとは思うんですけれども、そういう中で改めて民生委員さんにこういうお願いをしていくというのは、改めてそういう高齢者の方との話をする中身として、マニュアル的なものというのは何かあるものなんですかね。そこだけ。","respondent":"諸岡商業・観光課長","answer":"民生委員の皆さん方は前から、そういったお年寄りの被害についての一定の知識もお持ちですし、こちらからも民生委員の皆さん方には毎年１回ぐらいは、状況についてのご報告をさせていただいているところですけれども、最近、また、新手の商法が出てきて。","voiceIndex":33,"id":"exchange-013"},{"speaker":"高橋委員","kind":"質問","question":"センターの体制についてお聞きしたいんですけれども、何人いらっしゃって、予算書を見ていないのでよくないんですけれども、人件費はどのぐらいかかったのかと、１６時まで、４時までしかやらないという言い方はあれですけれども、そこで、夜かけたいと思ったときに、７時まで、第４火曜日はやっていますけれども、予算の関係もあるでしょうけれども、時間の拡大というのがまた。","respondent":"諸岡商業・観光課長","answer":"あと、時間ですけれども、一応、相談時間については４時までということで、その後、相談記録の整理とかということを行っているものです。それ以外にも、相談以外の職員もいますので緊急の場合には対応できますし、また国、都の相談センターでも受付をやっております。","voiceIndex":36,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":12703,"voices":49}},{"id":"h22-20101026-7","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"厚生委員会","time":"午前１０時０２分～午後２時３６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"稲川委員","kind":"確認","question":"確認なんですが、この大井林町高齢者住宅というのは、俗に言うこういう高齢者向け優良賃貸住宅、よく「高優賃」と言われるもので、表現としてはいいのかどうなのか。その選定とかはどうするのか、その辺、ちょっとよろしくお願いします。","respondent":"冨岡高齢者福祉課長","answer":"今後の問題ですが、あわせて今回ご報告しております、この区立の大井林町高齢者住宅のほかに、民間でも旗の台４丁目に民間の事業者によります高齢者住宅等の複合施設の建設を予定をしておりまして、本年度着工で、来年度、もう竣工というところで。","voiceIndex":7,"id":"exchange-001"},{"speaker":"稲川委員","kind":"質問","question":"その住み替えに関してなんですけれども、一般質問でもさせていただいて、やはりこの高齢者福祉の枠を超えた部分というのはすごく出てくると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"この数年の中で、そういう状況というのはいっぱい出てきていると思うんです。したがって、住民とのサービスの関係で、そういうレールを敷いた上でこれからもずっと走っていってしまっていいのかということを非常に疑問に感じていますので、改めてその辺の考え方というのを、指導も含めて、どういうふうな改善を求めてきているのかみたいな区の姿勢も含めて意見を伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"住み替え住宅のどれくらいの見込みかですが、先ほど想定している八潮地区と、それから住宅密集地で、これは個々に、例えば所管につきましては違いますけれども、聞いている範囲では個々に対応していくというところで、上限として、今回の数字ですが。","voiceIndex":10,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"だからどれぐらいのニーズがあるのかなというのをちょっと知りたくて伺ったんですが、やはりその辺の調査というのがされないと、こういう施設建設に当たっては、それこそ効果という点ではあれですから、やはりきちんとその辺は、他の所管であったにしても、ぜひ照会はしていただきたいと思います。この辺についてちょっと伺いたいと思います。そういう点で、改めてちょっと答弁を求めたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それから指定管理の部分ですけれども、やはり指定管理はサービスの向上ということと、民間の活力を活用して、やはり運営の経費、コストを削減していくという目標もありますので、やはりそこで今、民間の力が特に現場のケア等に。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"きちんと調査をしているんですから、数字を照会していただきたいと思います。したがって、そういうところの改善を求めても、なかなか改善されていかないという点がありますので、目が届かない。ぜひその点は、どういうふうに向上できるか、いろいろな個々の状況が出たときに、どういうふうに自治体として質の向上、改善を求める指導をするかというところまできちんと説明していただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"そのことをなるべく防いでいこうということを社会福祉法人は日々のケアの中で努力をしているわけでありますけれども、１００％今のようなお話を防ぐことはできないんですね。","voiceIndex":14,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"それから直営の点では、やはりいろいろ議論はあるところですけれども、やはり頭から１０年前の議論だということで一蹴するのではなくて、やはり直営で考えていくということも合わせて、それこそいろいろなノウハウがあって、やり方があって、切磋琢磨していくんだ、競争なんだとおっしゃっているわけですから、そういう点で１つのいい見本としても、やはり私はやるべきじゃないかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほど稲川委員の質問に対して、高齢者住宅の今後の見通しというか考え方、説明がありましたけれども、その中で区がどんどんつくると土地やまた敷地の問題があるのでというお話がありましたけれども、ならば伺いたいのは、区では土地が見つからないけれども、民間なら見つかるといいますか、できるといいますか、そういう意味なのか、ちょっとよく答弁の意味がわからなかったので。","respondent":"冨岡高齢者福祉課長","answer":"その中で十分に対応しているし、問題があれば指摘をするという段階を経て、最終的には経営会議で審査をいただいて、その結果をまた毎年議会に報告をして説明をさせていただいているですので、信頼関係がなければ指定管理というのはお願いできないわけでありますので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"提案","question":"こういう全体で見ると、福祉サービスの完全市場化は当たり前だという姿勢というのは、やはり問題が残るなと思います。そこで、今日の資料の選定理由に、ケアホーム西五反田の実績のことが選定理由として挙げられていたので、１つ伺いたいと思うんですけれども、さくら会の行っているケアホーム西五反田ですけれども、実際は株式会社マザース、ミサワホームグループが運営を委託しているという話を聞きました。","respondent":"木下健康福祉事業部長","answer":"先ほど福祉構造改革が、社会福祉法人とか株式会社等によって、福祉の現場を壊してきたというようなご発言もあったようでありますけれども、それはとんでもない認識違いだと私は思うわけです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その経過を見ると、やはり行政としての責任が問われる事例が幾つも見られてきたわけで、そのことを指摘をしているわけです。ケアホーム西五反田の株式会社マザース、ミサワホームと呼んだほうがいいんでしょうか。そうじゃなくて、近傍家賃というのがどんなレベルなのか、ちょっとそこは区の考えでいいんですから、大まかに教えていただきたいと思うんですけれども、いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"ケアホーム西五反田の部分の実践経験も評価するという説明をさせていただきましたけれども、さくら会は住宅系があるというのもご案内のとおりかと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚副委員長","kind":"確認","question":"なぜかというと、この指定管理者ということになると、指定管理者として大井林町高齢者住宅等をさくら会が受けたけれども、実際はその先、また別の会社に委託をしているんだということになってしまったら、これはやはりとんでもない話だと思いますので、それで伺ったので、そこだけ確認させてください。何でないのかなと思ったんですけれども、そういう環境対策はどうなんでしょうか。ご説明いただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問","question":"じゃあ、ちょっと変えます。そういう新しい施設をつくるときの、品川区の環境対策というのはどう考えていらっしゃるのか、太陽光パネルや壁面緑化はやはりしっかりできるところから進めていくということが、行動計画から見ても私は必要だと思うんですけれども、いかがでしょうか。","respondent":"鈴木委員長、冨岡高齢者福祉課長","answer":"その部分も委員会の範囲では違うと思いますので、環境のほうになると思います。設計の中ですと、別の設計にもなると思います。前半の部分だけ、理事者の方、お答えいただければと思います。それについても実施していますので、事前の協議をして、やっているところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"しかも周りにできた有料老人ホームが、年金の２倍も３倍もするような利用料を必要としているわけですから、どれぐらいなのか、これもやはり説明する責任が、最終的にはこうだともちろん前置きをしながらも、どれぐらいなのかというのはやはり説明していただきたいなと思いますので、そこはもう１回だけ聞きます。そこが先ほどからの説明ではっきりしないわけです。","respondent":"木下健康福祉事業部長","answer":"大井林町の件については、ケアホーム西五反田のような方式は全く考えておりません。課長がご説明申し上げましたとおり、例えば厨房はそれの専門の会社があるわけです。厨房の調理をする部分。","voiceIndex":30,"id":"exchange-012"},{"speaker":"山元委員","kind":"質問・要望","question":"１点だけ、今、この平面図をずっと見ていますと、住み替え住宅２０戸の中には、広さが若干違う部屋もあるということは、まずこれはどういうことかなということと同時に、逆にほかのこの７０のお部屋のほうはみんな一律になっている。もう１つ、先ほど国から２万５,６００円補助があるということなんですが、広さには関係なく、全戸の皆さんにそれは補助があるのかどうか、教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それから２万５,６００円というのは、これは今、発表している要項で決めている部分でありますけれども、それにつきましては部屋単位で決まっている部分でありまして、ただ所得要件がありますので、あまり高額の方は適用されないということはあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そういったときに、福祉の皆さん方がそういったところで、本当に、じゃあ、聞かれて答弁できるのかと。ですからこういう形にあっても、だから高齢者福祉課長がずっと苦労して説明しても説明し切れない部分というのがあるわけです。ですからそういった点での住み替えの制度についてはそういうあり方がある。答弁を求めるような話でもないから、聞いていてちょっと感想、ちょっと質問させてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"最後の部分ですけれども、私もかつて品川区の職員として保育士をしていた時代もあったので、その時代のことに関しての話があったので、事実を申し上げたいと思うんですけれども、確かに時間内に組合活動は制度として認められていたのであったということですから、それは全然違法でもないし何でもない、そんな批判を受けるような筋合いの内容ではないということを、改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"稲川委員","kind":"確認","question":"ちょっと１点だけお伺いをしたいんですけれども、応募方法の中に、申請書、申告書とあると思うんですけれども、この申告書というのが、例の立ち退きに関する確認書のことでよろしいんですか。","respondent":"間部高齢者いきがい課長","answer":"そのとおりです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"今までの話でも、流れの中で入居者のいろいろと条件については話が出てきていると思うんですが、改めてちょっと伺わせていただきますけれども、応募資格のすべてに該当する方ということで1)から4)まであります。1)、3)、4)ということで、これは客観的に見ても、主観的に見てもわかる。","respondent":"間部高齢者いきがい課長","answer":"劣悪に関するお問い合わせですけれども、劣悪、確かになかなか主観的な要素が入るものですが、私どもといたしましては実態調査する中で、例えば古い木造モルタルで雨漏りがするですとか、壁に穴があいているですとか、すきま風が多いとか日照が悪いとか。","voiceIndex":44,"id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"内容の積み重ねということですので、積み重ねる上には何かしらポイントというか、そういうようなもの、計算というか解釈を積み上げの判定基準にしていくんでしょうか。","respondent":"間部高齢者いきがい課長","answer":"判定の基準につきましては、基本的に立ち退きを迫られる方につきまして、優先順位が高くなっております。先ほど申し上げたような劣悪のポイントが何項目がありまして、その多い方ほどポイントが上がるという形になってあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"やはり自分自身も実際の現場というか、経験の中で、結構保安上・衛生上劣悪な条件、先ほど来申し上げている主観という部分がありまして、これによって結構はねられてしまう部分が多々あるような、自分自身の主観としては思われます。しかしそこのところの１つの判定基準の明示化というか明文案みたいものはつくれるものなのか、つくれるものでないのか、ちょっとそこのところのご意見を伺いたいと思います。","respondent":"間部高齢者いきがい課長","answer":"結局劣悪度については、先ほど申しましたように住宅の老朽度をはかるということで、いろいろな見方があるです。保健衛生上ということでは設備、浴室とかトイレだとか、そういう点も含めて見するというものです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなったら、またどなたかが、私有財産ですから入居者を求めるべくどこかに出すわけですけれども、そうなった後、区の手当てというか、明らかに区で認められているわけですから、その中にまた住宅として入ってくる方に対して、後々の補助制度みたいなのはあるんでしょうか。","respondent":"間部高齢者いきがい課長","answer":"私ども福祉部門におきましては、そのあたりはちょっと申しわけないんですが、承知してございません。","voiceIndex":50,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"先ほどの仕切りの上で違うので、これ以上はお尋ねしませんけれども、一応劣悪と認められたその後の手当ても何かできるもので、これは事業部が違うのでご答弁は結構ですけれども、私有財産ですから行政が入るということも非常に難しく、無理なところがありますが、認められた部分に関して、何かしら考えの片隅に入れられて、次の方がこの適用をしないでそこに住めるような何かがあればいいなと思いつつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"初めての質問をします。ちょっと勉強不足で大変申しわけないんですけれども、この現在の高齢者住宅のうち、生活保護を受けられている方は、今現在ある中で大体何世帯ぐらい生活保護受給者がいるでしょうか。","respondent":"間部高齢者いきがい課長","answer":"生活保護受給者の方につきましては、入居者の約３割ほどです。","voiceIndex":53,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"皆さんそうだと思いますけれども、私も地域でこの募集に応募したいけれどもなかなか外れてしまうという方が結構いらっしゃるんですけれども、今回４０名程度ということなんですが、これは毎年４０名だったかと、もうちょっと多かったような気もしたんですけれども、その辺をちょっと１点伺いたいのと、それからこの４点の応募資格という点なんですが、今。","respondent":"間部高齢者いきがい課長","answer":"４点の資格ですが、もともとこの制度ができたのはバブル花盛りし頃で、どうしても立ち退きを迫られるという方が多くて、高齢者はなかなか民間では貸してくれないという中の行き場所ということで整備をした経過がありまして、そういう関係から。","voiceIndex":55,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"過去３年間の実績ということでの紹介があって具体的な状況がわかったので、ありがとうあります。例えば平成２１年度のときには１１８名のうちの１７名ですから、１０１人の方があっ旋制度を利用して入られるような事態になっているというふうに、数字の高は別としても、そんなふうに考えていていいのかどうか、ちょっとその点だけ質問させていただきたいと思います。","respondent":"間部高齢者いきがい課長","answer":"親族の方もいらっしゃらないという方であれば、今、多くあるのは、生活保護にかかっている方だとそのケースワーカーですとか、あと地区の民生委員の方でも書いていただくという例もありますので、緊急連絡先がないから入れないよということはございませんので。","voiceIndex":57,"id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"お伺いしたいのは、導入当時はバブル期の話がありましたけれども、今現在、どういう理由で申し込まれるのか、どういう生活状況の方が増えているか、申し込んでいる方の傾向というんでしょうか、もちろん応募資格はこのままですから、これに当てはまる人というのはよくわかるんですけれども、やはり最近の申し込まれている方の傾向や特徴については、どのようにつかんでいるのか伺いたいと思います。","respondent":"間部高齢者いきがい課長","answer":"ただ、最近は長らく住まわれている方につきましては、加齢に伴い介護保険のお世話になる方も出てきておりまして、大体介護の認定を受けている方が、やはり生活保護と同じ３割程度いらっしゃるというような現状です。","voiceIndex":59,"id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ぜひ、こういう住宅は今後もやはり増設を進めていく必要があると思うんですけれども、最後、その１点はどうかと伺いたいと思います。増設をと言う前に１カ所でよしと思っていらっしゃるのか。高齢者の夫婦用の世帯もあわせて増やす必要があると私は思うんですけれども、１カ所でよしだと思っていらっしゃるのか、増設についてはどうお考えなのか、ご説明いただきたいと思います。","respondent":"間部高齢者いきがい課長","answer":"２人用云々ということがございましたけれども、現在２所帯分しかない、オーク中延にあるわけですけれども、ひとり暮らし高齢者というのが基本的には行政のスパンとして考えるべきことではないのかなというふうに認識しています。","voiceIndex":61,"id":"exchange-026"},{"speaker":"中塚副委員長","kind":"質問","question":"最後に意見だけ述べますけれども、今後は新しいタイプだというお話で最初の例がありましたけれども、先ほどの１つ前の話で、料金はまだわかりませんけれども、部長の話の中で、女性１人厚生年金の方の状況は把握されているという話の含みを思いますと、今の高齢者の多くは国民年金ですからね。とても女性１人厚生年金の料金設定では手が届かないとなってしまったら、やはり困るわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"現在、ご夫婦で住んでいる方でも、６畳一間のそういうアパートに住んでいる方はいるんです。ひとり暮らしと特定すると女性だけになってしまう。そういう人たちもいるんだという現実はやはり１度は検討していただきたい。ですから品川区として、そういう方たちについても暮らしていけるという現実の場は提供してあげるということは、もう少し広げてあげてもいいんじゃないかと思いますけれども、いかがですか。","respondent":"間部高齢者いきがい課長","answer":"今、お尋ねの件で、この大きさがあれば２人で十分住めるというお話ですけれども、確かにそういうご意見があるということは承知をしておりますが、現在の高齢者住宅で対応するのがよいのか、また都営や区営住宅等多くの公営住宅の中で判断するのがいいのか。","voiceIndex":64,"id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"それはそういうところもありますと。あるけれども、品川区としてはそういうことも、要するにメニューとしてこういうものがあるというものを検討するということに、じゃあ、もう少し考えしますと言えば、それで済む話じゃないですか。余計なことを言ったら、一言も二言も反論されるような形になるでしょう。","respondent":"間部高齢者いきがい課長","answer":"今後とも、引き続き検討してまいりたいと思います。","voiceIndex":66,"id":"exchange-029"}]},{"id":"topic-02","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"南委員","kind":"質問","question":"この報告書を受けて、これはどこで今後どういうふうな経過で進めて自治体までおりてくるのかということと、品川区としてこれをどういうふうにとらえて、今後の事業展開にしていこうとしているのかというそのあたり、まだまだそこの部分ではないのではないかと私は思うんですけれども、そのあたりもちょっとこの機会に伺っておきたいなと思うんです。","respondent":"冨岡高齢者福祉課長","answer":"問題意識に対する対応が個々にですが、提言の中では対応するようには出ている部分もありますけれども、ご指摘のように、先ほどの頭の４番のところで、今回、このとらえ方としては、問題点を発見して、それらに対する個別の対応策を考えていくという手法ではなくて、バツ。","voiceIndex":84,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"やはり一番の基本はサービスを受ける方、そして一人ひとりが健康で文化的な生活を営める、そこを本当に基本にして描いてほしいなと思っているんですけれども、このあるべき姿をトータルに描くというのは、そういうところで品川区として、保険者として、介護保険の推進していく立場として、国が出してきた問題に対してそのとおりだと受けとめるのではなくて、こういうふうにあるべきじゃないかみたいな。","respondent":"木下健康福祉事業部長","answer":"今回、品川区が補正予算でお願いしました夜間対応訪問介護の２４時間モデルというのが、在宅をそういう形にするための、国が今、考えている目玉事業なわけですけれども、それを品川区としてもモデルとして取り入れていこうというふうに考えているわけでありまして。","voiceIndex":86,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"それで、例えば在宅にいても施設にいると同じ安心感というんですけれども、施設が今、必ずしもいいというふうにはなかなかなり切れていないし、例えば現状は、入浴のときも個別に入浴するのではなくて、一定程度入れるような状態にしてタオルを掛けて順番待ちになっているとか、それから排泄だって、要介護度４とか５の寝た切りのような身体状況の方は時間で取りかえるだとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-032"},{"speaker":"中塚副委員長","kind":"質問","question":"そもそも、ちょうど１０年ですか。ちょっとこのあるべき姿について、品川区と考えが同じというのであれば、その辺、品川区自身もどういう問題意識を持っていらっしゃるのか、ちょっとお考えを伺いたいと思います。なのでこのバツのところがどういう問題があったのか、何の解決のためにこの丸のほうになっているのか、そこもあわせてご説明いただけますでしょうか。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"南委員がそこの趣旨をちょっと転換されておられたような気がするんですが、というのも、施設サービスと同じような在宅サービス、いわゆる集団ケア的なものを在宅に展開されるのではないかというようなご趣旨と。位置づけの中の「問題点を発見し」という部分で、本文におきましても１７ページ以降、２０２５年の超高齢社会を見すえた課題認識というところでさまざま、前提、負担のあり方。","voiceIndex":89,"id":"exchange-033"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"自分の理念であります高齢者の尊厳と個別性の尊重、その理念を具体化すべきその人一人ひとりの生活を支援していくのに必要なサービスを得ようと思っても、１割自己負担の壁があって、とりわけ所得の少ない方、また収入の少ない方にとっては介護が受けられないというこの現状がどう解決されるのか、この問題をどういう方向で改善しようとしているのか、そこを伺いたいと思うんです。","respondent":"木下健康福祉事業部長","answer":"個別の問題というのは、今現在介護保険を利用するに当たって、日本全体の中でということになると思うんですけれども、例えば同居の家族がいる場合は云々とか、そういうような個別の問題がいろいろあるけれども。","voiceIndex":92,"id":"exchange-034"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"実際使える額の半分ちょっと超える半分強しか使えてないということになるのでしょうか。個々人の状況や、また本人の希望がありますから、皆が皆、限度額いっぱい必要な人もいるだろうし、必要でない人もいるだろうし、そこはどうしても平均値で見るしかない事情もあるとは思いますけれども、先ほどのこちらのご説明の評価がよくわからなかったので、もう１度伺いたいと思います。そこだけお願いいたします。","respondent":"木下健康福祉事業部長","answer":"そのことについては、所得の高が１つのファクターになっているかというと、そういうことはないということをうかがい知ることができるということであります。","voiceIndex":94,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方向にならざるを得ないと推測できるのではないかと私は思うんですけれども、そういうところがある中で、先ほどの説明ではあるべき姿が同じだとひとくくりにしておっしゃったから、私は本当にそれではちょっと個々の状況をどういうふうに改善してほしいかという、利用者なり国民の側の、改善を真摯に求めているそれに対しての解決策がはっきりされない中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-036"},{"speaker":"三上委員","kind":"意見","question":"将来的なことについて、介護の制度はこうあるべきだというような方向性で考えているとは思うんです。介護を受けられる方よりも、受けないで元気な方というのも高齢になってもたくさんいらっしゃいますよね。健康福祉事業部長は、そこをどうとらえていますか。","respondent":"木下健康福祉事業部長","answer":"ご質問の自立支援への対応ですが、介護予防・認知症予防等については、第３期・第４期の介護保険事業計画の中では項目として挙げられ、進められてきたところですが、今回の地域包括ケア報告書の要旨からは外れておりまして。","voiceIndex":97,"id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"こういうふうに思っていくこと自体は、自分なりにそう思っていきたいなと思っているんですけれども、逆に健康の世界から考えたら、保健所長さんのそういう考え方というのはどうなっているんですか。","respondent":"本保品川区保健所長","answer":"日本の今までの健康政策というのは、やはり自分の健康は自分で守るというのが基本的に進められてきたかなと思いますけれども、やはりそれだけでは不十分ではないかという考え方のもとに。","voiceIndex":99,"id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"三上委員の後で、今、すごい質問を聞いてしまったので気が引けているんですけれども、今、コミュニティ全体の環境づくり、共助というようなことで、地域で高齢者を支えるあり方ということで私は伺ったんですけれども、ケアシステム自体、まず私の認識をこれで正しいのかどうかということでお伺いしたいのですが、いわゆる地域で支えていくという部分に主眼を置いた場合に、今までの施設の集約型から。","respondent":"冨岡高齢者福祉課長","answer":"先ほどの提言の中の引用にもありますように、やはり多数の職員を抱えるような従来型の施設とは異なって、軽装備の多様な住宅を前提としてというところで、地域におけるコミュニティにおけるケアというものが中心になっているというふうな論調であると理解をしているです。","voiceIndex":102,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":59279,"voices":108}},{"id":"h22-20101026-8","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"建設委員会","time":"午前１０時０３分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"最後、資料３でコスト比較というのが出てきたんですけれども、そこにわかりやすい感じでＣｏ２の問題がどうなのかというのも出していただきたかったなという。今回かなり詳細な比較調査を行ったというんですけれども、何かこういった調査を行っていく上で参考にした自治体とかはあるんですか。ほかの区とかもこういうのをやっているんでしょうか。","respondent":"齋藤道路公園課長","answer":"今度１１月にも東京都から技術者の会議で検証結果について発表して欲しいと求められています。引き続き土木行政についてはコストを考え、事業を進めていきたいと思っています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"Ｃｏ２の問題についてはここを見ればいいということであれば、若干、何ていうか、今の事実ですとＬＥＤを採用すればもっとずっと排出抑制するところもあるんですけれども、コスト面から勘案すると、導入するまで踏み切るには至らないというような結論だったのかなと思うんですけれども、ちょっと説明にもありましたけれども、これから技術革新などもあると思いますので、そちらをぜひ常に注視していただいて。","respondent":"齋藤道路公園課長","answer":"調査の財源は、夜照度をはかりましたので、職員の超勤代ぐらいのものです。はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"じゃあ、一般財源ということなんでしょうか。財源といいますか、そちらを聞いたんですけれども。","respondent":"齋藤道路公園課長","answer":"器具自体は無償でいただきました。検証したのは、職員がしました。ですから、一般の職員給与費で超勤代からということです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"まとめとして、省エネ街路灯が理にかなうという結果が出たんですけれども、すみません、これは齋藤課長の担当だと思うんですけれども、環境課長としてはこのまとめについて、環境面から考えたらどういう意見になっていくか教えていただけますでしょうか。","respondent":"工藤環境課長","answer":"今齋藤課長から話がありましたように、道路面とドライバーにとって安全運転上支障があるなどといった部分がありますので、私どもとしましても、そういった動向というものは十分に注視しながら、道路公園課、施設整備課、庁舎内。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"ですよね。だから、前の民主党、総理大臣がばーんと目標の数値とか出しちゃったときも、コストがかかるというのがものすごく話題になっていましたけれども、そういう観点においても、コストはかかるけれどもＣｏ２は下がるという結果は出ていても、それでもまだ時期尚早というふうに考えるのかということなんですけれども。","respondent":"岩田都市環境事業部長","answer":"多少高いぐらいであれば、区民の理解が得られれば導入というのも考えたんですが、この資料の２をご覧いただくように、Ｃｏ２排出量もＬＥＤの機械とうちが採用した蛍光灯とほとんど同じ、現在の水銀灯から比べると、ともに約３分の１の排出量に抑えることができる。","voiceIndex":13,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"１０月の頭にここを夜車で走りました。もちろん仕事の関係なんですけれども、ここを車でちょっとわけあって走ることがありまして、突然１０月の頭だったと思うんです、あれ、おかしいな、目が痛い、あそこを走っていて、何か白い感じがしたんです。近所の方とかから、あそこまで明るいと逆に苦情とか来なかったですかというのを聞きたかったんです。あの地域で。","respondent":"齋藤道路公園課長","answer":"車のドライバーの方がまぶしいと感じられるというのは初めて聞きました。ご指摘をいただきもう１回照度については考えなきゃいけないというふうに思います。","voiceIndex":18,"id":"exchange-006"},{"speaker":"若林委員","kind":"意見","question":"最後に、これはさっきもご答弁ありましたけれども、要するに、これはＬＥＤのそういった照明の特徴とともに、輝度、ここら辺の特徴がすごくあるので、ここをうまく利用した、要するに、いっぱい建てるとイニシャルとランニングで、街路灯について言えばこの２０年のスパンで見ると大変にコストがかかるけれども、その他の用途で、設置費用等も踏まえて、こういう特徴を活かした設置の仕方というのを、じゃあ。","respondent":"齋藤道路公園課長","answer":"ＬＥＤには指行性が強いという特性があります。例えば、天王洲の開放護岸に１１基ＬＥＤの街路灯を設置しました。今後は、公園の沿道でないところに設置して、３６０度に照らすタイプのＬＥＤ証明を設置して、これはどういう効果があるか今後検証してみたいと思います。","voiceIndex":24,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"自己規制値を超えたところが足立ということで、各清掃工場の水銀の自己規制値というんですか、これが幾らなのか、あと、実際検出された値はどれぐらいだったのか、それぞれお伺いしたいと思います。足立以降の工場の被害は大分軽いというか、被害金額がおさまるんですけれども、足立の事故を受けて一定の予防的な対策がとられたということなのか、そこら辺もお伺いします。","respondent":"太田品川区清掃事務所長","answer":"自己規制値ですけれども、正確に言うと、０.０５mg/m3という形、先ほど申し上げましたように、平たく言えば１m3に水銀が０.０５mg存在するです。実際の量については、これはわかりません。","voiceIndex":31,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後の再発防止対策が重要だと思うんですが、説明があったんですけれども、ぜひ全力を尽くしていただきたいんですが、先ほどご説明していただいた今後の対策で、どの程度こういった再発の防止できるのかというのは、そこら辺についての見通しというんですかね、それはどうでしょうか。","respondent":"太田品川区清掃事務所長","answer":"今回のことを受けまして、清掃一部事務組合と、それから、２３区課長会と対策についてさらに検討していこうということで、会議体を今後設置していくということで、さらに有効な再発防止策についても検討していくということであります。","voiceIndex":33,"id":"exchange-009"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ちょっと仕組みがまだ何となくよくわかっていないので教えていただきたいんですけれども、この水銀が入っていた可能性があるごみというのは、事業者から排出されたごみの中にあったということは確定していいんですか。普通の家庭ごみの収集ラインの中にあったというふうなルートもあり得るんですか。","respondent":"太田品川区清掃事務所長、岩田都市環境事業部長","answer":"そこの場所は事業者、あるいは、区収、分けてございませんので、今回の排出者についても事業系とまでは確定してございません。そういう意味でいくと、この報告書にもあるように、一般家庭のことも否定はできないということ。この問題は清掃一部事務組合の被害ということですけれども、回りめぐって、その財源は２３区が負担をしている負担金から出されることになりますので。","voiceIndex":35,"id":"exchange-010"},{"speaker":"阿部副委員長","kind":"質問","question":"それで、先ほど家庭ごみルートでもあり得るかと伺ったのは、家庭が出したからということではなくて、例えば、国道沿いに住んでいる方なんかから時々聞くんですけれども、自分の住んでいるエリアにいない人たちがごみの集積場所に車でやってきて、ごみを置いていく人たちがいると、それは非常に困るというようなことを、家庭ごみレベルでは時々聞くんですけれども、例えば、これは可能性。","respondent":"岩田都市環境事業部長","answer":"先ほど説明しましたように、特定はできていないんです。私が申し上げたのは、一部事務組合と清掃主管部長会の議論の中でそういう推測の議論をしております。ですから、搬入した収集運搬業者が故意にやったことも考えられるんですね。過失はないんでしょうけれども。","voiceIndex":38,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"すみません、ちょっと素朴な疑問なんですが、内訳戸数の中で品川区の戸数が１２戸だということですが、というのは、資料に記入していただくことはできないのかどうかということを聞こうと思ったんですけれども、あと、休日相談窓口というのを品川区でやっているということですが、どんな対応をしているのか具体的にお伺いしたいなと思います。","respondent":"柏原住宅担当課長","answer":"内容につきましては、書き方であるとか、それから、もう一般的な住宅の相談であるとか、そういったところが主でございまして、前回の８月の募集の際は、荏原文化センターで２５件、きゅりあんのほうでは５件、それから、今回と同様の募集を行いました５月の募集の際には。","voiceIndex":45,"id":"exchange-012"},{"speaker":"安藤委員","kind":"確認","question":"相談の内容ですけれども、一般的な住宅の相談ということでありましたが、例えば、１２月には高齢者住宅の発表があったりするんですが、そういうこともあわせて、必要だと思われる方には積極的にご案内をしたほうがいいと思うんですけれども、そういったことも行っているのかどうか、確認したいと思います。","respondent":"柏原住宅担当課長","answer":"基本的にはこちらのほう、都営住宅等のご案内ですので、そういったところが基本のお話にはなるんですけれども、それ以外の住宅につきましても、ご相談があった場合は区役所のこういう窓口でやっていますであるとか、そういったところのご案内はさせていただいています。","voiceIndex":47,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"何か住宅担当でも配っている高齢者住宅についてみたいな紙があるんですけれども、これは何かいろいろな住宅の案内が書いてあると思うんで、住宅に困っている方というのはやはりいろいろな情報があったほうが選択肢も増えると思いますので、聞かれたら答えるというのではなく、ぜひ積極的に区のほうからも、困っているときにはこういう住宅制度もありますよというご案内をしていただきたいなというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"このデッキがつくられることで歩行者の動線がかなり変化すると思うんですが、こちらに関してはどのように予想しておられるんでしょうかという点と、あと、このデッキですけれども、建設費の補助金ですね、幾ら入っているのかということと、その算定根拠と考え方はどうなっているのかということをお伺いします。","respondent":"三宅都市開発課長","answer":"区役所方面、補助第１６３号線のほうに来る方ですとか、百反通り方面に抜ける方などを想定しております。それで、変更点といいますか、今は工事中でなかなか通りにくいというような構造がありますので、基本的には前と同じような流れであると考えております。","voiceIndex":55,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"すみません、ちょっとわからなかったんですけれども、委託金額が５億円で、標準レベルの橋だと１.３億円国から補助金が来るということですと、その残ったところがグレードアップ分ということなんでしょうか。それでいいのかということと、あと、何ていうんでしょうね、グレードアップ分の内訳ですけれども、そこに関してはどこがどれぐらい負担するのかという内訳があれば教えてください。","respondent":"三宅都市開発課長","answer":"そのグレードアップ分につきましては、例えば、じゃあ、グレードアップは何かといいますと、資料裏面の断面図にありますが、例えばひさしといいますか、屋根といいますか、例えばそういう部分でございまして、それにつきまして。","voiceIndex":57,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"なので、今度そういった変わることになった場合に、そういったところを十分に区としては気をつけていく必要があると思うんですが、そこに関しての、何ていうか、声は聞いているのか。そして、どういう対策を考えているのかお伺いします。","respondent":"岩田都市環境事業部長","answer":"道路を管理している部隊が聞いているお話は、再開発が完成した街区はゆったりとした歩道ができて、非常に安心して歩ける空間になってよかったと、こういう声は聞いておりますけれども、歩行者が危険であるというような声は私ども道路管理者のほうには来ておりません。","voiceIndex":59,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そういったのも、今回さらに環境が変わる可能性があるわけですけれども、その辺に関してはしっかりやはり調査というか、継続調査も行っているということですが、万全の体制で、歩行者第一で安全、特に高齢者の方が多い地域でもありますので、お願いしたいと思うんですけれども、そこら辺についての考えをお伺いします。","respondent":"岩田都市環境事業部長","answer":"これは信号がついても絶対的な安全は確保できないんです、信号というのは。これはたらればの世界で、ドライバーが信号を守ってくれれば、歩行者が赤信号でちゃんととまっていれば、こういう世界なんですね。","voiceIndex":61,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"信号機に関する考え方は、たらればとおっしゃいましたけれども、やはり信号機があることでドライバーは運転に注意するわけですから、先ほどもちょっとお考えは私は納得いかないんですが、やはり歩行者第一で考えるんであれば、必要なところにきちんと信号機をつけるというのは、それは当然のことだと思いますし、ぜひやっていただきたいと思います。","respondent":"岩田都市環境事業部長","answer":"信号機の設置権限は公安委員会が持っておりますので、状況を確認し、警察と順次そこら辺については検証してまいります。","voiceIndex":63,"id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"ちょっと教えてください。それから、もう１つ、ここのデッキの構造を私はうろ覚えなので伺うのですけれども、最後道に至るところというのは、これは高低差を利用して、何かそのままの高さで歩道に結ばれるんでしたっけ。それとも、スロープなのか、階段なのか、どういうふうに歩道と最後着地する形になっていくか教えてください。","respondent":"三宅都市開発課長","answer":"協定ですけれども、これは大本の平成１５年の基本協定があって、それは漠然とした協定です。","voiceIndex":66,"id":"exchange-020"},{"speaker":"阿部副委員長","kind":"確認","question":"すみません。一応これから結ぶという話であったら、やはり契約期間といったらいいですかね、いつごろからというのはご説明があってもよかったかなと思いますので、ごめんなさい、それが１件と、それから、そうすると、確認しますけれども、今回階段だけ、動線としてはバリアフリーには今回この動線はならないんですかね。","respondent":"三宅都市開発課長","answer":"協定締結の実施ですが、今回の本会議で議決をいただいて、速やかに締結する予定です。ちょっとすみません。ここの再開発事業の中のここ、遠くて申しわけございません、拡大図なんですけれども、ここに階段がございまして、ここから五、六ｍ先のところにつく予定になっております。","voiceIndex":68,"id":"exchange-021"},{"speaker":"阿部副委員長","kind":"質問","question":"すみません、今のエレベーターの件なんですが、要は公園のほうにまたデッキが少し伸びていって、エレベーターがつくということなんでしょうかね。いつごろになるんでしょうか。当然工事が順次進んでいくので、順位差があるのはわかるんですけれども、めどとしていつごろになったらエレベーターがつくんだよということがわかったほうがいいかなと。","respondent":"三宅都市開発課長","answer":"こちらの図で言うと、平面図でいきますと、薄い点線が伸びている下側ですね、ここに場所としてはつく予定でございまして、こちらは西口南地区の再開発事業の中でやりますので、一応完成の時期としては平成２５年の夏を予定しています。","voiceIndex":71,"id":"exchange-022"},{"speaker":"安藤委員","kind":"提案","question":"なので、私はこれをそのまま、このままで、もう少し住民の間の意見も取り入れてじっくり検討して進めるべきだという意見なんですが、そういった点で、あれですかね、建設委員会で具体的にこれから条例がかかると思うんですけれども、それというのは、条例改正が出てくるのはいつになるのか、その条例改正は、確かに区の都市計画審議会においては可決されましたけれども。","respondent":"三宅都市開発課長、松代都市計画課長、片田防災まちづくり事業部長","answer":"住民の意見を聞いてじっくり進めるべきというお話ですが、今都市計画がもしこのまま決定になりました場合につきましても、都市計画では外側の枠組み。事業説明会も含め、地域説明会も含め、そのほかいろいろな形をとりまして、この事業内容については説明をしてきておりますし、かつ。都市計画の中身は出しながら、そういうものは制限がありませんから、理念だけの話になりますので、ぜひともそれは条例の中で。","voiceIndex":78,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとこちら、私が今持ってきた区の都市計画審議会の意見書、当日出された資料の意見書の欄なんですけれども、ちょっと今回建設委員会に対する報告があまりにも、何かこう、こちらに比べて簡素じゃないかなと思いまして、賛成、反対というふうに並べていますけれども、それ以外にもこちらを見るとリアルに住民の方の声というか、状況、思いがわかるので、これをぜひ、これは、あと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"ただ、ベストなのはこれをつけていただければそれで済んだかもしれないんですが、それがないので、だったら建設委員としてこの報告を受けたときに、こういう住民の意見があるというときに、じゃあ、区はどういう見解を示しているんですかというのを、それは当然知ってしかるべきだと私は思いますけれども。ですから、ぜひご答弁を、当然答弁いただけるものだと思います。そう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"全内容ではありません。もっと本当は多いんですから。一部ですよ。抜粋ですよ。その抜粋に関する見解。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、報告を受けた上で、必要であれば議会としての意見が、注文をつけるではないが、決定権はないかもしれないですけれども、報告に対して、こちらは区民のことを代弁して要望する、なので、必要なところでぜひ答弁いただきたかったんです。でも、それはやるわけないというんであれば、ちょっとそれは置いておいて、次の質問に行きます。反対の意見ですよ。そちらが２点目の質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"そこで、持っている方は、出た方はここで同じことの蒸し返しの質問をしているようですけれども、私たちにはわかりません。第一、これは報告事項ですから、報告事項という仕切りの中で、この報告を受けましたということですから、ここでそういう問題を審議するんではないと思うんですよ。その辺はしっかり正副で仕切ってください。もう打ち切っていただいていいんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"私は報告事項ということがどうあるべきなのかというのは大いに議論の余地があるんじゃないかと思うんです。私はただ単に報告を受けるだけでは委員会の役目を果たせないんじゃないかなと、それが必要な報告に対して、やはり委員として、議論をしていくというのが大事だと思うんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"こっちは、何もここに書いていないことを質問したわけじゃないんですから、ここにばっちり書いていることで質問したんですから、何もそういう指摘は当たらないと思うんです。私はここの文章を全部読み上げたんですよ。こちらに書いてあることを言ったわけじゃないんですから。もちろんこっちの資料を出してもらったほうがいいなと思ったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-030"},{"speaker":"阿部副委員長","kind":"質問","question":"よろしいですか。ただ、今回については、これは都市計画審議会の、あるいは、都市計画審議会を含めた状況報告ですので、これはこれとして報告として伺っておき、また改めて機会をとらえて、この再開発事業についてはきちんと資料ももって議論をする場を別につくるというほうが私はすっきりするのではないかと、あるいは、実りある議論になるのではないかと考えていますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-031"},{"speaker":"市川委員","kind":"質問・要望","question":"１つだけ確認をさせていただきたいんですけれども、２週間の縦覧でこれだけ１９８通の賛成反対含めて意見が出たということなんで、かなりの何か、この再開発には関心を持っているんだなということを改めて感じているんですけれども、答申案の中にこういう意見は盛り込まれるものなんでしょうか。","respondent":"松代都市計画課長","answer":"答申案といいますか、今回６項目の地区計画の中の要件があります。それを、先ほど申し上げましたように、都が決定する事項、区が決定する事項というふうに分けて、今回審議いただいて、決定をいたしました。","voiceIndex":102,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"あわせまして、使用していた当該の少年野球関係者さんなどからは、改修やその後の運用に当たってはどのような要望が出ているのかお伺いします。","respondent":"齋藤道路公園課長、藤橋都市整備下水道課長","answer":"現行の使用状況についてご説明申し上げます。この公園は基本的に、一般的にどなたでも使える公園ですので、日中はお散歩されたり、子どもさんを連れられたりして、使用できます。もう１点目の野球をされている方等の声ということについてですけれども、これまで最終計画をつくるに当たりまして、地域の方、それから、利用者の方々を交えまして意見交換を行ってまいりました。","voiceIndex":109,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"少年野球の関係者の方から、先行して人工芝にした八潮北公園があったと思うんですけれども、運用後、スライディングをするとやけどをしてしまう問題や、あと、プロなどが通常使っている固定ベースではけがをしてしまうことが多いので、可動できるベースにしたんですけれども、それが八潮北公園は滑り過ぎて何か使い勝手がいまいちだという問題があると聞いたんですけれども、それは今回の整備で解決され。","respondent":"藤橋都市整備下水道課長","answer":"鮫洲運動公園につきましても、人工芝につきましては同様の芝の構造を採用するとともに、ここはいわゆる小学生以下をメインとしたところですので、各ベース、塁のところとマウンドについては土で残そうといった形で配慮して。","voiceIndex":112,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"八潮北のほうの使用の芝生でスライディングをしてやけどしてしまうという声が出ているので、それをそのまま持ってきたら、何か単純に全然あまり解決できないんじゃないかなと思うんですが、そこら辺はやはりしっかりした、やけどしないような質のものにしていただく必要があると思うんですけれども、それはどうなのかということと、あと、ちょっと答弁漏れがあったんですけれども、ベース回り。","respondent":"藤橋都市整備下水道課長、岩田都市環境事業部長","answer":"やけどについてですけれども、今回採用する予定の人工芝は八潮北も最新のタイプのものでございまして、滑ったときに少し温かくなるというような話はありますけれども、ここでやけどをしたという事例は、私のほうでは聞いていません。だから、５００円をいただくと、こういうことになっております。","voiceIndex":114,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に要望なんですが、利用している、していた、よく使っていた方のご意見をしっかりと伺って、壊す、整備に当たって、全面改修するわけですから、ぜひそういった声を活かしていけるような、そういう方向で努力をしていただきたいのと、あと、利用料に関しては、そういう事情をご説明いただいたんですけれども、これまでの経緯もやはりありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-036"},{"speaker":"阿部副委員長","kind":"質問","question":"遊戯コーナーについて幾つかお伺いします。一番下に、子どもたちにものをつくる楽しさを体験してもらうために、体験の場を検討しているということなんですけれども、この体験をするのはデザインした子どもたちを対象にということなんでしょうか。それとも、もうちょっと広く考えてらっしゃいますか。その意見をちょっと。","respondent":"藤橋都市整備下水道課長","answer":"私どものほうで今考えてありますのは、デザインを提案した３０人の子どもたちと地域の子どもたちを対象にする考えです。","voiceIndex":119,"id":"exchange-037"},{"speaker":"阿部副委員長","kind":"質問","question":"これも地図の読み方だと思うんですけれども、左側の木、丸っぽいのと、それから、左上のところと、両方ちょっと高さがあるといいますか、築山みたいな感じになっているようにも見られるんですが、確かに公園は今より見通しはよくなると思うんですけれども、築山タイプの公園というのは防犯上はむしろ危険なのでやめたほうがいいというような議論が。","respondent":"藤橋都市整備下水道課長","answer":"築山につきましては、山については今高さ１ｍ程度のものを考えてございまして、委員ご指摘のように、見通しの部分につきまして、今、例えばワイドすべり台工と書いてあるところは少し１ｍぐらいの高さになるんですけれども。","voiceIndex":121,"id":"exchange-038"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"乳幼児の遊び場はスペース的にはそんなに広くなくていいと思うんですけれども、どうなんでしょうね、これは私が保守的なのかもしれませんけれども、やはりあの年代は当たり前のちっちゃいシーソーみたいなのとか、ちょっと当たり前のちっちゃいブランコみたいなものは、結構やはり欲しいものではないかなと思うんですけれども、そういったものは、要望次第ではありますけれども。","respondent":"藤橋都市整備下水道課長","answer":"今のテーブルベンチ工は少し茶色で書いて丸くなっている部分の周りに点線で囲ってあって、名称は記入してございませんけれども、施設的にはいわゆる一般の公園にあるような、今委員がご指摘のようなちっちゃい幼児向け遊具を設置することも考えております。","voiceIndex":123,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"伺いたいことは公園のこと１件、あと、要望と、全体的な考え方等をちょっと３件伺います。遊戯公園のほうは立派な公園に相当なると思いますが、でき上がったあかつきには、開園時間とかはどうなりますかね。これは１つ質問です。それと、要望を１つ、グランドと遊戯コーナーの工事スケジュールがずれています。それと、全体的な、例えば公園改修ですとか、新設するときの考え方を伺いたいと思います。","respondent":"齋藤道路公園課長、藤橋都市整備下水道課長","answer":"週に３回障害者団体の方に清掃をお願いし、夏の間、ほこりが立つ間はシルバー人材センターの方にお願いして水まきをしていただいています。有料施設につきましては閉めますけれども、子どものアイディアを活かした北側部分の公園は閉める考えはありません。今向こうの課長が申し上げたとおり、維持管理等運営につきましては常々私どもと調整しておりまして、今説明したとおり、グランドにつきましては夜間閉鎖。","voiceIndex":127,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。もうたくさん声を聞いていただいて、いい公園をどんどんつくっていただきたいと思います。できたはいいけれども、また苦情が来ちゃって使えなくなるというのは、それは本当に一番怖いんで、もうそうならないように最大の努力をしていただければと思いますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-041"}]},{"id":"topic-02","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、ちょっと聞きたいことがあるんですけれども、せっかくこうやって格好よくしていただて、作成した視察報告書なんですけれども、ちょっとどれだけ作成されて、どこに置かれるものなのか、区民の皆さんがこれ見たいなと思った場合にはどういうふうにしたら見られるのかというのをちょっとお伺いしたいのと、あと、前回報告書作成の委員会の場で私はちょっと述べさせていただいたんですが。","respondent":"原委員長","answer":"理由はないです。私のほうから言います。余談ですがと書いてありましたので、余談であれば必要ないだろうという判断をいたしました。掲載場所ね。掲載場所は特にはありません。フォルダに入れて書庫にということになります。","voiceIndex":135,"id":"exchange-042"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"このエレベーターは住民要望が非常に高いバリアフリーですので質問させていただいたんですが、３月末までに工事着手したいということでしたけれども、工程的な制約も実はありまして、現在住民が利用している通路を閉鎖してしまう問題など、課題があると伺っているんですね。","respondent":"山崎マスタープラン担当課長","answer":"工事内容、エレベーター等の構造の件ですけれども、エレベーター設置計画の検討を現在行っている旨の報告は受けてあります。ただ、現時点では具体的な図面等が示されていないため、設置箇所等々につきましては不明です。","voiceIndex":141,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところですけれども、注文ということで、それは、何ていうんでしょう、そのバリアフリー計画そのものについてというか、周知や理解を住民の方に得られるよう要望するというのは、それはある意味当然やっていただかなくちゃいけない点なんですが、どういうようなエレベーターをつけてほしいとか、そういう中身に関しては特にないのか、あと、中身は図面が示されていないということなので。","respondent":"山崎マスタープラン担当課長","answer":"本件の区の考え方です。下神明駅にエレベーターが設置されることによりまして、高齢者や障害者等を含む利用者の移動の円滑化、利便性の向上が図られるもの、こういうふうに認識しています。","voiceIndex":143,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"今日も実は何か朝一で控室のほうに電話がかかってきて、住民の方から、どうなっているんですか、東急さんが全く教えてくれないんですけれども、というような、そういう電話を受けたんですけれどもね、やはりすごくその地域の方々にとっては切望していますし、どんなあれになるのかというのを気にしておられますので、１日も早く、最後の課長からの説明がありましたが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-045"},{"speaker":"阿部副委員長","kind":"質問","question":"今スケジュール、あるいは、内容というのはまだわからないということで、それはそういう段階なんだろうなと思うんですけれども、それはいつごろになるとめどが立つというようなめどというのはあるんでしょうかね。","respondent":"松代都市計画課長","answer":"当然その間には当委員会のほうにも、今後時期を見て説明をする、そういう段階を踏んでいきたいと、このように思っております。今のところはちょっとまだそこまで行っておりませんので、今後年内の早いうちにそういったものを詰めてきたいと、このように思っているわけです。","voiceIndex":147,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":43992,"voices":157}}]);
